          </div>

          {/* Hand Area */}
          <div className="flex-1 p-4 flex flex-col items-center justify-center relative bg-slate-800/50">
             <div className="absolute top-2 text-xs font-bold text-slate-500 uppercase tracking-widest">Your Hand</div>
             <div className="flex -space-x-2 pt-4">
                 {currentPlayer.hand.map((card, idx) => (
                     <div key={card.id} className="hover:-translate-y-4 hover:z-10 transition-transform duration-200">
                         <CardDisplay 
                            card={card} 
                            onClick={() => handleCardClick(card, 'HAND', currentPlayer.id)}
                            isSelected={gameState.selectedCardId === card.id}
                            isPlayable={
                                gameState.phase === Phase.MAIN && 
                                currentPlayer.resources.length >= card.cost // Simple check, ignored tapping logic for MVP
                            }
                         />
                     </div>
                 ))}
             </div>
          </div>

          {/* Resource & Actions */}
          <div className="w-80 p-4 border-l border-slate-800 flex flex-col gap-2">

             {/* Resources */}
             <div className="h-20 flex items-center gap-1 overflow-x-auto p-1 bg-slate-950/50 rounded mb-2">
                 {currentPlayer.resources.length === 0 && <span className="text-xs text-slate-600 w-full text-center">No Resources</span>}
                 {currentPlayer.resources.map(r => (
                     <div key={r.id} className="cursor-pointer hover:scale-110 transition" onClick={() => handleCardClick(r, 'RESOURCE', currentPlayer.id)}>
                         <CardDisplay card={r} size="sm" />
                     </div>
                 ))}
             </div>

             {/* Action Buttons */}
             <div className="flex-1 grid grid-cols-2 gap-2">
                 {gameState.phase === Phase.RESOURCE_START && (
                     <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center">
                            <ArrowUpCircle size={18} />
                            <span>Add & Draw</span>
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center">
                            <RotateCcw size={18} />
                            <span>Swap Res</span>
                        </button>
                     </>
                 )}

                 {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                     <div className="col-span-2 bg-slate-700 text-center text-xs p-2 rounded flex items-center justify-center animate-pulse">
                         Select a card from hand to add as Resource
                     </div>
                 )}

                 {gameState.phase === Phase.MAIN && (
                     <>
                        <button 
                            disabled={gameState.targetMode !== 'NONE' || currentPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)} 
                            className="bg-red-700 hover:bg-red-600 disabled:opacity-50 text-white rounded font-bold flex items-center justify-center gap-2"
                        >
                            <Sword size={16} /> Declare Attack
                        </button>
                        {gameState.selectedCardId ? (
                            <button onClick={handlePlayCard} className="bg-blue-600 hover:bg-blue-500 text-white rounded font-bold">
                                Play Selected
                            </button>
                        ) : (
                             <button onClick={endTurn} className="bg-slate-700 hover:bg-slate-600 text-white rounded font-bold">
                                End Turn
                            </button>
                        )}
                        {gameState.targetMode !== 'NONE' && (
                            <div className="col-span-2 text-center text-xs text-amber-300">Select target on field...</div>
                        )}
                     </>
                 )}

                 {gameState.phase === Phase.ATTACK_DECLARE && (
                     <button onClick={confirmAttack} className="col-span-2 bg-red-600 hover:bg-red-500 text-white rounded font-bold animate-pulse">
                         Confirm Attackers ({gameState.pendingAttackers.length})
                     </button>
                 )}

                 {gameState.phase === Phase.BLOCK_DECLARE && (
                     <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white rounded font-bold">
                         Confirm Blocks
                     </button>
                 )}
             </div>
          </div>

      </div>

      {/* Log Overlay */}
      <div className="absolute top-16 left-4 w-64 pointer-events-none">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/60 text-white text-xs mb-1 p-1 rounded shadow backdrop-blur-sm animate-in slide-in-from-left fade-in duration-300">
                  {log}
              </div>
          ))}
      </div>

    </div>
  );
};

