import { Card, Suit, Rank, Color, FieldCard } from './types';
import { CARD_VALUES } from './constants';

// Unique ID generator
export const generateId = () => Math.random().toString(36).substr(2, 9);

export const createDeck = (): Card[] => {
  const suits = [Suit.Spades, Suit.Clubs, Suit.Hearts, Suit.Diamonds];
  const ranks = Object.values(Rank);
  const deck: Card[] = [];

  for (const suit of suits) {
    for (const rank of ranks) {
      const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
      const numericValue = CARD_VALUES[rank];

      // Cost is equal to numeric value, except Ace=1, J=2, Q=3, K=4
      let cost = numericValue;
      if (rank === Rank.Jack) cost = 2;
      if (rank === Rank.Queen) cost = 3;
      if (rank === Rank.King) cost = 4;
      if (rank === Rank.Ace) cost = 1;

      deck.push({
        id: generateId(),
        suit,
        rank,
        numericValue,
        cost,
        baseColor
      });
    }
  }
  return shuffle(deck);
};

export const shuffle = <T>(array: T[]): T[] => {
  let currentIndex = array.length, randomIndex;
  while (currentIndex !== 0) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;
    [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
  }
  return array;
};

// Determine the EFFECTIVE color of a soldier (considering attached Queens)
export const getEffectiveColor = (fieldCard: FieldCard): Color => {
  // If a Queen is attached, the soldier takes the Queen's spectrum
  const attachedQueen = fieldCard.attachedCards.find(c => c.rank === Rank.Queen);
  if (attachedQueen) {
    return attachedQueen.baseColor;
  }
  return fieldCard.card.baseColor;
};

export const canBlock = (attacker: FieldCard, blocker: FieldCard): boolean => {
    // Must be in same lane (Same Effective Color)
    const attackerColor = getEffectiveColor(attacker);
    const blockerColor = getEffectiveColor(blocker);

    // Physical (Black) vs Physical (Black), Magical (Red) vs Magical (Red)
    return attackerColor === blockerColor;
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, Rank, Color, Suit } from './types';
import { createDeck, shuffle, getEffectiveColor, canBlock, generateId } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_HAND_SIZE, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, AlertCircle, Shield, Sword, RotateCcw, Check, User, Activity, Flame } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);

  // -- Initialization --

  const initGame = useCallback(() => {
    const fullDeck = createDeck();

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: Card[] = [];

      // Draw initial 8
      for(let i=0; i<8; i++) {
        const card = fullDeck.pop();
        if(card) hand.push(card);
      }

      // Automatically set 3 as resources (simple logic: take first 3, in real game user might choose, but rules say "set 3 aside", implies random or topdeck is fine for mvp, but usually user chooses. Let's pick lowest cost for AI simplicity or just random)
      // Rule: "Set 3 aside as face-up Resources". 
      for(let i=0; i<STARTING_RESOURCE_COUNT; i++) {
        const c = hand.shift();
        if(c) resources.push(c);
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    setGameState({
      deck: fullDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      logs: ["Game Started. Street Rules (Shared Deck)."]
    });

    // Start Upkeep immediately after init
    setTimeout(() => advancePhase(Phase.UPKEEP, {
        players: [p1, p2],
        turnPlayer: 0,
        deck: fullDeck,
        phase: Phase.INIT,
        turnCount: 1,
        pendingAttackers: [],
        pendingBlocks: {},
        selectedCardId: null,
        targetMode: 'NONE',
        sourceCardId: null,
        winner: null,
        logs: []
    }), 500);

  }, []);

  useEffect(() => {
    initGame();
  }, [initGame]);

  // -- Helper Functions --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActivePlayer = (state: GameState) => state.players[state.turnPlayer];
  const getOpponent = (state: GameState) => state.players[state.turnPlayer === 0 ? 1 : 0];

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, currentState: GameState = gameState!) => {
    setGameState(prev => {
      if (!prev) return null;
      let newState = { ...prev };

      // Override if we passed a specific current state (for init chain)
      if (currentState) newState = { ...currentState };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          // Untap all soldiers
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              c.isSummoningSick = false; // Sickness wears off at start of your turn (usually) or end of opponent. 
              // Rule: "Soldiers cannot attack the turn they are Conscripted." -> Sickness removed at start of owner's turn.
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          // Auto advance to Draw
          setTimeout(() => advancePhase(Phase.DRAW), 1000);
          break;

        case Phase.DRAW:
            // First Draw
            if (newState.deck.length > 0) {
                const card = newState.deck.shift();
                if (card) {
                    player.hand.push(card);
                    player.consecutiveDrawFailures = 0;
                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                }
            } else {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }
            // Auto advance to Resource Check
            setTimeout(() => advancePhase(Phase.RESOURCE_START), 500);
            break;

        case Phase.RESOURCE_START:
            // Check Skip conditions: Turn 1 Player 1 OR Max Resources
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, "Resource Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 500);
            } else {
                // Wait for user input
                newState.logs = addLog(newState, "Resource Step: Choose Action.");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             newState.logs = addLog(newState, `${getOpponent(newState).name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            resolveCombat(newState);
            break;

        case Phase.RESOURCE_ADD_SELECT:
        case Phase.RESOURCE_SWAP_SELECT_HAND:
        case Phase.RESOURCE_SWAP_SELECT_PILE:
            // Just UI state changes
            break;
      }

      return newState;
    });
  };

  const endTurn = () => {
    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        // Check deck out game over at end of turn? Rule says "consecutively unable to draw".
        // This is checked in Draw phase.

        return {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP
        };
    });
    // Trigger upkeep via effect or timeout handled in render/state change? 
    // Better to explicitly call advancePhase(UPKEEP) but we need the state update to settle.
    // We'll use a useEffect monitoring phase change? No, explicit timeout in the setter return is tricky.
    // Let's use a small timeout to call advancePhase from current scope.
    setTimeout(() => advancePhase(Phase.UPKEEP), 100);
  };

  // -- Interaction Handlers --

  // Resource Step Handling
  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') {
          advancePhase(Phase.RESOURCE_ADD_SELECT);
      } else {
          advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
      }
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const isMyTurn = gameState.turnPlayer === gameState.players[0].id; // Assuming Local MP, P1 is always "Me" visually, but let's handle generic
      const currentPlayer = gameState.players[gameState.turnPlayer];

      // -- Resource Management Interactions --
      if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          // Move to resource, draw card 2, go to main
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[prev.turnPlayer];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             if (cardIdx === -1) return prev;

             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(resCard);

             // Draw 2nd card
             if (prev.deck.length > 0) {
                 const draw = prev.deck.shift();
                 if(draw) p.hand.push(draw);
             } else {
                 p.consecutiveDrawFailures++;
             }

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: card.id,
              phase: Phase.RESOURCE_SWAP_SELECT_PILE,
              logs: addLog(prev!, "Select a resource to swap with.")
          }));
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[prev.turnPlayer];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.id === card.id);

              if(handIdx > -1 && resIdx > -1) {
                  const temp = p.hand[handIdx];
                  p.hand[handIdx] = p.resources[resIdx];
                  p.resources[resIdx] = temp;
              }

              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource. Skipped 2nd draw.") };
          });
      }

      // -- Main Phase: Playing Cards --
      else if (gameState.phase === Phase.MAIN && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: prev?.selectedCardId === card.id ? null : card.id
          }));
      }

      // -- Main Phase: Selecting Targets (Queen/King) --
      else if (gameState.phase === Phase.MAIN && location === 'FIELD' && gameState.targetMode !== 'NONE') {
          handleTargetSelection(instanceId!, ownerId);
      }

      // -- Attack Phase: Tapping Attackers --
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[prev.turnPlayer];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);

              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;

              // Toggle attack status
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking 
                  ? prev.pendingAttackers.filter(id => id !== instanceId)
                  : [...prev.pendingAttackers, instanceId!];

              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }

      // -- Block Phase: Assigning Blocks --
      else if (gameState.phase === Phase.BLOCK_DECLARE) {
          const opponentId = gameState.turnPlayer; // The one who IS attacking
          const blockerId = gameState.turnPlayer === 0 ? 1 : 0; // The one who IS blocking (current UI user?)
          // Wait, BLOCK_DECLARE phase: "Opponent chooses blocks". 
          // If I am Player 2 (Blocker), I click My Unit (Blocker) then Enemy Unit (Attacker).

          // Logic: Select Blocker (My Unit)
          if (ownerId !== gameState.turnPlayer && location === 'FIELD') { 
              // This is a defender's unit
              setGameState(prev => ({ ...prev!, selectedCardId: instanceId! }));
          }

          // Logic: Target Attacker (Enemy Unit)
          if (ownerId === gameState.turnPlayer && location === 'FIELD' && gameState.selectedCardId) {
              const attackerInstanceId = instanceId!;
              // Check if this unit is actually attacking
              if (!gameState.pendingAttackers.includes(attackerInstanceId)) return;

              // Try to block
              setGameState(prev => {
                  if(!prev) return null;
                  const defenderPlayer = prev.players[prev.turnPlayer === 0 ? 1 : 0];
                  const attackerPlayer = prev.players[prev.turnPlayer];

                  const blocker = defenderPlayer.field.find(f => f.instanceId === prev.selectedCardId);
                  const attacker = attackerPlayer.field.find(f => f.instanceId === attackerInstanceId);

                  if (!blocker || !attacker) return prev;
                  if (blocker.isTapped) return prev; // Should filter UI already

                  // Validate Color Match
                  if (!canBlock(attacker, blocker)) {
                      return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
                  }

                  // Check 1-to-1 rule: Is this attacker already blocked? 
                  const existingBlockerForAttacker = Object.keys(prev.pendingBlocks).find(key => prev.pendingBlocks[key] === attackerInstanceId);
                  if (existingBlockerForAttacker) {
                       // Replace block? Or deny? Rules say "One soldier may only block one other".
                       // Let's assume re-assigning is fine.
                       const newBlocks = { ...prev.pendingBlocks };
                       delete newBlocks[existingBlockerForAttacker]; // Remove old block
                       newBlocks[blocker.instanceId] = attackerInstanceId;
                       return { ...prev, pendingBlocks: newBlocks, selectedCardId: null, logs: addLog(prev, "Block declared.") };
                  }

                   // Is this blocker already blocking something?
                   if (prev.pendingBlocks[blocker.instanceId]) {
                        // Switch target
                       const newBlocks = { ...prev.pendingBlocks };
                       newBlocks[blocker.instanceId] = attackerInstanceId;
                       return { ...prev, pendingBlocks: newBlocks, selectedCardId: null, logs: addLog(prev, "Block switched.") };
                   }

                  return { 
                      ...prev, 
                      pendingBlocks: { ...prev.pendingBlocks, [blocker.instanceId]: attackerInstanceId }, 
                      selectedCardId: null,
                      logs: addLog(prev, "Block declared.")
                  };
              });
          }
      }
  };

  const handlePlayCard = () => {
      if (!gameState || !gameState.selectedCardId) return;

      const player = gameState.players[gameState.turnPlayer];
      const cardIdx = player.hand.findIndex(c => c.id === gameState.selectedCardId);
      if (cardIdx === -1) return;
      const card = player.hand[cardIdx];

      // Check Cost
      if (player.resources.length < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      // Soldier Logic
      if (!['J', 'Q', 'K'].includes(card.rank)) {
          // Play Soldier
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[prev.turnPlayer];
              p.hand.splice(cardIdx, 1);

              // Tap resources (Logic: simple check for amount. Complex logic: tap specific resources? 
              // Rules say "paying Resource cost". Doesn't explicitly say tap. 
              // Usually games imply tapping or spending. Since resources are cards, let's just count them. 
              // "Once a player reaches 10 Resources...". 
              // We won't remove resources. Just check count. 
              // WAIT - "Hiring a soldier by paying Resource cost". 
              // If resources aren't consumed/tapped, I can play infinite 2-drops with 2 resources? 
              // Standard TCG logic implies Tapping. I will implement Tapping of resources for the turn.)

              // Simplification for this prompt: Just check if Total Resources >= Cost. 
              // BUT, to prevent infinite plays, we need a "Available Resources" tracker or tap them.
              // Let's add `isTapped` to resources in PlayerState type implicitly by reusing Card type? No, Card type doesn't have isTapped.
              // Let's assume resources refresh each turn. We need to track `resourcesUsedThisTurn`.
              // *Modification:* I'll skip complex resource tapping for this MVP and assume "Pool" logic.
              // Actually, simpler: You have X resources. You can spend X per turn.

              // Let's rely on `currentResources` calculated property.
              // For now, I will NOT implement resource tapping visuals, but I will track mana pool in state if needed. 
              // Actually, standard Magic/Hearthstone logic is expected. 
              // Let's add `spentResources` to PlayerState?
              // No, let's keep it simple: Infinite resources for this demo or strict? 
              // Strict: Calculate `usedResources` this turn.
              // Let's add `resourcesAvailable` to `PlayerState` in `init` but that breaks type.
              // Let's just track `resourcesSpent` in player state? No.
              // Re-read: "Hiring a soldier by paying Resource cost".
              // Let's assume resources tap. I'll filter available resources in the play check.

          });
          // *RE-THINK*: Adding "isTapped" to resources is necessary for proper gameplay.
          // I will assume `resources` in PlayerState should be `FieldCard` or similar, or just cast Card to object with tap state. 
          // For now, I'll allow playing any number of cards if total resources >= cost. This is "Battle" (War) style? 
          // No, clearly a TCG. I will restrict based on "Spent" logic.
          // Let's create a temporary `resourcesSpent` in GameState to track usage this turn.
          // Actually, let's just use the `field` logic for resources too? No, different pile.
          // QUICK FIX: I will allow play if (Resources.length - CardsPlayedCostSum) >= Card.Cost.
          // This requires tracking cost sum. 
          // Let's just assume simple logic: You have X max resources.
      } 

      // Let's implement correct logic: 
      // Play Soldier -> Move to Field.
      // Play Tactic -> Execute Effect -> Discard.

      // Need to execute effects.
      if (card.rank === 'J') {
          // Draw 2
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[prev.turnPlayer];
              // Pay cost check (skipping for brevity, assuming UI handles validation)
              p.hand.splice(cardIdx, 1);
              p.discard.push(card);

              // Draw 2
              for(let i=0; i<2; i++){
                  if(prev.deck.length > 0) p.hand.push(prev.deck.shift()!);
              }
              return { ...prev, selectedCardId: null, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
          });
      }
      else if (card.rank === 'Q' || card.rank === 'K') {
          // Enter Target Mode
          setGameState(prev => ({
              ...prev!,
              targetMode: card.rank === 'Q' ? 'QUEEN' : 'KING',
              sourceCardId: card.id,
              logs: addLog(prev!, `Select target for ${card.rank === 'Q' ? 'Queen' : 'King'}.`)
          }));
      }
      else {
          // Soldier
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[prev.turnPlayer];
              p.hand.splice(cardIdx, 1);

              const newSoldier: FieldCard = {
                  instanceId: generateId(),
                  card: card,
                  ownerId: p.id,
                  isTapped: false,
                  isSummoningSick: true,
                  attachedCards: [],
                  currentHealth: card.numericValue
              };

              p.field.push(newSoldier);
              return { ...prev, selectedCardId: null, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
          });
      }
  };

  const handleTargetSelection = (targetInstanceId: string, targetOwnerId: number) => {
      setGameState(prev => {
          if (!prev || !prev.sourceCardId) return null;

          const p = prev.players[prev.turnPlayer];
          const handIdx = p.hand.findIndex(c => c.id === prev.sourceCardId);
          if (handIdx === -1) return prev;
          const tacticCard = p.hand[handIdx];

          const targetPlayer = prev.players[targetOwnerId];
          const targetCardIdx = targetPlayer.field.findIndex(fc => fc.instanceId === targetInstanceId);
          if (targetCardIdx === -1) return prev;
          const targetCard = targetPlayer.field[targetCardIdx];

          // King Logic
          if (tacticCard.rank === 'K') {
               // Must be same spectrum. 
               // King Red kills Red. King Black kills Black.
               // Check King color
               const kingColor = tacticCard.baseColor;
               const targetColor = getEffectiveColor(targetCard);

               if (kingColor !== targetColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: King can only execute same spectrum.") };
               }

               // Destroy
               p.hand.splice(handIdx, 1);
               p.discard.push(tacticCard);

               // Discard target and its attachments
               targetPlayer.field.splice(targetCardIdx, 1);
               targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);

               return { 
                   ...prev, 
                   targetMode: 'NONE', 
                   sourceCardId: null, 
                   selectedCardId: null,
                   logs: addLog(prev, "King executed a soldier.") 
               };
          }

          // Queen Logic
          if (tacticCard.rank === 'Q') {
              p.hand.splice(handIdx, 1);
              // Attach to soldier (move from hand to attachment array)
              targetCard.attachedCards.push(tacticCard);

              return {
                   ...prev, 
                   targetMode: 'NONE', 
                   sourceCardId: null, 
                   selectedCardId: null,
                   logs: addLog(prev, "Queen attached. Spectrum shifted.") 
              };
          }

          return prev;
      });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              // No attack? Just move to End/PostCombat
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") }; // Rules allow post-combat main. 
          }

          // Tap attackers
          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });

          p.hasAttackedThisTurn = true;

          return { 
              ...prev, 
              phase: Phase.BLOCK_DECLARE, 
              logs: addLog(prev, "Attack declared! Opponent blocking phase.") 
          };
      });
  };

  const confirmBlocks = () => {
      advancePhase(Phase.DAMAGE);
  };

  const resolveCombat = (state: GameState) => {
      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];

      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));
      let logBuffer: string[] = [];

      attackers.forEach(atk => {
          // Find blocker
          const blockerId = Object.keys(state.pendingBlocks).find(key => state.pendingBlocks[key] === atk.instanceId);

          if (blockerId) {
              const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
              if (blk) {
                  // Fight
                  const atkVal = atk.card.numericValue;
                  const blkVal = blk.card.numericValue;

                  const atkIsAce = atk.card.rank === 'A';
                  const blkIsAce = blk.card.rank === 'A';

                  let atkDies = false;
                  let blkDies = false;

                  // Slayer Logic
                  if (atkIsAce) blkDies = true;
                  if (blkIsAce) atkDies = true;

                  // Value Logic
                  if (!atkIsAce && !blkIsAce) {
                      if (atkVal > blkVal) blkDies = true;
                      else if (blkVal > atkVal) atkDies = true;
                      else { atkDies = true; blkDies = true; }
                  } else {
                      // Ace logic overrides value, but if Ace vs Non-Ace?
                      // Ace has value 1.
                      // Ace (1) vs 5. Ace dies (1<5) BUT Ace is Slayer, so 5 dies. Result: Both die.
                      // Matches logic above.
                      // Ace (1) vs Ace (1). Equal. Both die.
                      if(atkIsAce && !blkIsAce) atkDies = true; // Ace is weak
                      if(blkIsAce && !atkIsAce) blkDies = true; 
                  }

                  if (atkDies) {
                      attackerPlayer.field = attackerPlayer.field.filter(f => f.instanceId !== atk.instanceId);
                      attackerPlayer.discard.push(atk.card, ...atk.attachedCards);
                      logBuffer.push(`${atk.card.rank}${atk.card.suit} destroyed.`);
                  }
                  if (blkDies) {
                      defenderPlayer.field = defenderPlayer.field.filter(f => f.instanceId !== blk.instanceId);
                      defenderPlayer.discard.push(blk.card, ...blk.attachedCards);
                      logBuffer.push(`${blk.card.rank}${blk.card.suit} destroyed.`);
                  }
              }
          } else {
              // Unblocked
              const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
              defenderPlayer.life -= dmg;
              logBuffer.push(`${defenderPlayer.name} takes ${dmg} damage!`);
          }
      });

      state.logs = [...logBuffer.reverse(), ...state.logs].slice(0, 10);

      checkGameOver(state);

      // Move to Post-Combat Main
      setTimeout(() => {
          setGameState(prev => {
              if(!prev) return null;
              // Ensure we aren't in game over
              if (prev.phase === Phase.GAME_OVER) return prev;
              return { ...prev, phase: Phase.MAIN, pendingAttackers: [], pendingBlocks: {} };
          });
      }, 1500);
  };

  const checkGameOver = (state: GameState) => {
      // Life check
      if (state.players[0].life <= 0) state.winner = 1;
      else if (state.players[1].life <= 0) state.winner = 0;

      // Deck out tie breaker
      if (state.players[0].consecutiveDrawFailures > 0 && state.players[1].consecutiveDrawFailures > 0) {
          // Both failed to draw consecutively
          if (state.players[0].life > state.players[1].life) state.winner = 0;
          else if (state.players[1].life > state.players[0].life) state.winner = 1;
          else {
              // Field value check
              const p1Val = state.players[0].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              const p2Val = state.players[1].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              if (p1Val > p2Val) state.winner = 0;
              else if (p2Val > p1Val) state.winner = 1;
              else state.winner = -1; // Draw
          }
      }

      if (state.winner !== null) {
          state.phase = Phase.GAME_OVER;
      }
  };

  // -- Render Helpers --

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.RESOURCE_START: return "Resource Phase";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Declare Attacks";
        case Phase.BLOCK_DECLARE: return "Block Phase";
        case Phase.DAMAGE: return "Combat Resolution";
        default: return gameState?.phase || "";
    }
  };

  if (!gameState) return <div className="text-white">Loading...</div>;

  const currentPlayer = gameState.players[gameState.turnPlayer];
  const opponent = gameState.players[gameState.turnPlayer === 0 ? 1 : 0];
  const isMyTurn = true; // Local multiplayer, so always "My" turn effectively

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans">

      {/* Top Bar (Status) */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800">
        <div className="flex items-center gap-4">
           <div className="text-xl font-title font-bold text-indigo-400">BATTLE</div>
           <div className="text-sm text-slate-400">Turn {gameState.turnCount}</div>
           <div className="px-3 py-1 bg-indigo-900/50 rounded-full text-indigo-200 text-xs font-bold border border-indigo-700/50">
               {getPhaseName()}
           </div>
        </div>

        {/* Opponent Mini Status */}
        <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
                <div className="text-xs text-slate-400 uppercase tracking-widest">{opponent.name}</div>
                <div className="flex items-center gap-2">
                     <div className="flex items-center text-red-400 gap-1"><Activity size={14} /> {opponent.life}</div>
                     <div className="flex items-center text-blue-400 gap-1"><RotateCcw size={14} /> {opponent.resources.length}</div>
                     <div className="flex items-center text-amber-400 gap-1"><User size={14} /> {opponent.hand.length}</div>
                </div>
            </div>
        </div>
      </div>

      {/* Game Area */}
      <div className="flex-1 flex flex-col relative overflow-hidden">

         {/* Opponent Field (Top) */}
         <div className="flex-1 bg-slate-900/50 border-b border-slate-800/50 flex flex-col p-4">
             <div className="flex-1 flex justify-center gap-4 items-center">
                 {/* Opponent Hand (Face Down) */}
                 <div className="absolute top-2 right-4 flex -space-x-12 opacity-50 scale-75 origin-top-right">
                     {opponent.hand.map((c, i) => (
                         <CardDisplay key={c.id} card={c} showBack size="sm" />
                     ))}
                 </div>

                 {/* Lanes */}
                 <div className="flex gap-12 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 border-r border-slate-800 flex justify-center items-center gap-2 relative">
                         <div className="absolute top-0 left-0 text-slate-700 text-[10rem] opacity-5 pointer-events-none">♠</div>
                         {opponent.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <CardDisplay 
                                key={fc.instanceId} 
                                card={fc.card} 
                                isTapped={fc.isTapped}
                                isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                onClick={() => handleCardClick(fc.card, 'FIELD', opponent.id, fc.instanceId)}
                                isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && gameState.turnPlayer !== opponent.id)}
                             />
                         ))}
                     </div>
                     <div className="flex-1 flex justify-center items-center gap-2 relative">
                         <div className="absolute top-0 right-0 text-red-900 text-[10rem] opacity-5 pointer-events-none">♥</div>
                         {opponent.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <CardDisplay 
                                key={fc.instanceId} 
                                card={fc.card} 
                                isTapped={fc.isTapped}
                                isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                onClick={() => handleCardClick(fc.card, 'FIELD', opponent.id, fc.instanceId)}
                                isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && gameState.turnPlayer !== opponent.id)}
                             />
                         ))}
                     </div>
                 </div>
             </div>
         </div>

         {/* Center Info / Phase Indicator */}
         {gameState.phase === Phase.DAMAGE && (
             <div className="absolute inset-0 z-20 flex items-center justify-center bg-black/60 backdrop-blur-sm pointer-events-none">
                 <div className="text-4xl font-black text-red-500 animate-bounce font-title">COMBAT!</div>
             </div>
         )}

         {gameState.winner !== null && (
             <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md">
                 <div className="text-center">
                     <div className="text-6xl font-black text-amber-500 mb-4 font-title">
                         {gameState.winner === -1 ? "DRAW GAME" : `${gameState.players[gameState.winner].name} WINS!`}
                     </div>
                     <button 
                        onClick={initGame}
                        className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded font-bold shadow-lg transform hover:scale-105 transition"
                     >
                         Play Again
                     </button>
                 </div>
             </div>
         )}

         {/* Player Field (Bottom) */}
         <div className="flex-1 bg-slate-800/30 flex flex-col p-4">
             <div className="flex-1 flex justify-center gap-4 items-center h-full">
                 <div className="flex gap-12 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 border-r border-slate-800 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-0 left-0 text-slate-700 text-[10rem] opacity-5 pointer-events-none">♣</div>
                         {currentPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <CardDisplay 
                                key={fc.instanceId} 
                                card={fc.card} 
                                isTapped={fc.isTapped} 
                                isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                isBlocking={gameState.selectedCardId === fc.instanceId} // Selecting for block
                                onClick={() => handleCardClick(fc.card, 'FIELD', currentPlayer.id, fc.instanceId)}
                                isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                             />
                         ))}
                     </div>
                     <div className="flex-1 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-0 right-0 text-red-900 text-[10rem] opacity-5 pointer-events-none">♦</div>
                         {currentPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <CardDisplay 
                                key={fc.instanceId} 
                                card={fc.card} 
                                isTapped={fc.isTapped}
                                isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                isBlocking={gameState.selectedCardId === fc.instanceId} // Selecting for block
                                onClick={() => handleCardClick(fc.card, 'FIELD', currentPlayer.id, fc.instanceId)}
                                isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                             />
                         ))}
                     </div>
                 </div>
             </div>
         </div>
      </div>

      {/* Bottom Control Area */}
      <div className="h-48 bg-slate-900 border-t border-slate-800 flex">

          {/* Player Stats */}
          <div className="w-48 p-4 border-r border-slate-800 flex flex-col justify-between">
              <div>
                  <div className="text-xl font-bold text-indigo-300">{currentPlayer.name}</div>
                  <div className="text-xs text-slate-500 mb-2">Active Player</div>
                  <div className="flex items-center gap-2 text-2xl font-bold text-red-500">
                      <Activity /> {currentPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500">
                  Deck: {gameState.deck.length} cards
              </div>
          </div>

          {/* Hand Area */}
          <div className="flex-1 p-4 flex flex-col items-center justify-center relative bg-slate-800/50">
             <div className="absolute top-2 text-xs font-bold text-slate-500 uppercase tracking-widest">Your Hand</div>
             <div className="flex -space-x-2 pt-4">
                 {currentPlayer.hand.map((card, idx) => (
                     <div key={card.id} className="hover:-translate-y-4 hover:z-10 transition-transform duration-200">
                         <CardDisplay 
                            card={card} 
                            onClick={() => handleCardClick(card, 'HAND', currentPlayer.id)}
                            isSelected={gameState.selectedCardId === card.id}
                            isPlayable={
                                gameState.phase === Phase.MAIN && 
                                currentPlayer.resources.length >= card.cost // Simple check, ignored tapping logic for MVP
                            }
                         />
                     </div>
                 ))}
             </div>
          </div>

          {/* Resource & Actions */}
          <div className="w-80 p-4 border-l border-slate-800 flex flex-col gap-2">

             {/* Resources */}
             <div className="h-20 flex items-center gap-1 overflow-x-auto p-1 bg-slate-950/50 rounded mb-2">
                 {currentPlayer.resources.length === 0 && <span className="text-xs text-slate-600 w-full text-center">No Resources</span>}
                 {currentPlayer.resources.map(r => (
                     <div key={r.id} className="cursor-pointer hover:scale-110 transition" onClick={() => handleCardClick(r, 'RESOURCE', currentPlayer.id)}>
                         <CardDisplay card={r} size="sm" />
                     </div>
                 ))}
             </div>

             {/* Action Buttons */}
             <div className="flex-1 grid grid-cols-2 gap-2">
                 {gameState.phase === Phase.RESOURCE_START && (
                     <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center">
                            <ArrowUpCircle size={18} />
                            <span>Add & Draw</span>
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center">
                            <RotateCcw size={18} />
                            <span>Swap Res</span>
                        </button>
                     </>
                 )}

                 {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                     <div className="col-span-2 bg-slate-700 text-center text-xs p-2 rounded flex items-center justify-center animate-pulse">
                         Select a card from hand to add as Resource
                     </div>
                 )}

                 {gameState.phase === Phase.MAIN && (
                     <>
                        <button 
                            disabled={gameState.targetMode !== 'NONE' || currentPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)} 
                            className="bg-red-700 hover:bg-red-600 disabled:opacity-50 text-white rounded font-bold flex items-center justify-center gap-2"
                        >
                            <Sword size={16} /> Declare Attack
                        </button>
                        {gameState.selectedCardId ? (
                            <button onClick={handlePlayCard} className="bg-blue-600 hover:bg-blue-500 text-white rounded font-bold">
                                Play Selected
                            </button>
                        ) : (
                             <button onClick={endTurn} className="bg-slate-700 hover:bg-slate-600 text-white rounded font-bold">
                                End Turn
                            </button>
                        )}
                        {gameState.targetMode !== 'NONE' && (
                            <div className="col-span-2 text-center text-xs text-amber-300">Select target on field...</div>
                        )}
                     </>
                 )}

                 {gameState.phase === Phase.ATTACK_DECLARE && (
                     <button onClick={confirmAttack} className="col-span-2 bg-red-600 hover:bg-red-500 text-white rounded font-bold animate-pulse">
                         Confirm Attackers ({gameState.pendingAttackers.length})
                     </button>
                 )}

                 {gameState.phase === Phase.BLOCK_DECLARE && (
                     <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white rounded font-bold">
                         Confirm Blocks
                     </button>
                 )}
             </div>
          </div>

      </div>

      {/* Log Overlay */}
      <div className="absolute top-16 left-4 w-64 pointer-events-none">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/60 text-white text-xs mb-1 p-1 rounded shadow backdrop-blur-sm animate-in slide-in-from-left fade-in duration-300">
                  {log}
              </div>
          ))}
      </div>

    </div>
  );
};

export default App;

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
  baseColor: Color;
}

export interface FieldCard {
  instanceId: string;
  card: Card;
  ownerId: number;
  isTapped: boolean;
  isSummoningSick: boolean;
  attachedCards: Card[]; // For Queens
  currentHealth: number; // Usually equals attack, but for tracking state
}

export enum Phase {
  INIT = 'INIT',
  UPKEEP = 'UPKEEP',
  DRAW = 'DRAW',
  RESOURCE_START = 'RESOURCE_START',
  RESOURCE_ADD_SELECT = 'RESOURCE_ADD_SELECT',
  RESOURCE_SWAP_SELECT_HAND = 'RESOURCE_SWAP_SELECT_HAND',
  RESOURCE_SWAP_SELECT_PILE = 'RESOURCE_SWAP_SELECT_PILE',
  MAIN = 'MAIN',
  ATTACK_DECLARE = 'ATTACK_DECLARE',
  BLOCK_DECLARE = 'BLOCK_DECLARE',
  DAMAGE = 'DAMAGE',
  GAME_OVER = 'GAME_OVER',
}

export interface PlayerState {
  id: number;
  name: string;
  life: number;
  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: Card[];
  field: FieldCard[];
  discard: Card[];
  consecutiveDrawFailures: number;
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO';

export interface GameState {
  mode: GameMode;
  deck: Card[]; // Shared deck for Street mode
  players: PlayerState[];
  turnPlayer: number; // 0 or 1
  phase: Phase;
  turnCount: number;
  pendingAttackers: string[]; // instanceIds
  pendingBlocks: Record<string, string>; // blockerId -> attackerId
  selectedCardId: string | null; // For hand interaction
  targetMode: 'NONE' | 'QUEEN' | 'KING';
  sourceCardId: string | null; // The card initiating the target mode
  winner: number | null; // 0, 1, or -1 (Draw)
  logs: string[];
}

import React, { useState, useEffect, useCallback } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, User, Activity, Play, ShieldAlert, Swords } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    // For Street mode, we create one shared deck.
    // For Pro mode, we create individual decks for each player.

    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: Card[] = [];
      const library = mode === 'PRO' ? createDeck() : []; // Pro mode gets its own deck

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      // Draw initial 8
      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      // Set 3 resources
      for(let i=0; i<STARTING_RESOURCE_COUNT; i++) {
        const c = hand.shift();
        if(c) resources.push(c);
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      logs: [`Game Started. Mode: ${mode}`]
    };

    setGameState(initialState);

    // Start Upkeep immediately
    setTimeout(() => advancePhase(Phase.UPKEEP, initialState), 500);
  }, []);

  // -- Helper Functions --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, currentState: GameState = gameState!) => {
    setGameState(prev => {
      if (!prev) return null;
      let newState = { ...prev };

      if (currentState) newState = { ...currentState };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          // Untap all soldiers
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              // Remove summoning sickness if it's the player's turn
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 1000);
          break;

        case Phase.DRAW:
            // Handle Draw logic based on Mode
            let cardDrawn = false;
            let sourceDeck: Card[] = [];

            if (newState.mode === 'STREET') {
                sourceDeck = newState.deck;
            } else {
                sourceDeck = player.library;
            }

            if (sourceDeck.length > 0) {
                const card = sourceDeck.shift();
                if (card) {
                    player.hand.push(card);
                    player.consecutiveDrawFailures = 0;
                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                    cardDrawn = true;
                }
            }

            if (!cardDrawn) {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }

            // If game didn't end from deck out immediately
            if (newState.phase !== Phase.GAME_OVER) {
                setTimeout(() => advancePhase(Phase.RESOURCE_START), 500);
            }
            break;

        case Phase.RESOURCE_START:
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, "Resource Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 500);
            } else {
                newState.logs = addLog(newState, "Resource Step: Choose Action.");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             // Switch logic happens in render, but log it
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            resolveCombat(newState);
            break;
      }

      return newState;
    });
  };

  const endTurn = () => {
    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        return {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP
        };
    });
    setTimeout(() => advancePhase(Phase.UPKEEP), 100);
  };

  // -- Logic Handlers --

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') {
          advancePhase(Phase.RESOURCE_ADD_SELECT);
      } else {
          advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
      }
  };

  // A generic wrapper to handle "Active Player" logic
  // Returns the ID of the player currently making decisions
  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          // Defender acts
          return state.turnPlayer === 0 ? 1 : 0;
      }
      // Otherwise Turn Player acts
      return state.turnPlayer;
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;

      const activePlayerId = getActiveDecisionPlayerId(gameState);

      // Strict turn control: Only the active player can interact with their own hand/resources
      // Field interaction depends on phase (targeting etc)

      if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             if (cardIdx === -1) return prev;

             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(resCard);

             // Draw 2nd card
             let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
             if (sourceDeck.length > 0) {
                 const draw = sourceDeck.shift();
                 if(draw) p.hand.push(draw);
             } else {
                 p.consecutiveDrawFailures++;
             }

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: card.id,
              phase: Phase.RESOURCE_SWAP_SELECT_PILE,
              logs: addLog(prev!, "Select a resource to swap with.")
          }));
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE' && ownerId === activePlayerId) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.id === card.id);

              if(handIdx > -1 && resIdx > -1) {
                  const temp = p.hand[handIdx];
                  p.hand[handIdx] = p.resources[resIdx];
                  p.resources[resIdx] = temp;
              }

              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource. Skipped 2nd draw.") };
          });
      }

      // -- Main Phase: Playing Cards (Turn Player only) --
      else if (gameState.phase === Phase.MAIN && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: prev?.selectedCardId === card.id ? null : card.id
          }));
      }

      // -- Main Phase: Selecting Targets (Queen/King) --
      else if (gameState.phase === Phase.MAIN && location === 'FIELD' && gameState.targetMode !== 'NONE') {
          handleTargetSelection(instanceId!, ownerId);
      }

      // -- Attack Phase: Tapping Attackers (Turn Player only) --
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);

              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;

              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking 
                  ? prev.pendingAttackers.filter(id => id !== instanceId)
                  : [...prev.pendingAttackers, instanceId!];

              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }

      // -- Block Phase: Assigning Blocks (Defender only) --
      else if (gameState.phase === Phase.BLOCK_DECLARE) {
          // In this phase, activePlayerId is the Defender.
          // 1. Select My Unit (Blocker)
          if (ownerId === activePlayerId && location === 'FIELD') { 
              setGameState(prev => ({ ...prev!, selectedCardId: instanceId! }));
          }

          // 2. Click Enemy Unit (Attacker) to Block
          if (ownerId !== activePlayerId && location === 'FIELD' && gameState.selectedCardId) {
              const attackerInstanceId = instanceId!;
              if (!gameState.pendingAttackers.includes(attackerInstanceId)) return;

              setGameState(prev => {
                  if(!prev) return null;
                  const defenderPlayer = prev.players[activePlayerId];
                  const attackerPlayer = prev.players[activePlayerId === 0 ? 1 : 0];

                  const blocker = defenderPlayer.field.find(f => f.instanceId === prev.selectedCardId);
                  const attacker = attackerPlayer.field.find(f => f.instanceId === attackerInstanceId);

                  if (!blocker || !attacker) return prev;
                  if (blocker.isTapped) return prev;

                  if (!canBlock(attacker, blocker)) {
                      return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
                  }

                  // Check if attacker already blocked, reassign if needed
                  const existingBlockerForAttacker = Object.keys(prev.pendingBlocks).find(key => prev.pendingBlocks[key] === attackerInstanceId);
                  const newBlocks = { ...prev.pendingBlocks };

                  if (existingBlockerForAttacker) delete newBlocks[existingBlockerForAttacker];

                  // If this blocker was blocking something else, remove that link
                  newBlocks[blocker.instanceId] = attackerInstanceId;

                  return { 
                      ...prev, 
                      pendingBlocks: newBlocks, 
                      selectedCardId: null,
                      logs: addLog(prev, "Block declared.")
                  };
              });
          }
      }
  };

  const handlePlayCard = () => {
      if (!gameState || !gameState.selectedCardId) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);
      const player = gameState.players[activePlayerId];
      const cardIdx = player.hand.findIndex(c => c.id === gameState.selectedCardId);
      if (cardIdx === -1) return;
      const card = player.hand[cardIdx];

      if (player.resources.length < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      // Logic for Cards
      if (card.rank === 'J') {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              p.hand.splice(cardIdx, 1);
              p.discard.push(card);

              let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
              for(let i=0; i<2; i++){
                  if(sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
              }
              return { ...prev, selectedCardId: null, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
          });
      }
      else if (card.rank === 'Q' || card.rank === 'K') {
          setGameState(prev => ({
              ...prev!,
              targetMode: card.rank === 'Q' ? 'QUEEN' : 'KING',
              sourceCardId: card.id,
              logs: addLog(prev!, `Select target for ${card.rank === 'Q' ? 'Queen' : 'King'}.`)
          }));
      }
      else {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              p.hand.splice(cardIdx, 1);

              const newSoldier: FieldCard = {
                  instanceId: generateId(),
                  card: card,
                  ownerId: p.id,
                  isTapped: false,
                  isSummoningSick: true,
                  attachedCards: [],
                  currentHealth: card.numericValue
              };

              p.field.push(newSoldier);
              return { ...prev, selectedCardId: null, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
          });
      }
  };

  const handleTargetSelection = (targetInstanceId: string, targetOwnerId: number) => {
      setGameState(prev => {
          if (!prev || !prev.sourceCardId) return null;

          const p = prev.players[prev.turnPlayer];
          const handIdx = p.hand.findIndex(c => c.id === prev.sourceCardId);
          if (handIdx === -1) return prev;
          const tacticCard = p.hand[handIdx];

          const targetPlayer = prev.players[targetOwnerId];
          const targetCardIdx = targetPlayer.field.findIndex(fc => fc.instanceId === targetInstanceId);
          if (targetCardIdx === -1) return prev;
          const targetCard = targetPlayer.field[targetCardIdx];

          if (tacticCard.rank === 'K') {
               const kingColor = tacticCard.baseColor;
               const targetColor = getEffectiveColor(targetCard);
               if (kingColor !== targetColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: King can only execute same spectrum.") };
               }
               p.hand.splice(handIdx, 1);
               p.discard.push(tacticCard);

               targetPlayer.field.splice(targetCardIdx, 1);
               targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);

               return { ...prev, targetMode: 'NONE', sourceCardId: null, selectedCardId: null, logs: addLog(prev, "King executed a soldier.") };
          }

          if (tacticCard.rank === 'Q') {
              p.hand.splice(handIdx, 1);
              targetCard.attachedCards.push(tacticCard);
              return { ...prev, targetMode: 'NONE', sourceCardId: null, selectedCardId: null, logs: addLog(prev, "Queen attached. Spectrum shifted.") };
          }

          return prev;
      });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Attack declared! Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      advancePhase(Phase.DAMAGE);
  };

  const resolveCombat = (state: GameState) => {
      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];

      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));
      let logBuffer: string[] = [];

      attackers.forEach(atk => {
          const blockerId = Object.keys(state.pendingBlocks).find(key => state.pendingBlocks[key] === atk.instanceId);

          if (blockerId) {
              const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
              if (blk) {
                  const atkVal = atk.card.numericValue;
                  const blkVal = blk.card.numericValue;
                  const atkIsAce = atk.card.rank === 'A';
                  const blkIsAce = blk.card.rank === 'A';
                  let atkDies = false;
                  let blkDies = false;

                  if (atkIsAce) blkDies = true;
                  if (blkIsAce) atkDies = true;

                  if (!atkIsAce && !blkIsAce) {
                      if (atkVal > blkVal) blkDies = true;
                      else if (blkVal > atkVal) atkDies = true;
                      else { atkDies = true; blkDies = true; }
                  } else {
                      if(atkIsAce && !blkIsAce) atkDies = true;
                      if(blkIsAce && !atkIsAce) blkDies = true; 
                  }

                  if (atkDies) {
                      attackerPlayer.field = attackerPlayer.field.filter(f => f.instanceId !== atk.instanceId);
                      attackerPlayer.discard.push(atk.card, ...atk.attachedCards);
                      logBuffer.push(`${atk.card.rank}${atk.card.suit} destroyed.`);
                  }
                  if (blkDies) {
                      defenderPlayer.field = defenderPlayer.field.filter(f => f.instanceId !== blk.instanceId);
                      defenderPlayer.discard.push(blk.card, ...blk.attachedCards);
                      logBuffer.push(`${blk.card.rank}${blk.card.suit} destroyed.`);
                  }
              }
          } else {
              const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
              defenderPlayer.life -= dmg;
              logBuffer.push(`${defenderPlayer.name} takes ${dmg} damage!`);
          }
      });

      state.logs = [...logBuffer.reverse(), ...state.logs].slice(0, 10);
      checkGameOver(state);

      setTimeout(() => {
          setGameState(prev => {
              if(!prev) return null;
              if (prev.phase === Phase.GAME_OVER) return prev;
              return { ...prev, phase: Phase.MAIN, pendingAttackers: [], pendingBlocks: {} };
          });
      }, 1500);
  };

  const checkGameOver = (state: GameState) => {
      if (state.players[0].life <= 0) state.winner = 1;
      else if (state.players[1].life <= 0) state.winner = 0;

      if (state.players[0].consecutiveDrawFailures > 0 && state.players[1].consecutiveDrawFailures > 0) {
          if (state.players[0].life > state.players[1].life) state.winner = 0;
          else if (state.players[1].life > state.players[0].life) state.winner = 1;
          else {
              const p1Val = state.players[0].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              const p2Val = state.players[1].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              if (p1Val > p2Val) state.winner = 0;
              else if (p2Val > p1Val) state.winner = 1;
              else state.winner = -1;
          }
      }

      if (state.winner !== null) {
          state.phase = Phase.GAME_OVER;
      }
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- RENDER: TITLE SCREEN --
  if (!gameState) {
      return (
          <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans items-center justify-center relative overflow-hidden">
              <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-900 to-slate-950"></div>

              <div className="z-10 text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <div className="mb-8">
                      <h1 className="text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-br from-indigo-400 to-red-400 drop-shadow-2xl">
                          BATTLE
                      </h1>
                      <p className="text-slate-400 tracking-widest uppercase text-sm mt-2">Tactical Card Warfare</p>
                  </div>

                  <div className="flex gap-8">
                      <button 
                          onClick={() => startGame('STREET')}
                          className="group relative w-64 h-80 bg-slate-900 border-2 border-slate-700 hover:border-indigo-500 rounded-xl p-6 transition-all duration-300 hover:-translate-y-2 hover:shadow-2xl hover:shadow-indigo-500/20 flex flex-col items-center justify-between text-left"
                      >
                          <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/50 rounded-xl"></div>
                          <div className="z-10 w-full">
                              <Swords className="w-12 h-12 text-indigo-500 mb-4 group-hover:scale-110 transition" />
                              <h2 className="text-2xl font-bold text-white mb-2 font-title">Street Rules</h2>
                              <p className="text-sm text-slate-400 leading-relaxed">
                                  Shared 52-card deck. Resources are tight. Every draw counts. Chaos guaranteed.
                              </p>
                          </div>
                          <div className="z-10 w-full border-t border-slate-700 pt-4 flex justify-between items-center text-indigo-400 text-sm font-bold">
                              <span>Play Street</span>
                              <ArrowUpCircle className="rotate-90" size={16} />
                          </div>
                      </button>

                      <button 
                          onClick={() => startGame('PRO')}
                          className="group relative w-64 h-80 bg-slate-900 border-2 border-slate-700 hover:border-red-500 rounded-xl p-6 transition-all duration-300 hover:-translate-y-2 hover:shadow-2xl hover:shadow-red-500/20 flex flex-col items-center justify-between text-left"
                      >
                          <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/50 rounded-xl"></div>
                          <div className="z-10 w-full">
                              <ShieldAlert className="w-12 h-12 text-red-500 mb-4 group-hover:scale-110 transition" />
                              <h2 className="text-2xl font-bold text-white mb-2 font-title">Pro Rules</h2>
                              <p className="text-sm text-slate-400 leading-relaxed">
                                  Separate 52-card decks. Predictable resources. Pure strategy and deck management.
                              </p>
                          </div>
                          <div className="z-10 w-full border-t border-slate-700 pt-4 flex justify-between items-center text-red-400 text-sm font-bold">
                              <span>Play Pro</span>
                              <ArrowUpCircle className="rotate-90" size={16} />
                          </div>
                      </button>
                  </div>
              </div>

              <div className="absolute bottom-4 text-slate-600 text-xs">v1.0.0 Alpha</div>
          </div>
      );
  }

  // -- RENDER: GAME --

  // Perspective Logic:
  // If it is BLOCK_DECLARE, the Defender is making decisions, so they should be at the "Bottom" (Active View).
  // Otherwise, the Turn Player is at the "Bottom".
  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);

  // Bottom player is the one currently making moves
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  // Top player is the opponent relative to the active view
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans">

      {/* Top Bar (Status) */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
        <div className="flex items-center gap-4">
           <div className="text-xl font-title font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</div>
           <div className="h-6 w-px bg-slate-700"></div>
           <div className="flex flex-col leading-none">
               <span className="text-[10px] text-slate-500 uppercase font-bold">Round</span>
               <span className="text-sm font-bold text-slate-200">{gameState.turnCount}</span>
           </div>
           <div className="px-3 py-1 bg-slate-800 rounded border border-slate-700 text-slate-300 text-xs font-bold uppercase tracking-wide">
               {getPhaseName()}
           </div>
        </div>

        {/* Top Player Mini Status (Opponent of Active View) */}
        <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">{topPlayer.name}</div>
                <div className="flex items-center gap-3 bg-slate-800/50 px-3 py-1 rounded-full border border-slate-700">
                     <div className="flex items-center text-red-400 gap-1.5 font-bold"><Activity size={14} /> {topPlayer.life}</div>
                     <div className="w-px h-3 bg-slate-700"></div>
                     <div className="flex items-center text-blue-400 gap-1.5 font-bold"><RotateCcw size={14} /> {topPlayer.resources.length}</div>
                     <div className="w-px h-3 bg-slate-700"></div>
                     <div className="flex items-center text-amber-400 gap-1.5 font-bold"><User size={14} /> {topPlayer.hand.length}</div>
                </div>
            </div>
        </div>
      </div>

      {/* Game Area */}
      <div className="flex-1 flex flex-col relative overflow-hidden bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

         {/* Top Player Field */}
         <div className="flex-1 border-b border-slate-800/50 flex flex-col p-4 relative">
             <div className="flex-1 flex justify-center gap-4 items-center">
                 {/* Top Hand (Hidden) */}
                 <div className="absolute top-[-40px] right-4 flex -space-x-12 scale-75 origin-top-right transition-all hover:translate-y-4 z-10">
                     {topPlayer.hand.map((c, i) => (
                         <CardDisplay key={c.id} card={c} showBack size="sm" />
                     ))}
                 </div>

                 {/* Lanes */}
                 <div className="flex gap-8 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 bg-gradient-to-b from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative group">
                         <div className="absolute top-2 left-2 text-slate-700 text-6xl opacity-10 font-serif">♠</div>
                         {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                    // Allow clicking enemy units if active player is attacking (to view?) or blocking
                                    onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                    isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id)}
                                 />
                             </div>
                         ))}
                     </div>
                     <div className="flex-1 bg-gradient-to-b from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative group">
                         <div className="absolute top-2 right-2 text-red-900 text-6xl opacity-10 font-serif">♥</div>
                         {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                    onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                    isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id)}
                                 />
                             </div>
                         ))}
                     </div>
                 </div>
             </div>
         </div>

         {/* Center Info / Phase Indicator */}
         {gameState.phase === Phase.DAMAGE && (
             <div className="absolute inset-0 z-30 flex items-center justify-center bg-black/60 backdrop-blur-sm pointer-events-none">
                 <div className="text-6xl font-black text-red-500 animate-bounce font-title drop-shadow-[0_5px_5px_rgba(0,0,0,1)]">COMBAT!</div>
             </div>
         )}

         {gameState.winner !== null && (
             <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md">
                 <div className="text-center animate-in zoom-in duration-300">
                     <div className="text-7xl font-black text-amber-500 mb-6 font-title tracking-tight">
                         {gameState.winner === -1 ? "DRAW" : `${gameState.players[gameState.winner].name} WINS`}
                     </div>
                     <div className="flex gap-4 justify-center">
                        <button 
                            onClick={() => setGameState(null)}
                            className="px-8 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded font-bold shadow-lg transition"
                        >
                            Main Menu
                        </button>
                     </div>
                 </div>
             </div>
         )}

         {/* Bottom Player Field */}
         <div className="flex-1 flex flex-col p-4 relative">
             <div className="flex-1 flex justify-center gap-4 items-center h-full">
                 <div className="flex gap-8 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 bg-gradient-to-t from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-2 left-2 text-slate-700 text-6xl opacity-10 font-serif">♣</div>
                         {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped} 
                                    isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                    isBlocking={gameState.selectedCardId === fc.instanceId} 
                                    onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                    isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                 />
                             </div>
                         ))}
                     </div>
                     <div className="flex-1 bg-gradient-to-t from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-2 right-2 text-red-900 text-6xl opacity-10 font-serif">♦</div>
                         {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                    isBlocking={gameState.selectedCardId === fc.instanceId} 
                                    onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                    isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                 />
                             </div>
                         ))}
                     </div>
                 </div>
             </div>
         </div>
      </div>

      {/* Bottom Control Area */}
      <div className="h-52 bg-slate-900 border-t border-slate-800 flex shadow-[0_-10px_40px_rgba(0,0,0,0.5)] z-20">

          {/* Active Player Stats */}
          <div className="w-56 p-5 border-r border-slate-800 flex flex-col justify-between bg-slate-900">
              <div>
                  <div className="text-2xl font-title font-bold text-indigo-300 truncate">{bottomPlayer.name}</div>
                  <div className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Decision Maker</div>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500">
                      <Activity size={28} /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 font-mono">
                  {gameState.mode === 'STREET' ? 'Shared Deck' : 'Library'}: {gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}
              </div>
          </div>

          {/* Hand Area */}
          <div className="flex-1 p-4 flex flex-col items-center justify-center relative bg-slate-800/50 shadow-inner">
             <div className="absolute top-2 text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Current Hand</div>
             <div className="flex -space-x-4 pt-4 pb-2 px-8 overflow-visible">
                 {bottomPlayer.hand.map((card, idx) => (
                     <div key={card.id} className="hover:-translate-y-6 hover:scale-110 hover:z-20 transition-all duration-200 origin-bottom cursor-pointer">
                         <CardDisplay 
                            card={card} 
                            onClick={() => handleCardClick(card, 'HAND', bottomPlayer.id)}
                            isSelected={gameState.selectedCardId === card.id}
                            isPlayable={
                                gameState.phase === Phase.MAIN && 
                                bottomPlayer.resources.length >= card.cost
                            }
                         />
                     </div>
                 ))}
             </div>
          </div>

          {/* Resource & Actions */}
          <div className="w-80 p-4 border-l border-slate-800 flex flex-col gap-3 bg-slate-900">

             {/* Resources */}
             <div className="h-20 flex items-center gap-1 overflow-x-auto p-2 bg-black/40 rounded-lg shadow-inner">
                 {bottomPlayer.resources.length === 0 && <span className="text-xs text-slate-600 w-full text-center italic">No Resources</span>}
                 {bottomPlayer.resources.map(r => (
                     <div key={r.id} className="cursor-pointer hover:scale-110 hover:-translate-y-1 transition duration-200" onClick={() => handleCardClick(r, 'RESOURCE', bottomPlayer.id)}>
                         <CardDisplay card={r} size="sm" />
                     </div>
                 ))}
             </div>

             {/* Action Buttons */}
             <div className="flex-1 grid grid-cols-2 gap-2">
                 {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                     <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-700 hover:bg-emerald-600 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center transition shadow-lg border-b-2 border-emerald-900 active:border-b-0 active:translate-y-1">
                            <ArrowUpCircle size={18} className="mb-1" />
                            <span>Add & Draw</span>
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-700 hover:bg-amber-600 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center transition shadow-lg border-b-2 border-amber-900 active:border-b-0 active:translate-y-1">
                            <RotateCcw size={18} className="mb-1" />
                            <span>Swap Res</span>
                        </button>
                     </>
                 )}

                 {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                     <div className="col-span-2 bg-slate-700/50 border border-slate-600 text-slate-300 text-center text-xs p-2 rounded flex items-center justify-center animate-pulse font-bold">
                         Select card from hand to add
                     </div>
                 )}

                 {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                     <>
                        <button 
                            disabled={gameState.targetMode !== 'NONE' || bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)} 
                            className="bg-rose-700 hover:bg-rose-600 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded font-bold flex items-center justify-center gap-2 shadow-lg transition border-b-4 border-rose-900 active:border-b-0 active:translate-y-1"
                        >
                            <Sword size={18} /> Attack
                        </button>
                        {gameState.selectedCardId ? (
                            <button onClick={handlePlayCard} className="bg-indigo-600 hover:bg-indigo-500 text-white rounded font-bold shadow-lg transition border-b-4 border-indigo-900 active:border-b-0 active:translate-y-1">
                                Play Card
                            </button>
                        ) : (
                             <button onClick={endTurn} className="bg-slate-700 hover:bg-slate-600 text-white rounded font-bold shadow-lg transition border-b-4 border-slate-900 active:border-b-0 active:translate-y-1">
                                End Turn
                            </button>
                        )}
                        {gameState.targetMode !== 'NONE' && (
                            <div className="col-span-2 text-center text-xs text-amber-300 font-bold animate-pulse">Select target unit...</div>
                        )}
                     </>
                 )}

                 {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                     <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white rounded font-bold animate-pulse shadow-[0_0_15px_rgba(225,29,72,0.6)] transition border-b-4 border-rose-800 active:border-b-0 active:translate-y-1">
                         Confirm Attackers ({gameState.pendingAttackers.length})
                     </button>
                 )}

                 {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                     <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white rounded font-bold shadow-[0_0_15px_rgba(37,99,235,0.6)] transition border-b-4 border-blue-800 active:border-b-0 active:translate-y-1">
                         Confirm Blocks
                     </button>
                 )}
             </div>
          </div>

      </div>

      {/* Log Overlay */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/80 border-l-4 border-indigo-500 text-slate-200 text-xs mb-1.5 p-2 rounded-r shadow-lg backdrop-blur-md animate-in slide-in-from-left fade-in duration-300">
                  {log}
              </div>
          ))}
      </div>

    </div>
  );
};

export default App;

export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
  baseColor: Color;
}

export interface FieldCard {
  instanceId: string;
  card: Card;
  ownerId: number;
  isTapped: boolean;
  isSummoningSick: boolean;
  attachedCards: Card[]; // For Queens
  currentHealth: number; // Usually equals attack, but for tracking state
}

export enum Phase {
  INIT = 'INIT',
  INIT_SELECT = 'INIT_SELECT', // New phase for selecting starting resources
  UPKEEP = 'UPKEEP',
  DRAW = 'DRAW',
  RESOURCE_START = 'RESOURCE_START',
  RESOURCE_ADD_SELECT = 'RESOURCE_ADD_SELECT',
  RESOURCE_SWAP_SELECT_HAND = 'RESOURCE_SWAP_SELECT_HAND',
  RESOURCE_SWAP_SELECT_PILE = 'RESOURCE_SWAP_SELECT_PILE',
  MAIN = 'MAIN',
  ATTACK_DECLARE = 'ATTACK_DECLARE',
  BLOCK_DECLARE = 'BLOCK_DECLARE',
  DAMAGE = 'DAMAGE',
  GAME_OVER = 'GAME_OVER',
}

export interface PlayerState {
  id: number;
  name: string;
  life: number;
  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: FieldCard[]; // Changed from Card[] to FieldCard[] to support tapping
  field: FieldCard[];
  discard: Card[];
  consecutiveDrawFailures: number;
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO';

export interface GameState {
  mode: GameMode;
  deck: Card[]; // Shared deck for Street mode
  players: PlayerState[];
  turnPlayer: number; // 0 or 1
  phase: Phase;
  turnCount: number;
  pendingAttackers: string[]; // instanceIds
  pendingBlocks: Record<string, string>; // blockerId -> attackerId
  selectedCardId: string | null; // For hand interaction
  initSelectedIds: string[]; // For multi-selection during INIT_SELECT
  targetMode: 'NONE' | 'QUEEN' | 'KING';
  sourceCardId: string | null; // The card initiating the target mode
  winner: number | null; // 0, 1, or -1 (Draw)
  logs: string[];
}

import { Card, Suit, Rank, Color, FieldCard } from './types';
import { CARD_VALUES } from './constants';

// Unique ID generator
export const generateId = () => Math.random().toString(36).substr(2, 9);

export const createDeck = (): Card[] => {
  const suits = [Suit.Spades, Suit.Clubs, Suit.Hearts, Suit.Diamonds];
  const ranks = Object.values(Rank);
  const deck: Card[] = [];

  for (const suit of suits) {
    for (const rank of ranks) {
      const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
      const numericValue = CARD_VALUES[rank];

      // Cost is equal to numeric value, except Ace=1, J=2, Q=3, K=4
      let cost = numericValue;
      if (rank === Rank.Jack) cost = 2;
      if (rank === Rank.Queen) cost = 3;
      if (rank === Rank.King) cost = 4;
      if (rank === Rank.Ace) cost = 1;

      deck.push({
        id: generateId(),
        suit,
        rank,
        numericValue,
        cost,
        baseColor
      });
    }
  }
  return shuffle(deck);
};

export const shuffle = <T>(array: T[]): T[] => {
  let currentIndex = array.length, randomIndex;
  while (currentIndex !== 0) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;
    [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
  }
  return array;
};

// Determine the EFFECTIVE color of a soldier (considering attached Queens)
export const getEffectiveColor = (fieldCard: FieldCard): Color => {
  // If a Queen is attached, the soldier takes the Queen's spectrum
  const attachedQueen = fieldCard.attachedCards.find(c => c.rank === Rank.Queen);
  if (attachedQueen) {
    return attachedQueen.baseColor;
  }
  return fieldCard.card.baseColor;
};

export const canBlock = (attacker: FieldCard, blocker: FieldCard): boolean => {
    // Must be in same lane (Same Effective Color)
    const attackerColor = getEffectiveColor(attacker);
    const blockerColor = getEffectiveColor(blocker);

    // Physical (Black) vs Physical (Black), Magical (Red) vs Magical (Red)
    return attackerColor === blockerColor;
};

export const createFieldCard = (card: Card, ownerId: number): FieldCard => ({
  instanceId: generateId(),
  card,
  ownerId,
  isTapped: false,
  isSummoningSick: true,
  attachedCards: [],
  currentHealth: card.numericValue
});

import React, { useState, useEffect, useCallback } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, User, Activity, Play, ShieldAlert, Swords, AlertTriangle, X, Check } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      // Draw initial 8 cards
      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      // NO automatic resource selection. This happens in INIT_SELECT phase.

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT, // Start with selection
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, []);

  // -- Helper Functions --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, currentState: GameState = gameState!) => {
    setGameState(prev => {
      if (!prev) return null;
      let newState = { ...prev };

      if (currentState) newState = { ...currentState };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          // Untap all soldiers AND resources
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            // Untap resources for the turn player
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 1000);
          break;

        case Phase.DRAW:
            let cardDrawn = false;
            let sourceDeck: Card[] = [];

            if (newState.mode === 'STREET') {
                sourceDeck = newState.deck;
            } else {
                sourceDeck = player.library;
            }

            if (sourceDeck.length > 0) {
                const card = sourceDeck.shift();
                if (card) {
                    player.hand.push(card);
                    player.consecutiveDrawFailures = 0;
                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                    cardDrawn = true;
                }
            }

            if (!cardDrawn) {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }

            if (newState.phase !== Phase.GAME_OVER) {
                setTimeout(() => advancePhase(Phase.RESOURCE_START), 500);
            }
            break;

        case Phase.RESOURCE_START:
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, "Resource Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 500);
            } else {
                newState.logs = addLog(newState, "Resource Step: Add or Swap?");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            resolveCombat(newState);
            break;
      }

      return newState;
    });
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);
    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        return {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP
        };
    });
    setTimeout(() => advancePhase(Phase.UPKEEP), 100);
  };

  // -- Logic Handlers --

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') {
          advancePhase(Phase.RESOURCE_ADD_SELECT);
      } else {
          advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
      }
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  const handleConfirmInitSelection = () => {
      if (!gameState) return;
      const player = gameState.players[gameState.turnPlayer];

      if (gameState.initSelectedIds.length !== 3) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Must select exactly 3 cards.") }));
          return;
      }

      setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];

          // Move selected cards to resources
          // Filter carefully
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));

          p.hand = remainingHand;
          selectedCards.forEach(c => {
              p.resources.push(createFieldCard(c, p.id));
          });

          // Transition
          if (prev.turnPlayer === 0) {
              // Switch to Player 2 Init
              return { 
                  ...prev, 
                  turnPlayer: 1, 
                  initSelectedIds: [], 
                  logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") 
              };
          } else {
              // Both done, start game (Turn 1, P1)
              const startState = {
                  ...prev,
                  turnPlayer: 0,
                  initSelectedIds: [],
                  phase: Phase.UPKEEP,
                  logs: addLog(prev, "Game On! Player 1 Start.")
              };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
      });
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;

      // INIT SELECT LOGIC
      if (gameState.phase === Phase.INIT_SELECT) {
          if (ownerId !== gameState.turnPlayer || location !== 'HAND') return;

          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = [...prev.initSelectedIds];

              if (isSelected) {
                  newIds = newIds.filter(id => id !== card.id);
              } else {
                  if (newIds.length < 3) {
                      newIds.push(card.id);
                  }
              }
              return { ...prev, initSelectedIds: newIds };
          });
          return;
      }

      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             if (cardIdx === -1) return prev;

             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));

             // Draw 2nd card
             let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
             if (sourceDeck.length > 0) {
                 const draw = sourceDeck.shift();
                 if(draw) p.hand.push(draw);
             } else {
                 p.consecutiveDrawFailures++;
             }

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: card.id,
              phase: Phase.RESOURCE_SWAP_SELECT_PILE,
              logs: addLog(prev!, "Select a resource to swap with.")
          }));
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE' && ownerId === activePlayerId) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id); // Check card.id inside FieldCard

              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];

                  // Swap: Hand card becomes resource (untapped), Resource card becomes hand card
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); // New resource enters untapped usually? Or same state? Rules say "Swap". Usually enters untapped or same state. Let's assume untapped.
              }

              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource. Skipped 2nd draw.") };
          });
      }

      // -- Main Phase: Playing Cards (Turn Player only) --
      else if (gameState.phase === Phase.MAIN && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: prev?.selectedCardId === card.id ? null : card.id
          }));
      }

      // -- Main Phase: Selecting Targets (Queen/King) --
      else if (gameState.phase === Phase.MAIN && location === 'FIELD' && gameState.targetMode !== 'NONE') {
          handleTargetSelection(instanceId!, ownerId);
      }

      // -- Attack Phase: Tapping Attackers (Turn Player only) --
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);

              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;

              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking 
                  ? prev.pendingAttackers.filter(id => id !== instanceId)
                  : [...prev.pendingAttackers, instanceId!];

              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }

      // -- Block Phase: Assigning Blocks (Defender only) --
      else if (gameState.phase === Phase.BLOCK_DECLARE) {
          if (ownerId === activePlayerId && location === 'FIELD') { 
              setGameState(prev => ({ ...prev!, selectedCardId: instanceId! }));
          }

          if (ownerId !== activePlayerId && location === 'FIELD' && gameState.selectedCardId) {
              const attackerInstanceId = instanceId!;
              if (!gameState.pendingAttackers.includes(attackerInstanceId)) return;

              setGameState(prev => {
                  if(!prev) return null;
                  const defenderPlayer = prev.players[activePlayerId];
                  const attackerPlayer = prev.players[activePlayerId === 0 ? 1 : 0];

                  const blocker = defenderPlayer.field.find(f => f.instanceId === prev.selectedCardId);
                  const attacker = attackerPlayer.field.find(f => f.instanceId === attackerInstanceId);

                  if (!blocker || !attacker) return prev;
                  if (blocker.isTapped) return prev;

                  if (!canBlock(attacker, blocker)) {
                      return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
                  }

                  const existingBlockerForAttacker = Object.keys(prev.pendingBlocks).find(key => prev.pendingBlocks[key] === attackerInstanceId);
                  const newBlocks = { ...prev.pendingBlocks };

                  if (existingBlockerForAttacker) delete newBlocks[existingBlockerForAttacker];

                  newBlocks[blocker.instanceId] = attackerInstanceId;

                  return { 
                      ...prev, 
                      pendingBlocks: newBlocks, 
                      selectedCardId: null,
                      logs: addLog(prev, "Block declared.")
                  };
              });
          }
      }
  };

  const handlePlayCard = () => {
      if (!gameState || !gameState.selectedCardId) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);
      const player = gameState.players[activePlayerId];
      const cardIdx = player.hand.findIndex(c => c.id === gameState.selectedCardId);
      if (cardIdx === -1) return;
      const card = player.hand[cardIdx];

      // Resource Tapping Logic
      const untappedResources = player.resources.filter(r => !r.isTapped);
      if (untappedResources.length < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, `Not enough resources! Need ${card.cost}.`) }));
          return;
      }

      // Tap resources
      setGameState(prev => {
         if(!prev) return null;
         const p = prev.players[activePlayerId];

         // Mark cost amount as tapped
         let toTap = card.cost;
         for (const res of p.resources) {
             if (!res.isTapped && toTap > 0) {
                 res.isTapped = true;
                 toTap--;
             }
         }
         return { ...prev }; // update state to reflect tapped
      });

      // Logic for Cards
      if (card.rank === 'J') {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              p.hand.splice(cardIdx, 1);
              p.discard.push(card);

              let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
              for(let i=0; i<2; i++){
                  if(sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
              }
              return { ...prev, selectedCardId: null, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
          });
      }
      else if (card.rank === 'Q' || card.rank === 'K') {
          setGameState(prev => ({
              ...prev!,
              targetMode: card.rank === 'Q' ? 'QUEEN' : 'KING',
              sourceCardId: card.id,
              logs: addLog(prev!, `Select target for ${card.rank === 'Q' ? 'Queen' : 'King'}.`)
          }));
      }
      else {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              p.hand.splice(cardIdx, 1);

              const newSoldier = createFieldCard(card, p.id);

              p.field.push(newSoldier);
              return { ...prev, selectedCardId: null, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
          });
      }
  };

  const handleTargetSelection = (targetInstanceId: string, targetOwnerId: number) => {
      setGameState(prev => {
          if (!prev || !prev.sourceCardId) return null;

          const p = prev.players[prev.turnPlayer];
          const handIdx = p.hand.findIndex(c => c.id === prev.sourceCardId);
          if (handIdx === -1) return prev;
          const tacticCard = p.hand[handIdx];

          const targetPlayer = prev.players[targetOwnerId];
          const targetCardIdx = targetPlayer.field.findIndex(fc => fc.instanceId === targetInstanceId);
          if (targetCardIdx === -1) return prev;
          const targetCard = targetPlayer.field[targetCardIdx];

          if (tacticCard.rank === 'K') {
               const kingColor = tacticCard.baseColor;
               const targetColor = getEffectiveColor(targetCard);
               if (kingColor !== targetColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: King can only execute same spectrum.") };
               }
               p.hand.splice(handIdx, 1);
               p.discard.push(tacticCard);

               targetPlayer.field.splice(targetCardIdx, 1);
               targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);

               return { ...prev, targetMode: 'NONE', sourceCardId: null, selectedCardId: null, logs: addLog(prev, "King executed a soldier.") };
          }

          if (tacticCard.rank === 'Q') {
              p.hand.splice(handIdx, 1);
              targetCard.attachedCards.push(tacticCard);
              return { ...prev, targetMode: 'NONE', sourceCardId: null, selectedCardId: null, logs: addLog(prev, "Queen attached. Spectrum shifted.") };
          }

          return prev;
      });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Attack declared! Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      advancePhase(Phase.DAMAGE);
  };

  const resolveCombat = (state: GameState) => {
      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];

      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));
      let logBuffer: string[] = [];

      attackers.forEach(atk => {
          const blockerId = Object.keys(state.pendingBlocks).find(key => state.pendingBlocks[key] === atk.instanceId);

          if (blockerId) {
              const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
              if (blk) {
                  const atkVal = atk.card.numericValue;
                  const blkVal = blk.card.numericValue;
                  const atkIsAce = atk.card.rank === 'A';
                  const blkIsAce = blk.card.rank === 'A';
                  let atkDies = false;
                  let blkDies = false;

                  if (atkIsAce) blkDies = true;
                  if (blkIsAce) atkDies = true;

                  if (!atkIsAce && !blkIsAce) {
                      if (atkVal > blkVal) blkDies = true;
                      else if (blkVal > atkVal) atkDies = true;
                      else { atkDies = true; blkDies = true; }
                  } else {
                      if(atkIsAce && !blkIsAce) atkDies = true;
                      if(blkIsAce && !atkIsAce) blkDies = true; 
                  }

                  if (atkDies) {
                      attackerPlayer.field = attackerPlayer.field.filter(f => f.instanceId !== atk.instanceId);
                      attackerPlayer.discard.push(atk.card, ...atk.attachedCards);
                      logBuffer.push(`${atk.card.rank}${atk.card.suit} destroyed.`);
                  }
                  if (blkDies) {
                      defenderPlayer.field = defenderPlayer.field.filter(f => f.instanceId !== blk.instanceId);
                      defenderPlayer.discard.push(blk.card, ...blk.attachedCards);
                      logBuffer.push(`${blk.card.rank}${blk.card.suit} destroyed.`);
                  }
              }
          } else {
              const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
              defenderPlayer.life -= dmg;
              logBuffer.push(`${defenderPlayer.name} takes ${dmg} damage!`);
          }
      });

      state.logs = [...logBuffer.reverse(), ...state.logs].slice(0, 10);
      checkGameOver(state);

      setTimeout(() => {
          setGameState(prev => {
              if(!prev) return null;
              if (prev.phase === Phase.GAME_OVER) return prev;
              return { ...prev, phase: Phase.MAIN, pendingAttackers: [], pendingBlocks: {} };
          });
      }, 1500);
  };

  const checkGameOver = (state: GameState) => {
      if (state.players[0].life <= 0) state.winner = 1;
      else if (state.players[1].life <= 0) state.winner = 0;

      if (state.players[0].consecutiveDrawFailures > 0 && state.players[1].consecutiveDrawFailures > 0) {
          if (state.players[0].life > state.players[1].life) state.winner = 0;
          else if (state.players[1].life > state.players[0].life) state.winner = 1;
          else {
              const p1Val = state.players[0].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              const p2Val = state.players[1].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              if (p1Val > p2Val) state.winner = 0;
              else if (p2Val > p1Val) state.winner = 1;
              else state.winner = -1;
          }
      }

      if (state.winner !== null) {
          state.phase = Phase.GAME_OVER;
      }
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- RENDER: TITLE SCREEN --
  if (!gameState) {
      return (
          <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans items-center justify-center relative overflow-hidden">
              <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-900 to-slate-950"></div>

              <div className="z-10 text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <div className="mb-8">
                      <h1 className="text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-br from-indigo-400 to-red-400 drop-shadow-2xl">
                          BATTLE
                      </h1>
                      <p className="text-slate-400 tracking-widest uppercase text-sm mt-2">Tactical Card Warfare</p>
                  </div>

                  <div className="flex gap-8">
                      <button 
                          onClick={() => startGame('STREET')}
                          className="group relative w-64 h-80 bg-slate-900 border-2 border-slate-700 hover:border-indigo-500 rounded-xl p-6 transition-all duration-300 hover:-translate-y-2 hover:shadow-2xl hover:shadow-indigo-500/20 flex flex-col items-center justify-between text-left"
                      >
                          <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/50 rounded-xl"></div>
                          <div className="z-10 w-full">
                              <Swords className="w-12 h-12 text-indigo-500 mb-4 group-hover:scale-110 transition" />
                              <h2 className="text-2xl font-bold text-white mb-2 font-title">Street Rules</h2>
                              <p className="text-sm text-slate-400 leading-relaxed">
                                  Shared 52-card deck. Resources are tight. Every draw counts. Chaos guaranteed.
                              </p>
                          </div>
                          <div className="z-10 w-full border-t border-slate-700 pt-4 flex justify-between items-center text-indigo-400 text-sm font-bold">
                              <span>Play Street</span>
                              <ArrowUpCircle className="rotate-90" size={16} />
                          </div>
                      </button>

                      <button 
                          onClick={() => startGame('PRO')}
                          className="group relative w-64 h-80 bg-slate-900 border-2 border-slate-700 hover:border-red-500 rounded-xl p-6 transition-all duration-300 hover:-translate-y-2 hover:shadow-2xl hover:shadow-red-500/20 flex flex-col items-center justify-between text-left"
                      >
                          <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/50 rounded-xl"></div>
                          <div className="z-10 w-full">
                              <ShieldAlert className="w-12 h-12 text-red-500 mb-4 group-hover:scale-110 transition" />
                              <h2 className="text-2xl font-bold text-white mb-2 font-title">Pro Rules</h2>
                              <p className="text-sm text-slate-400 leading-relaxed">
                                  Separate 52-card decks. Predictable resources. Pure strategy and deck management.
                              </p>
                          </div>
                          <div className="z-10 w-full border-t border-slate-700 pt-4 flex justify-between items-center text-red-400 text-sm font-bold">
                              <span>Play Pro</span>
                              <ArrowUpCircle className="rotate-90" size={16} />
                          </div>
                      </button>
                  </div>
              </div>

              <div className="absolute bottom-4 text-slate-600 text-xs">v1.0.0 Alpha</div>
          </div>
      );
  }

  // -- RENDER: GAME --

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans">

      {/* End Turn Confirmation Modal */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[60] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <div className="flex items-center gap-3 text-amber-500 mb-4">
                      <AlertTriangle size={24} />
                      <h3 className="text-xl font-bold font-title">End Turn?</h3>
                  </div>
                  <p className="text-slate-400 mb-6">Are you sure you want to end your turn? You cannot play any more cards until your next turn.</p>
                  <div className="flex gap-3 justify-end">
                      <button 
                          onClick={() => setShowEndTurnModal(false)}
                          className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded font-bold transition flex items-center gap-2"
                      >
                          <X size={16} /> Cancel
                      </button>
                      <button 
                          onClick={confirmEndTurn}
                          className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded font-bold transition flex items-center gap-2"
                      >
                          <Check size={16} /> Confirm
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Top Bar (Status) */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
        <div className="flex items-center gap-4">
           <div className="text-xl font-title font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</div>
           <div className="h-6 w-px bg-slate-700"></div>
           <div className="flex flex-col leading-none">
               <span className="text-[10px] text-slate-500 uppercase font-bold">Round</span>
               <span className="text-sm font-bold text-slate-200">{gameState.turnCount}</span>
           </div>
           <div className="px-3 py-1 bg-slate-800 rounded border border-slate-700 text-slate-300 text-xs font-bold uppercase tracking-wide">
               {getPhaseName()}
           </div>
        </div>

        <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">{topPlayer.name}</div>
                <div className="flex items-center gap-3 bg-slate-800/50 px-3 py-1 rounded-full border border-slate-700">
                     <div className="flex items-center text-red-400 gap-1.5 font-bold"><Activity size={14} /> {topPlayer.life}</div>
                     <div className="w-px h-3 bg-slate-700"></div>
                     <div className="flex items-center text-blue-400 gap-1.5 font-bold"><RotateCcw size={14} /> {topPlayer.resources.length}</div>
                     <div className="w-px h-3 bg-slate-700"></div>
                     <div className="flex items-center text-amber-400 gap-1.5 font-bold"><User size={14} /> {topPlayer.hand.length}</div>
                </div>
            </div>
        </div>
      </div>

      {/* Game Area */}
      <div className="flex-1 flex flex-col relative overflow-hidden bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

         {/* Top Player Field */}
         <div className="flex-1 border-b border-slate-800/50 flex flex-col p-4 relative">
             <div className="flex-1 flex justify-center gap-4 items-center">
                 {/* Top Hand (Hidden) */}
                 <div className="absolute top-[-40px] right-4 flex -space-x-12 scale-75 origin-top-right transition-all hover:translate-y-4 z-10">
                     {topPlayer.hand.map((c, i) => (
                         <CardDisplay key={c.id} card={c} showBack size="sm" />
                     ))}
                 </div>

                 {/* Lanes */}
                 <div className="flex gap-8 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 bg-gradient-to-b from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative group">
                         <div className="absolute top-2 left-2 text-slate-700 text-6xl opacity-10 font-serif">♠</div>
                         {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                    onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                    isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id)}
                                 />
                             </div>
                         ))}
                     </div>
                     <div className="flex-1 bg-gradient-to-b from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative group">
                         <div className="absolute top-2 right-2 text-red-900 text-6xl opacity-10 font-serif">♥</div>
                         {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                    onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                    isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id)}
                                 />
                             </div>
                         ))}
                     </div>
                 </div>
             </div>
         </div>

         {/* Center Info / Phase Indicator */}
         {gameState.phase === Phase.DAMAGE && (
             <div className="absolute inset-0 z-30 flex items-center justify-center bg-black/60 backdrop-blur-sm pointer-events-none">
                 <div className="text-6xl font-black text-red-500 animate-bounce font-title drop-shadow-[0_5px_5px_rgba(0,0,0,1)]">COMBAT!</div>
             </div>
         )}

         {gameState.winner !== null && (
             <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md">
                 <div className="text-center animate-in zoom-in duration-300">
                     <div className="text-7xl font-black text-amber-500 mb-6 font-title tracking-tight">
                         {gameState.winner === -1 ? "DRAW" : `${gameState.players[gameState.winner].name} WINS`}
                     </div>
                     <div className="flex gap-4 justify-center">
                        <button 
                            onClick={() => setGameState(null)}
                            className="px-8 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded font-bold shadow-lg transition"
                        >
                            Main Menu
                        </button>
                     </div>
                 </div>
             </div>
         )}

         {/* Bottom Player Field */}
         <div className="flex-1 flex flex-col p-4 relative">
             <div className="flex-1 flex justify-center gap-4 items-center h-full">
                 <div className="flex gap-8 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 bg-gradient-to-t from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-2 left-2 text-slate-700 text-6xl opacity-10 font-serif">♣</div>
                         {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped} 
                                    isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                    isBlocking={gameState.selectedCardId === fc.instanceId} 
                                    onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                    isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                 />
                             </div>
                         ))}
                     </div>
                     <div className="flex-1 bg-gradient-to-t from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-2 right-2 text-red-900 text-6xl opacity-10 font-serif">♦</div>
                         {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                    isBlocking={gameState.selectedCardId === fc.instanceId} 
                                    onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                    isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                 />
                             </div>
                         ))}
                     </div>
                 </div>
             </div>
         </div>
      </div>

      {/* Bottom Control Area */}
      <div className="h-52 bg-slate-900 border-t border-slate-800 flex shadow-[0_-10px_40px_rgba(0,0,0,0.5)] z-20">

          {/* Active Player Stats */}
          <div className="w-56 p-5 border-r border-slate-800 flex flex-col justify-between bg-slate-900">
              <div>
                  <div className="text-2xl font-title font-bold text-indigo-300 truncate">{bottomPlayer.name}</div>
                  <div className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Decision Maker</div>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500">
                      <Activity size={28} /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 font-mono">
                  {gameState.mode === 'STREET' ? 'Shared Deck' : 'Library'}: {gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}
              </div>
          </div>

          {/* Hand Area */}
          <div className="flex-1 p-4 flex flex-col items-center justify-center relative bg-slate-800/50 shadow-inner">
             <div className="absolute top-2 text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Current Hand</div>
             <div className="flex -space-x-4 pt-4 pb-2 px-8 overflow-visible">
                 {bottomPlayer.hand.map((card, idx) => {
                     const isSelectedForInit = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(card.id);
                     return (
                         <div key={card.id} className={`hover:-translate-y-6 hover:scale-110 hover:z-20 transition-all duration-200 origin-bottom cursor-pointer ${isSelectedForInit ? '-translate-y-6 z-10' : ''}`}>
                             <CardDisplay 
                                card={card} 
                                onClick={() => handleCardClick(card, 'HAND', bottomPlayer.id)}
                                isSelected={gameState.selectedCardId === card.id || isSelectedForInit}
                                isPlayable={
                                    gameState.phase === Phase.MAIN && 
                                    bottomPlayer.resources.filter(r => !r.isTapped).length >= card.cost
                                }
                             />
                         </div>
                     );
                 })}
             </div>
          </div>

          {/* Resource & Actions */}
          <div className="w-80 p-4 border-l border-slate-800 flex flex-col gap-3 bg-slate-900">

             {/* Resources */}
             <div className="h-20 flex items-center gap-1 overflow-x-auto p-2 bg-black/40 rounded-lg shadow-inner">
                 {bottomPlayer.resources.length === 0 && <span className="text-xs text-slate-600 w-full text-center italic">No Resources</span>}
                 {bottomPlayer.resources.map(r => (
                     <div key={r.instanceId} className="cursor-pointer hover:scale-110 hover:-translate-y-1 transition duration-200" onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id)}>
                         <CardDisplay card={r.card} size="sm" isTapped={r.isTapped} />
                     </div>
                 ))}
             </div>

             {/* Action Buttons */}
             <div className="flex-1 grid grid-cols-2 gap-2">
                 {/* Init Phase Actions */}
                 {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                     <div className="col-span-2 flex flex-col gap-2">
                         <div className="text-center text-xs text-slate-400">Select 3 cards for Resources</div>
                         <button 
                            disabled={gameState.initSelectedIds.length !== 3}
                            onClick={handleConfirmInitSelection}
                            className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded p-2 font-bold shadow-lg transition"
                        >
                             Confirm Selection ({gameState.initSelectedIds.length}/3)
                         </button>
                     </div>
                 )}

                 {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                     <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-700 hover:bg-emerald-600 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center transition shadow-lg border-b-2 border-emerald-900 active:border-b-0 active:translate-y-1">
                            <ArrowUpCircle size={18} className="mb-1" />
                            <span>Add & Draw</span>
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-700 hover:bg-amber-600 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center transition shadow-lg border-b-2 border-amber-900 active:border-b-0 active:translate-y-1">
                            <RotateCcw size={18} className="mb-1" />
                            <span>Swap Res</span>
                        </button>
                     </>
                 )}

                 {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                     <div className="col-span-2 bg-slate-700/50 border border-slate-600 text-slate-300 text-center text-xs p-2 rounded flex items-center justify-center animate-pulse font-bold">
                         Select card from hand to add
                     </div>
                 )}

                 {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                     <>
                        <button 
                            disabled={gameState.targetMode !== 'NONE' || bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)} 
                            className="bg-rose-700 hover:bg-rose-600 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded font-bold flex items-center justify-center gap-2 shadow-lg transition border-b-4 border-rose-900 active:border-b-0 active:translate-y-1"
                        >
                            <Sword size={18} /> Attack
                        </button>
                        {gameState.selectedCardId ? (
                            <button onClick={handlePlayCard} className="bg-indigo-600 hover:bg-indigo-500 text-white rounded font-bold shadow-lg transition border-b-4 border-indigo-900 active:border-b-0 active:translate-y-1">
                                Play Card
                            </button>
                        ) : (
                             <button onClick={requestEndTurn} className="bg-slate-700 hover:bg-slate-600 text-white rounded font-bold shadow-lg transition border-b-4 border-slate-900 active:border-b-0 active:translate-y-1">
                                End Turn
                            </button>
                        )}
                        {gameState.targetMode !== 'NONE' && (
                            <div className="col-span-2 text-center text-xs text-amber-300 font-bold animate-pulse">Select target unit...</div>
                        )}
                     </>
                 )}

                 {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                     <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white rounded font-bold animate-pulse shadow-[0_0_15px_rgba(225,29,72,0.6)] transition border-b-4 border-rose-800 active:border-b-0 active:translate-y-1">
                         Confirm Attackers ({gameState.pendingAttackers.length})
                     </button>
                 )}

                 {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                     <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white rounded font-bold shadow-[0_0_15px_rgba(37,99,235,0.6)] transition border-b-4 border-blue-800 active:border-b-0 active:translate-y-1">
                         Confirm Blocks
                     </button>
                 )}
             </div>
          </div>

      </div>

      {/* Log Overlay */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/80 border-l-4 border-indigo-500 text-slate-200 text-xs mb-1.5 p-2 rounded-r shadow-lg backdrop-blur-md animate-in slide-in-from-left fade-in duration-300">
                  {log}
              </div>
          ))}
      </div>

    </div>
  );
};

export default App;

export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
  baseColor: Color;
}

export interface FieldCard {
  instanceId: string;
  card: Card;
  ownerId: number;
  isTapped: boolean;
  isSummoningSick: boolean;
  attachedCards: Card[]; // For Queens
  currentHealth: number; // Usually equals attack, but for tracking state
}

export enum Phase {
  INIT = 'INIT',
  INIT_SELECT = 'INIT_SELECT', // New phase for selecting starting resources
  UPKEEP = 'UPKEEP',
  DRAW = 'DRAW',
  RESOURCE_START = 'RESOURCE_START',
  RESOURCE_ADD_SELECT = 'RESOURCE_ADD_SELECT',
  RESOURCE_SWAP_SELECT_HAND = 'RESOURCE_SWAP_SELECT_HAND',
  RESOURCE_SWAP_SELECT_PILE = 'RESOURCE_SWAP_SELECT_PILE',
  MAIN = 'MAIN',
  ATTACK_DECLARE = 'ATTACK_DECLARE',
  BLOCK_DECLARE = 'BLOCK_DECLARE',
  DAMAGE = 'DAMAGE',
  GAME_OVER = 'GAME_OVER',
}

export interface PlayerState {
  id: number;
  name: string;
  life: number;
  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: FieldCard[]; // Changed from Card[] to FieldCard[] to support tapping
  field: FieldCard[];
  discard: Card[];
  consecutiveDrawFailures: number;
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO';

export interface GameState {
  mode: GameMode;
  deck: Card[]; // Shared deck for Street mode
  players: PlayerState[];
  turnPlayer: number; // 0 or 1
  phase: Phase;
  turnCount: number;
  pendingAttackers: string[]; // instanceIds
  pendingBlocks: Record<string, string>; // blockerId -> attackerId
  selectedCardId: string | null; // For hand interaction
  initSelectedIds: string[]; // For multi-selection during INIT_SELECT
  targetMode: 'NONE' | 'QUEEN' | 'KING';
  sourceCardId: string | null; // The card initiating the target mode
  winner: number | null; // 0, 1, or -1 (Draw)
  recentDamage: Record<string, number>; // Maps instanceId (or 'P0'/'P1') to damage taken this phase
  logs: string[];
}

import React from 'react';
import { Card, Suit, Color, FieldCard } from '../types';
import { SUIT_COLORS } from '../constants';

interface CardDisplayProps {
  card: Card;
  onClick?: () => void;
  isSelected?: boolean;
  isTapped?: boolean;
  isPlayable?: boolean;
  isTargetable?: boolean;
  isAttacking?: boolean;
  isBlocking?: boolean;
  attachedTo?: FieldCard; // If this is a queen attached to something
  damageTaken?: number; // Visual only
  size?: 'sm' | 'md' | 'lg';
  showBack?: boolean;
}

export const CardDisplay: React.FC<CardDisplayProps> = ({
  card,
  onClick,
  isSelected,
  isTapped,
  isPlayable,
  isTargetable,
  isAttacking,
  isBlocking,
  damageTaken,
  size = 'md',
