    sm: 'w-12 h-16 text-xs rounded-sm',
    md: 'w-20 h-28 text-sm rounded',
    lg: 'w-32 h-44 text-lg rounded-md',
  };

  // Lunging animation logic
  // If bottom player lunges, they move UP (negative Y)
  // If top player lunges, they move DOWN (positive Y)
  const lungeClass = isLunging 
    ? (orientation === 'bottom' ? '-translate-y-24 scale-125 z-50 shadow-2xl ring-4 ring-red-600' : 'translate-y-24 scale-125 z-50 shadow-2xl ring-4 ring-red-600')
    : '';

  if (showBack) {
    return (
      <div
        className={`${dimensions[size]} bg-indigo-900 border-2 border-slate-200 shadow-md relative overflow-hidden flex items-center justify-center`}
      >
        <div className="w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-indigo-700 to-indigo-950 opacity-80"></div>
        <div className="absolute text-indigo-300 font-title font-bold opacity-30">BATTLE</div>
      </div>
    );
  }

  return (
    <div
      onClick={onClick}
      className={`
        ${dimensions[size]} 
        relative bg-white shadow-md select-none transition-all duration-300 ease-out
        flex flex-col justify-between p-1
        ${isRed ? 'text-red-600' : 'text-slate-900'}
        ${isSelected ? 'ring-4 ring-yellow-400 -translate-y-2 z-10' : 'border border-slate-300'}
        ${isPlayable ? 'ring-2 ring-green-400 cursor-pointer hover:-translate-y-1' : ''}
        ${isTargetable ? 'ring-4 ring-red-500 cursor-crosshair animate-pulse' : ''}
        ${isTapped ? 'rotate-90 grayscale-[0.5]' : ''}
        ${isAttacking && !isLunging ? 'ring-4 ring-red-600 -translate-y-6 shadow-xl z-10' : ''} 
        ${isBlocking ? 'ring-4 ring-blue-500 -translate-y-4 shadow-lg' : ''}
        ${lungeClass}
        ${onClick ? 'cursor-pointer' : ''}
      `}
    >
      {/* Top Corner */}
      <div className="flex flex-col items-center leading-none">
        <span className="font-bold font-title">{card.rank}</span>
        <span className="text-[0.8em]">{card.suit}</span>
      </div>

      {/* Center Art / Icon placeholder */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
        <span className="text-4xl">{card.suit}</span>
      </div>

      {/* Bottom Corner */}
      <div className="flex flex-col items-center leading-none rotate-180">
        <span className="font-bold font-title">{card.rank}</span>
        <span className="text-[0.8em]">{card.suit}</span>
      </div>

      {/* Special Badges */}
      {card.rank === 'A' && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-black text-white text-[0.5rem] px-1 rounded uppercase tracking-tighter">
          Slayer
        </div>
      )}
      {['J', 'Q', 'K'].includes(card.rank) && (
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 text-[0.5rem] uppercase font-bold tracking-widest bg-slate-100 px-1 rounded shadow-sm opacity-80">
          {card.rank === 'J' ? 'Draw 2' : card.rank === 'Q' ? 'Shift' : 'Kill'}
        </div>
      )}

      {/* Damage Popup */}
      {damageTaken !== undefined && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[60] pointer-events-none animate-bounce scale-150">
            <div className="text-4xl font-black text-white stroke-black drop-shadow-[0_4px_4px_rgba(0,0,0,1)]" style={{ WebkitTextStroke: '1px black' }}>
                -{damageTaken}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, User, Heart, Play, ShieldAlert, Swords, AlertTriangle, X, Check, Layers } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      // Draw initial 8 cards
      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT, // Start with selection
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, []);

  // -- Helper Functions --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  // -- Phase Management --

  // Refactored to avoid stale state closures
  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          // Untap all soldiers AND resources
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            // Untap resources for the turn player
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 1000);
          break;

        case Phase.DRAW:
            let cardDrawn = false;
            let sourceDeck: Card[] = [];

            if (newState.mode === 'STREET') {
                sourceDeck = newState.deck;
            } else {
                sourceDeck = player.library;
            }

            if (sourceDeck.length > 0) {
                const card = sourceDeck.shift();
                if (card) {
                    player.hand.push(card);
                    player.consecutiveDrawFailures = 0;
                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                    cardDrawn = true;
                }
            }

            if (!cardDrawn) {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }

            if (newState.phase !== Phase.GAME_OVER) {
                setTimeout(() => advancePhase(Phase.RESOURCE_START), 500);
            }
            break;

        case Phase.RESOURCE_START:
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached. Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 500);
            } else {
                newState.logs = addLog(newState, "Resource Step: Add or Swap?");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            // Handled by confirmBlocks triggering resolveCombat
            break;
      }

      return newState;
    });
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);

    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        const nextState = {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP 
        };

        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return prev; 
    });
  };

  // -- Logic Handlers --

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') {
          advancePhase(Phase.RESOURCE_ADD_SELECT);
      } else {
          advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
      }
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  const handleConfirmInitSelection = () => {
      if (!gameState) return;
      const player = gameState.players[gameState.turnPlayer];

      if (gameState.initSelectedIds.length !== 3) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Must select exactly 3 cards.") }));
          return;
      }

      setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];

          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));

          p.hand = remainingHand;
          selectedCards.forEach(c => {
              p.resources.push(createFieldCard(c, p.id));
          });

          if (prev.turnPlayer === 0) {
              return { 
                  ...prev, 
                  turnPlayer: 1, 
                  initSelectedIds: [], 
                  logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") 
              };
          } else {
              // Start Game with Player 1 Upkeep
              const startState = {
                  ...prev,
                  turnPlayer: 0,
                  initSelectedIds: [],
                  phase: Phase.UPKEEP,
                  logs: addLog(prev, "Game On! Player 1 Start.")
              };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
      });
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;

      // INIT SELECT LOGIC
      if (gameState.phase === Phase.INIT_SELECT) {
          if (ownerId !== gameState.turnPlayer || location !== 'HAND') return;

          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = [...prev.initSelectedIds];

              if (isSelected) {
                  newIds = newIds.filter(id => id !== card.id);
              } else {
                  if (newIds.length < 3) {
                      newIds.push(card.id);
                  }
              }
              return { ...prev, initSelectedIds: newIds };
          });
          return;
      }

      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             if (cardIdx === -1) return prev;

             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));

             let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
             if (sourceDeck.length > 0) {
                 const draw = sourceDeck.shift();
                 if(draw) p.hand.push(draw);
             } else {
                 p.consecutiveDrawFailures++;
             }

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: card.id,
              phase: Phase.RESOURCE_SWAP_SELECT_PILE,
              logs: addLog(prev!, "Select a resource to swap with.")
          }));
      }

      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE' && ownerId === activePlayerId) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);

              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];

                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
              }

              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource. Skipped 2nd draw.") };
          });
      }

      // -- Main Phase: Playing Cards (Turn Player only) --
      else if (gameState.phase === Phase.MAIN && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => ({
              ...prev!,
              selectedCardId: prev?.selectedCardId === card.id ? null : card.id
          }));
      }

      // -- Main Phase: Selecting Targets (Queen/King) --
      else if (gameState.phase === Phase.MAIN && location === 'FIELD' && gameState.targetMode !== 'NONE') {
          handleTargetSelection(instanceId!, ownerId);
      }

      // -- Attack Phase: Tapping Attackers (Turn Player only) --
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);

              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;

              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking 
                  ? prev.pendingAttackers.filter(id => id !== instanceId)
                  : [...prev.pendingAttackers, instanceId!];

              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }

      // -- Block Phase: Assigning Blocks (Defender only) --
      else if (gameState.phase === Phase.BLOCK_DECLARE) {
          if (ownerId === activePlayerId && location === 'FIELD') { 
              setGameState(prev => ({ ...prev!, selectedCardId: instanceId! }));
          }

          if (ownerId !== activePlayerId && location === 'FIELD' && gameState.selectedCardId) {
              const attackerInstanceId = instanceId!;
              if (!gameState.pendingAttackers.includes(attackerInstanceId)) return;

              setGameState(prev => {
                  if(!prev) return null;
                  const defenderPlayer = prev.players[activePlayerId];
                  const attackerPlayer = prev.players[activePlayerId === 0 ? 1 : 0];

                  const blocker = defenderPlayer.field.find(f => f.instanceId === prev.selectedCardId);
                  const attacker = attackerPlayer.field.find(f => f.instanceId === attackerInstanceId);

                  if (!blocker || !attacker) return prev;
                  if (blocker.isTapped) return prev;

                  if (!canBlock(attacker, blocker)) {
                      return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
                  }

                  const existingBlockerForAttacker = Object.keys(prev.pendingBlocks).find(key => prev.pendingBlocks[key] === attackerInstanceId);
                  const newBlocks = { ...prev.pendingBlocks };

                  if (existingBlockerForAttacker) delete newBlocks[existingBlockerForAttacker];

                  newBlocks[blocker.instanceId] = attackerInstanceId;

                  return { 
                      ...prev, 
                      pendingBlocks: newBlocks, 
                      selectedCardId: null,
                      logs: addLog(prev, "Block declared.")
                  };
              });
          }
      }
  };

  const handlePlayCard = () => {
      if (!gameState || !gameState.selectedCardId) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);
      const player = gameState.players[activePlayerId];
      const cardIdx = player.hand.findIndex(c => c.id === gameState.selectedCardId);
      if (cardIdx === -1) return;
      const card = player.hand[cardIdx];

      const untappedResources = player.resources.filter(r => !r.isTapped);
      if (untappedResources.length < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, `Not enough resources! Need ${card.cost}.`) }));
          return;
      }

      setGameState(prev => {
         if(!prev) return null;
         const p = prev.players[activePlayerId];
         let toTap = card.cost;
         for (const res of p.resources) {
             if (!res.isTapped && toTap > 0) {
                 res.isTapped = true;
                 toTap--;
             }
         }
         return { ...prev }; 
      });

      if (card.rank === 'J') {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              p.hand.splice(cardIdx, 1);
              p.discard.push(card);

              let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
              for(let i=0; i<2; i++){
                  if(sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
              }
              return { ...prev, selectedCardId: null, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
          });
      }
      else if (card.rank === 'Q' || card.rank === 'K') {
          setGameState(prev => ({
              ...prev!,
              targetMode: card.rank === 'Q' ? 'QUEEN' : 'KING',
              sourceCardId: card.id,
              logs: addLog(prev!, `Select target for ${card.rank === 'Q' ? 'Queen' : 'King'}.`)
          }));
      }
      else {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              p.hand.splice(cardIdx, 1);
              const newSoldier = createFieldCard(card, p.id);
              p.field.push(newSoldier);
              return { ...prev, selectedCardId: null, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
          });
      }
  };

  const handleTargetSelection = (targetInstanceId: string, targetOwnerId: number) => {
      setGameState(prev => {
          if (!prev || !prev.sourceCardId) return null;

          const p = prev.players[prev.turnPlayer];
          const handIdx = p.hand.findIndex(c => c.id === prev.sourceCardId);
          if (handIdx === -1) return prev;
          const tacticCard = p.hand[handIdx];

          const targetPlayer = prev.players[targetOwnerId];
          const targetCardIdx = targetPlayer.field.findIndex(fc => fc.instanceId === targetInstanceId);
          if (targetCardIdx === -1) return prev;
          const targetCard = targetPlayer.field[targetCardIdx];

          if (tacticCard.rank === 'K') {
               const kingColor = tacticCard.baseColor;
               const targetColor = getEffectiveColor(targetCard);
               if (kingColor !== targetColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: King can only execute same spectrum.") };
               }
               p.hand.splice(handIdx, 1);
               p.discard.push(tacticCard);

               targetPlayer.field.splice(targetCardIdx, 1);
               targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);

               return { ...prev, targetMode: 'NONE', sourceCardId: null, selectedCardId: null, logs: addLog(prev, "King executed a soldier.") };
          }

          if (tacticCard.rank === 'Q') {
              p.hand.splice(handIdx, 1);
              targetCard.attachedCards.push(tacticCard);
              return { ...prev, targetMode: 'NONE', sourceCardId: null, selectedCardId: null, logs: addLog(prev, "Queen attached. Spectrum shifted.") };
          }

          return prev;
      });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Attack declared! Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      // Start 1-by-1 combat resolution
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  // Triggering the async combat sequence whenever Phase switches to DAMAGE
  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  // Ref to access latest state inside async sequence without stale closures
  const gameStateRef = useRef<GameState | null>(null);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      // We will iterate through interactions
      for (const atk of attackers) {
          // 1. Highlight / Lunge
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 600)); // Lunge Duration

          // 2. Show Damage
          setGameState(prev => {
             if (!prev) return null;
             const blockerId = prev.pendingBlocks[atk.instanceId];
             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 const defenderKey = defenderPlayer.id === 0 ? 'P0' : 'P1';
                 nextRecentDamage[defenderKey] = (nextRecentDamage[defenderKey] || 0) + dmg;
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 1200)); // Read time

          // 3. Reset Lunge for this card
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 200)); // Brief pause between cards
      }

      // 4. Finalize Combat (Death/Cleanup)
      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = nextState.pendingBlocks[atk.instanceId];

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          // Check Game Over
          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const checkGameOver = (state: GameState) => {
      if (state.players[0].life <= 0) state.winner = 1;
      else if (state.players[1].life <= 0) state.winner = 0;

      if (state.players[0].consecutiveDrawFailures > 0 && state.players[1].consecutiveDrawFailures > 0) {
          if (state.players[0].life > state.players[1].life) state.winner = 0;
          else if (state.players[1].life > state.players[0].life) state.winner = 1;
          else {
              const p1Val = state.players[0].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              const p2Val = state.players[1].field.reduce((acc, c) => acc + c.card.numericValue, 0);
              if (p1Val > p2Val) state.winner = 0;
              else if (p2Val > p1Val) state.winner = 1;
              else state.winner = -1;
          }
      }

      if (state.winner !== null) {
          state.phase = Phase.GAME_OVER;
      }
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- RENDER: TITLE SCREEN --
  if (!gameState) {
      return (
          <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans items-center justify-center relative overflow-hidden">
              <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-900 to-slate-950"></div>

              <div className="z-10 text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <div className="mb-8">
                      <h1 className="text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-br from-indigo-400 to-red-400 drop-shadow-2xl">
                          BATTLE
                      </h1>
                      <p className="text-slate-400 tracking-widest uppercase text-sm mt-2">Tactical Card Warfare</p>
                  </div>

                  <div className="flex gap-8">
                      <button 
                          onClick={() => startGame('STREET')}
                          className="group relative w-64 h-80 bg-slate-900 border-2 border-slate-700 hover:border-indigo-500 rounded-xl p-6 transition-all duration-300 hover:-translate-y-2 hover:shadow-2xl hover:shadow-indigo-500/20 flex flex-col items-center justify-between text-left"
                      >
                          <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/50 rounded-xl"></div>
                          <div className="z-10 w-full">
                              <Swords className="w-12 h-12 text-indigo-500 mb-4 group-hover:scale-110 transition" />
                              <h2 className="text-2xl font-bold text-white mb-2 font-title">Street Rules</h2>
                              <p className="text-sm text-slate-400 leading-relaxed">
                                  Shared 52-card deck. Resources are tight. Every draw counts. Chaos guaranteed.
                              </p>
                          </div>
                          <div className="z-10 w-full border-t border-slate-700 pt-4 flex justify-between items-center text-indigo-400 text-sm font-bold">
                              <span>Play Street</span>
                              <ArrowUpCircle className="rotate-90" size={16} />
                          </div>
                      </button>

                      <button 
                          onClick={() => startGame('PRO')}
                          className="group relative w-64 h-80 bg-slate-900 border-2 border-slate-700 hover:border-red-500 rounded-xl p-6 transition-all duration-300 hover:-translate-y-2 hover:shadow-2xl hover:shadow-red-500/20 flex flex-col items-center justify-between text-left"
                      >
                          <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/50 rounded-xl"></div>
                          <div className="z-10 w-full">
                              <ShieldAlert className="w-12 h-12 text-red-500 mb-4 group-hover:scale-110 transition" />
                              <h2 className="text-2xl font-bold text-white mb-2 font-title">Pro Rules</h2>
                              <p className="text-sm text-slate-400 leading-relaxed">
                                  Separate 52-card decks. Predictable resources. Pure strategy and deck management.
                              </p>
                          </div>
                          <div className="z-10 w-full border-t border-slate-700 pt-4 flex justify-between items-center text-red-400 text-sm font-bold">
                              <span>Play Pro</span>
                              <ArrowUpCircle className="rotate-90" size={16} />
                          </div>
                      </button>
                  </div>
              </div>

              <div className="absolute bottom-4 text-slate-600 text-xs">v1.0.0 Alpha</div>
          </div>
      );
  }

  // -- RENDER: GAME --

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];

  const topPlayerDamage = gameState.recentDamage[topPlayer.id === 0 ? 'P0' : 'P1'];

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans">

      {/* End Turn Confirmation Modal */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[60] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <div className="flex items-center gap-3 text-amber-500 mb-4">
                      <AlertTriangle size={24} />
                      <h3 className="text-xl font-bold font-title">End Turn?</h3>
                  </div>
                  <p className="text-slate-400 mb-6">Are you sure you want to end your turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button 
                          onClick={() => setShowEndTurnModal(false)}
                          className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded font-bold transition flex items-center gap-2"
                      >
                          <X size={16} /> Cancel
                      </button>
                      <button 
                          onClick={confirmEndTurn}
                          className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded font-bold transition flex items-center gap-2"
                      >
                          <Check size={16} /> Confirm
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Top Bar (Status) */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
        <div className="flex items-center gap-4">
           <div className="text-xl font-title font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</div>
           <div className="h-6 w-px bg-slate-700"></div>
           <div className="flex flex-col leading-none" title="Current Round Number">
               <span className="text-[10px] text-slate-500 uppercase font-bold">Round</span>
               <span className="text-sm font-bold text-slate-200">{gameState.turnCount}</span>
           </div>
           <div className="px-3 py-1 bg-slate-800 rounded border border-slate-700 text-slate-300 text-xs font-bold uppercase tracking-wide" title="Current Game Phase">
               {getPhaseName()}
           </div>
        </div>

        <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">{topPlayer.name}</div>
                <div className="flex items-center gap-3 bg-slate-800/50 px-3 py-1 rounded-full border border-slate-700 relative">
                     <div className="flex items-center text-red-400 gap-1.5 font-bold" title="Opponent Life">
                         <Heart size={14} fill="currentColor" /> {topPlayer.life}
                         {topPlayerDamage && (
                             <span className="absolute -bottom-6 left-2 text-2xl font-black text-red-500 animate-bounce">-{topPlayerDamage}</span>
                         )}
                     </div>
                     <div className="w-px h-3 bg-slate-700"></div>
                     <div className="flex items-center text-blue-400 gap-1.5 font-bold" title="Opponent Resources"><RotateCcw size={14} /> {topPlayer.resources.length}</div>
                     <div className="w-px h-3 bg-slate-700"></div>
                     <div className="flex items-center text-amber-400 gap-1.5 font-bold" title="Opponent Cards in Hand"><User size={14} /> {topPlayer.hand.length}</div>
                     <div className="w-px h-3 bg-slate-700"></div>
                     <div className="flex items-center text-slate-400 gap-1.5 font-bold" title="Opponent Deck"><Layers size={14} /> {gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</div>
                </div>
            </div>
        </div>
      </div>

      {/* Game Area */}
      <div className="flex-1 flex flex-col relative overflow-hidden bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

         {/* Top Player Field */}
         <div className="flex-1 border-b border-slate-800/50 flex flex-col p-4 relative">
             <div className="flex-1 flex justify-center gap-4 items-center">
                 {/* Top Hand (Hidden) */}
                 <div className="absolute top-[-40px] right-4 flex -space-x-12 scale-75 origin-top-right transition-all hover:translate-y-4 z-10">
                     {topPlayer.hand.map((c, i) => (
                         <CardDisplay key={c.id} card={c} showBack size="sm" />
                     ))}
                 </div>

                 {/* Lanes */}
                 <div className="flex gap-8 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 bg-gradient-to-b from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative group">
                         <div className="absolute top-2 left-2 text-slate-700 text-6xl opacity-10 font-serif">♠</div>
                         {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                    isLunging={gameState.activeCombatCardId === fc.instanceId}
                                    damageTaken={gameState.recentDamage[fc.instanceId]}
                                    onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                    isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id)}
                                    orientation="top"
                                 />
                             </div>
                         ))}
                     </div>
                     <div className="flex-1 bg-gradient-to-b from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative group">
                         <div className="absolute top-2 right-2 text-red-900 text-6xl opacity-10 font-serif">♥</div>
                         {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isBlocking={Object.keys(gameState.pendingBlocks).includes(fc.instanceId)}
                                    isLunging={gameState.activeCombatCardId === fc.instanceId}
                                    damageTaken={gameState.recentDamage[fc.instanceId]}
                                    onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                    isTargetable={gameState.targetMode !== 'NONE' || (gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id)}
                                    orientation="top"
                                 />
                             </div>
                         ))}
                     </div>
                 </div>
             </div>
         </div>

         {/* Center Info / Phase Indicator */}
         {gameState.phase === Phase.DAMAGE && (
             <div className="absolute inset-0 z-30 flex items-center justify-center bg-black/60 backdrop-blur-sm pointer-events-none">
                 <div className="text-6xl font-black text-red-500 animate-bounce font-title drop-shadow-[0_5px_5px_rgba(0,0,0,1)]">COMBAT!</div>
             </div>
         )}

         {gameState.winner !== null && (
             <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-md">
                 <div className="text-center animate-in zoom-in duration-300">
                     <div className="text-7xl font-black text-amber-500 mb-6 font-title tracking-tight">
                         {gameState.winner === -1 ? "DRAW" : `${gameState.players[gameState.winner].name} WINS`}
                     </div>
                     <div className="flex gap-4 justify-center">
                        <button 
                            onClick={() => setGameState(null)}
                            className="px-8 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded font-bold shadow-lg transition"
                        >
                            Main Menu
                        </button>
                     </div>
                 </div>
             </div>
         )}

         {/* Bottom Player Field */}
         <div className="flex-1 flex flex-col p-4 relative">
             <div className="flex-1 flex justify-center gap-4 items-center h-full">
                 <div className="flex gap-8 w-full max-w-4xl justify-center h-full">
                     <div className="flex-1 bg-gradient-to-t from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-2 left-2 text-slate-700 text-6xl opacity-10 font-serif">♣</div>
                         {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped} 
                                    isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                    isLunging={gameState.activeCombatCardId === fc.instanceId}
                                    isBlocking={gameState.selectedCardId === fc.instanceId} 
                                    damageTaken={gameState.recentDamage[fc.instanceId]}
                                    onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                    isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                    orientation="bottom"
                                 />
                             </div>
                         ))}
                     </div>
                     <div className="flex-1 bg-gradient-to-t from-slate-900/50 to-transparent rounded-lg border border-slate-800/30 flex justify-center items-center gap-2 relative">
                         <div className="absolute bottom-2 right-2 text-red-900 text-6xl opacity-10 font-serif">♦</div>
                         {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                             <div key={fc.instanceId} className="transition-transform hover:scale-105">
                                 <CardDisplay 
                                    card={fc.card} 
                                    isTapped={fc.isTapped}
                                    isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                    isLunging={gameState.activeCombatCardId === fc.instanceId}
                                    isBlocking={gameState.selectedCardId === fc.instanceId} 
                                    damageTaken={gameState.recentDamage[fc.instanceId]}
                                    onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                    isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                    orientation="bottom"
                                 />
                             </div>
                         ))}
                     </div>
                 </div>
             </div>
         </div>
      </div>

      {/* Bottom Control Area */}
      <div className="h-52 bg-slate-900 border-t border-slate-800 flex shadow-[0_-10px_40px_rgba(0,0,0,0.5)] z-20">

          {/* Active Player Stats */}
          <div className="w-56 p-5 border-r border-slate-800 flex flex-col justify-between bg-slate-900">
              <div>
                  <div className="text-2xl font-title font-bold text-indigo-300 truncate">{bottomPlayer.name}</div>
                  <div className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Decision Maker</div>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500" title="Your Life">
                      <Heart size={28} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="flex flex-col gap-1 mt-2">
                   <div className="text-xs text-slate-500 font-bold uppercase tracking-wide">
                      Deck: <span className="text-slate-200 text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
                   </div>
              </div>
          </div>

          {/* Hand Area */}
          <div className="flex-1 p-4 flex flex-col items-center justify-center relative bg-slate-800/50 shadow-inner">
             <div className="absolute top-2 text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Current Hand</div>
             <div className="flex -space-x-4 pt-4 pb-2 px-8 overflow-visible">
                 {bottomPlayer.hand.map((card, idx) => {
                     const isSelectedForInit = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(card.id);
                     return (
                         <div key={card.id} className={`hover:-translate-y-6 hover:scale-110 hover:z-20 transition-all duration-200 origin-bottom cursor-pointer ${isSelectedForInit ? '-translate-y-6 z-10' : ''}`}>
                             <CardDisplay 
                                card={card} 
                                onClick={() => handleCardClick(card, 'HAND', bottomPlayer.id)}
                                isSelected={gameState.selectedCardId === card.id || isSelectedForInit}
                                isPlayable={
                                    gameState.phase === Phase.MAIN && 
                                    bottomPlayer.resources.filter(r => !r.isTapped).length >= card.cost
                                }
                             />
                         </div>
                     );
                 })}
             </div>
          </div>

          {/* Resource & Actions */}
          <div className="w-80 p-4 border-l border-slate-800 flex flex-col gap-3 bg-slate-900">

             {/* Resources Header */}
             <div className="flex justify-between items-baseline px-1">
                 <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Resources</span>
                 <span className="text-xs font-bold text-indigo-400">
                     {bottomPlayer.resources.filter(r => !r.isTapped).length} <span className="text-slate-600">/</span> {bottomPlayer.resources.length}
                 </span>
             </div>

             {/* Resources List */}
             <div className="h-16 flex items-center gap-1 overflow-x-auto p-2 bg-black/40 rounded-lg shadow-inner">
                 {bottomPlayer.resources.length === 0 && <span className="text-xs text-slate-600 w-full text-center italic">No Resources</span>}
                 {bottomPlayer.resources.map(r => (
                     <div key={r.instanceId} className="cursor-pointer hover:scale-110 hover:-translate-y-1 transition duration-200" onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id)}>
                         <CardDisplay card={r.card} size="sm" isTapped={r.isTapped} />
                     </div>
                 ))}
             </div>

             {/* Action Buttons */}
             <div className="flex-1 grid grid-cols-2 gap-2">
                 {/* Init Phase Actions */}
                 {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                     <div className="col-span-2 flex flex-col gap-2">
                         <div className="text-center text-xs text-slate-400">Select 3 cards for Resources</div>
                         <button 
                            disabled={gameState.initSelectedIds.length !== 3}
                            onClick={handleConfirmInitSelection}
                            className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded p-2 font-bold shadow-lg transition"
                        >
                             Confirm Selection ({gameState.initSelectedIds.length}/3)
                         </button>
                     </div>
                 )}

                 {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                     <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-700 hover:bg-emerald-600 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center transition shadow-lg border-b-2 border-emerald-900 active:border-b-0 active:translate-y-1">
                            <ArrowUpCircle size={18} className="mb-1" />
                            <span>Add & Draw</span>
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-700 hover:bg-amber-600 text-white rounded p-1 text-sm font-bold flex flex-col items-center justify-center transition shadow-lg border-b-2 border-amber-900 active:border-b-0 active:translate-y-1">
                            <RotateCcw size={18} className="mb-1" />
                            <span>Swap Res</span>
                        </button>
                     </>
                 )}

                 {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                     <div className="col-span-2 bg-slate-700/50 border border-slate-600 text-slate-300 text-center text-xs p-2 rounded flex items-center justify-center animate-pulse font-bold">
                         Select card from hand to add
                     </div>
                 )}

                 {gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && (
                     <div className="col-span-2 bg-amber-900/40 border border-amber-600 text-amber-200 text-center text-xs p-2 rounded flex items-center justify-center animate-pulse font-bold">
                         Select a Resource to swap with
                     </div>
                 )}

                 {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                     <>
                        <button 
                            disabled={gameState.targetMode !== 'NONE' || bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)} 
                            className="bg-rose-700 hover:bg-rose-600 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded font-bold flex items-center justify-center gap-2 shadow-lg transition border-b-4 border-rose-900 active:border-b-0 active:translate-y-1"
                        >
                            <Sword size={18} /> Attack
                        </button>
                        {gameState.selectedCardId ? (
                            <button onClick={handlePlayCard} className="bg-indigo-600 hover:bg-indigo-500 text-white rounded font-bold shadow-lg transition border-b-4 border-indigo-900 active:border-b-0 active:translate-y-1">
                                Play Card
                            </button>
                        ) : (
                             <button onClick={requestEndTurn} className="bg-slate-700 hover:bg-slate-600 text-white rounded font-bold shadow-lg transition border-b-4 border-slate-900 active:border-b-0 active:translate-y-1">
                                End Turn
                            </button>
                        )}
                        {gameState.targetMode !== 'NONE' && (
                            <div className="col-span-2 text-center text-xs text-amber-300 font-bold animate-pulse">Select target unit...</div>
                        )}
                     </>
                 )}

                 {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                     <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white rounded font-bold animate-pulse shadow-[0_0_15px_rgba(225,29,72,0.6)] transition border-b-4 border-rose-800 active:border-b-0 active:translate-y-1">
                         Confirm Attackers ({gameState.pendingAttackers.length})
                     </button>
                 )}

                 {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                     <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white rounded font-bold shadow-[0_0_15px_rgba(37,99,235,0.6)] transition border-b-4 border-blue-800 active:border-b-0 active:translate-y-1">
                         Confirm Blocks
                     </button>
                 )}
             </div>
          </div>

      </div>

      {/* Log Overlay */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/80 border-l-4 border-indigo-500 text-slate-200 text-xs mb-1.5 p-2 rounded-r shadow-lg backdrop-blur-md animate-in slide-in-from-left fade-in duration-300">
                  {log}
              </div>
          ))}
      </div>

    </div>
  );
};

export default App;

export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
  baseColor: Color;
}

export interface FieldCard {
  instanceId: string;
  card: Card;
  ownerId: number;
  isTapped: boolean;
  isSummoningSick: boolean;
  attachedCards: Card[]; // For Queens
  currentHealth: number; // Usually equals attack, but for tracking state
}

export enum Phase {
  INIT = 'INIT',
  INIT_SELECT = 'INIT_SELECT', // New phase for selecting starting resources
  UPKEEP = 'UPKEEP',
  DRAW = 'DRAW',
  RESOURCE_START = 'RESOURCE_START',
  RESOURCE_ADD_SELECT = 'RESOURCE_ADD_SELECT',
  RESOURCE_SWAP_SELECT_HAND = 'RESOURCE_SWAP_SELECT_HAND',
  RESOURCE_SWAP_SELECT_PILE = 'RESOURCE_SWAP_SELECT_PILE',
  MAIN = 'MAIN',
  ATTACK_DECLARE = 'ATTACK_DECLARE',
  BLOCK_DECLARE = 'BLOCK_DECLARE',
  DAMAGE = 'DAMAGE',
  GAME_OVER = 'GAME_OVER',
}

export interface PlayerState {
  id: number;
  name: string;
  life: number;
  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: FieldCard[]; // Changed from Card[] to FieldCard[] to support tapping
  field: FieldCard[];
  discard: Card[];
  consecutiveDrawFailures: number;
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO';

export interface GameState {
  mode: GameMode;
  deck: Card[]; // Shared deck for Street mode
  players: PlayerState[];
  turnPlayer: number; // 0 or 1
  phase: Phase;
  turnCount: number;
  pendingAttackers: string[]; // instanceIds
  pendingBlocks: Record<string, string>; // blockerId -> attackerId
  selectedCardId: string | null; // For hand interaction
  activeCombatCardId: string | null; // The card currently animating in combat
  initSelectedIds: string[]; // For multi-selection during INIT_SELECT
  targetMode: 'NONE' | 'QUEEN' | 'KING';
  sourceCardId: string | null; // The card initiating the target mode
  winner: number | null; // 0, 1, or -1 (Draw)
  recentDamage: Record<string, number>; // Maps instanceId (or 'P0'/'P1') to damage taken this phase
  logs: string[];
}

export interface DragState {
    cardId: string;
    sourceType: 'HAND' | 'FIELD';
    ownerId: number;
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    cardObj?: Card; // Helper to avoid lookups during render
    instanceId?: string; // For field cards
}

export interface FlyingText {
    id: string;
    text: string;
    startX: number;
    startY: number;
    targetX: number;
    targetY: number;
    createdAt: number;
    color: string;
}

import React from 'react';
import { Card, Suit, Color, FieldCard } from '../types';
import { SUIT_COLORS } from '../constants';

interface CardDisplayProps {
  card: Card;
  domId?: string; // For DOM lookups/lines
  onClick?: () => void;
  onMouseDown?: (e: React.MouseEvent) => void;
  isSelected?: boolean;
  isTapped?: boolean;
  isPlayable?: boolean;
  isTargetable?: boolean;
  isAttacking?: boolean; // Used for static "declared" state
  isLunging?: boolean; // Used for active animation
  isDragging?: boolean;
  isBlocking?: boolean;
  attachedTo?: FieldCard; // If this is a queen attached to something
  damageTaken?: number; // Visual only
  size?: 'sm' | 'md' | 'lg';
  showBack?: boolean;
  orientation?: 'top' | 'bottom';
}

export const CardDisplay: React.FC<CardDisplayProps> = ({
  card,
  domId,
  onClick,
  onMouseDown,
  isSelected,
  isTapped,
  isPlayable,
  isTargetable,
  isAttacking,
  isLunging,
  isDragging,
  isBlocking,
  damageTaken,
  size = 'md',
  showBack = false,
  orientation = 'bottom',
}) => {
  const isRed = card.suit === Suit.Hearts || card.suit === Suit.Diamonds;

  // Size classes
  const dimensions = {
    sm: 'w-12 h-16 text-xs rounded-sm',
    md: 'w-20 h-28 text-sm rounded',
    lg: 'w-32 h-44 text-lg rounded-md',
  };

  // Lunging animation logic
  const lungeClass = isLunging 
    ? (orientation === 'bottom' ? '-translate-y-24 scale-125 z-50 shadow-2xl ring-4 ring-red-600' : 'translate-y-24 scale-125 z-50 shadow-2xl ring-4 ring-red-600')
    : '';

  if (showBack) {
    return (
      <div
        id={domId}
        className={`${dimensions[size]} bg-indigo-900 border-2 border-slate-200 shadow-md relative overflow-hidden flex items-center justify-center`}
      >
        <div className="w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-indigo-700 to-indigo-950 opacity-80"></div>
        <div className="absolute text-indigo-300 font-title font-bold opacity-30">BATTLE</div>
      </div>
    );
  }

  return (
    <div
      id={domId}
      onClick={onClick}
      onMouseDown={onMouseDown}
      className={`
        ${dimensions[size]} 
        relative bg-white shadow-md select-none transition-all duration-300 ease-out
        flex flex-col justify-between p-1
        ${isRed ? 'text-red-600' : 'text-slate-900'}
        ${isSelected ? 'ring-4 ring-yellow-400 -translate-y-2 z-10' : 'border border-slate-300'}
        ${isPlayable ? 'ring-2 ring-green-400 cursor-grab active:cursor-grabbing hover:-translate-y-1' : ''}
        ${isTargetable ? 'ring-4 ring-red-500 cursor-crosshair animate-pulse' : ''}
        ${isTapped ? 'rotate-90 grayscale-[0.5]' : ''}
        ${isAttacking && !isLunging ? 'ring-4 ring-red-600 -translate-y-6 shadow-xl z-10' : ''} 
        ${isBlocking ? 'ring-4 ring-blue-500 -translate-y-4 shadow-lg' : ''}
        ${isDragging ? 'opacity-50 grayscale' : ''}
        ${lungeClass}
        ${onClick || onMouseDown ? 'cursor-pointer' : ''}
      `}
    >
      {/* Top Corner */}
      <div className="flex flex-col items-center leading-none">
        <span className="font-bold font-title">{card.rank}</span>
        <span className="text-[0.8em]">{card.suit}</span>
      </div>

      {/* Center Art / Icon placeholder */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
        <span className="text-4xl">{card.suit}</span>
      </div>

      {/* Bottom Corner */}
      <div className="flex flex-col items-center leading-none rotate-180">
        <span className="font-bold font-title">{card.rank}</span>
        <span className="text-[0.8em]">{card.suit}</span>
      </div>

      {/* Special Badges */}
      {card.rank === 'A' && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-black text-white text-[0.5rem] px-1 rounded uppercase tracking-tighter">
          Slayer
        </div>
      )}
      {['J', 'Q', 'K'].includes(card.rank) && (
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 text-[0.5rem] uppercase font-bold tracking-widest bg-slate-100 px-1 rounded shadow-sm opacity-80">
          {card.rank === 'J' ? 'Draw 2' : card.rank === 'Q' ? 'Shift' : 'Kill'}
        </div>
      )}

      {/* Damage Popup */}
      {damageTaken !== undefined && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[60] pointer-events-none animate-bounce scale-150">
            <div className="text-4xl font-black text-white stroke-black drop-shadow-[0_4px_4px_rgba(0,0,0,1)]" style={{ WebkitTextStroke: '1px black' }}>
                -{damageTaken}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, User, Heart, Play, ShieldAlert, Swords, AlertTriangle, X, Check, Layers, Hand } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);

  // UI State
  const [dragState, setDragState] = useState<DragState | null>(null);
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);

  // Refs for tracking DOM positions for lines and flying text
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, []);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  // Determine if the "End Turn" button should be highlighted
  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      // 1. Can play a card?
      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);

      // 2. Can attack?
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Drag & Drop Logic --

  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      // Prevent dragging if not allowed
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      // Block Phase: Only allow dragging defenders
      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') {
          // Allow
      } 
      // Main Phase: Only allow dragging hand cards (or maybe field cards later for abilities, but sticking to basics)
      else if (gameState.phase === Phase.MAIN && type === 'HAND') {
          // Allow
      }
      else {
          return; // Block drag
      }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      // Use document.elementFromPoint to find what we dropped on
      // We look for elements with 'data-instance-id' or 'id="field-area"'
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return; // Dropped in void

      // -- PLAYING CARDS FROM HAND --
      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');

          if (targetElement.id === 'field-area' || targetInstanceId) {
             // Logic to play card
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }

      // -- DECLARING BLOCKERS --
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      // Cost Check
      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      // Target Check
      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return; // Must drop on a target

          // Execute Targeted Play
          // Find target card
          let targetOwnerId = -1;
          let targetCardIndex = -1;

          gameState.players.forEach(p => {
              const idx = p.field.findIndex(f => f.instanceId === targetInstanceId);
              if (idx !== -1) {
                  targetOwnerId = p.id;
                  targetCardIndex = idx;
              }
          });

          if (targetOwnerId === -1) return;

          // We essentially simulate the 2-step process in one go
          // 1. Pay Cost
          // 2. Execute Effect
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          // Soldier or Jack -> Play normally (no target needed, just field drop)
          playCardImmediate(card);
      }
  };

  const playCardImmediate = (card: Card, targetId?: string, targetOwnerId?: number) => {
       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           const cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           // Pay Cost
           let toTap = card.cost;
           for (const res of p.resources) {
               if (!res.isTapped && toTap > 0) {
                   res.isTapped = true;
                   toTap--;
               }
           }

           // Remove from hand
           p.hand.splice(cardIdx, 1);

           // Effects
           if (card.rank === 'J') {
               p.discard.push(card);
               let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
               for(let i=0; i<2; i++) {
                   if(sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
               }
               return { ...prev, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
           } 
           else if (card.rank === 'Q' || card.rank === 'K') {
               const targetPlayer = prev.players[targetOwnerId!];
               const targetCardIdx = targetPlayer.field.findIndex(f => f.instanceId === targetId);
               if (targetCardIdx === -1) return prev; // Should not happen given checks
               const targetCard = targetPlayer.field[targetCardIdx];

               if (card.rank === 'K') {
                   const kingColor = card.baseColor;
                   const targetColor = getEffectiveColor(targetCard);
                   if (kingColor !== targetColor) {
                        // Refund (Revert state logic is hard here, so we just don't do it? 
                        // Or we allow invalid play to fizzle? Let's block it earlier ideally, but here we just return prev and untap resources? 
                        // For simplicity, we assume player checked. If invalid, we undo cost payment manually here or just fail safe.
                        // Let's just fail safe and revert the hand/tap.
                        p.hand.push(card);
                        // Untap resources (simplistic: untap 'cost' amount of resources)
                        let toUntap = card.cost;
                        for(const res of p.resources) { if(res.isTapped && toUntap > 0) { res.isTapped = false; toUntap--; }}
                        return { ...prev, logs: addLog(prev, "Invalid Target: King can only kill same color.") };
                   }
                   p.discard.push(card);
                   targetPlayer.field.splice(targetCardIdx, 1);
                   targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);
                   return { ...prev, logs: addLog(prev, "King executed a soldier.") };
               }
               else if (card.rank === 'Q') {
                   targetCard.attachedCards.push(card);
                   return { ...prev, logs: addLog(prev, "Queen attached. Spectrum shifted.") };
               }
           }
           else {
               // Soldier
               const newSoldier = createFieldCard(card, p.id);
               p.field.push(newSoldier);
               return { ...prev, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
           }

           return prev;
       });
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          // Validate
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];

          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker) return prev;
          if (blocker.isTapped) return prev; // Cannot block if tapped
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          // Register Block
          // Remove any existing block assignments for this blocker? 
          // One blocker blocks one attacker.
          const newBlocks = { ...prev.pendingBlocks };

          // If this blocker was blocking something else, remove that entry
          // Since pendingBlocks is { blockerId: attackerId }, we just overwrite
          newBlocks[blockerInstanceId] = attackerInstanceId;

          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  // -- Combat Logic & Animation --

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      // Default to center if no element
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      // Target is Life Icon in HUD
      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      // Cleanup
      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            let cardDrawn = false;
            let sourceDeck = newState.mode === 'STREET' ? newState.deck : player.library;

            if (sourceDeck.length > 0) {
                const card = sourceDeck.shift();
                if (card) {
                    player.hand.push(card);
                    player.consecutiveDrawFailures = 0;
                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                    cardDrawn = true;
                }
            } else {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }

            if (newState.phase !== Phase.GAME_OVER) {
                setTimeout(() => advancePhase(Phase.RESOURCE_START), 400);
            }
            break;

        case Phase.RESOURCE_START:
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached. Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 400);
            } else {
                newState.logs = addLog(newState, "Resource Step: Add or Swap?");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          // Auto-Skip Check: Does defender have ANY untapped units?
          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              // Go straight to damage, no blocks possible
              // Need to trigger useEffect, so set phase to DAMAGE
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "Attack declared! No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Attack declared! Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  // Async Combat Sequencer
  const gameStateRef = useRef<GameState | null>(null);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          // 1. Lunge
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          // 2. Logic & Visuals
          setGameState(prev => {
             if (!prev) return null;
             // Correctly find the blocker for this attacker
             // pendingBlocks: { blockerId: attackerId }
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 const defenderKey = defenderPlayer.id === 0 ? 'P0' : 'P1'; // P0 is P1 in UI? No, P0 is ID 0.
                 // Just map ID to Key
                 // Actually, let's just use the player's life for visual logic later or HUD
                 // We will spawn flying text here
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      // 3. Resolve State (Deaths/Damage)
      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  // ... (Other handlers like handleConfirmInitSelection, handleResourceOption kept same as previous but omitted for brevity in thought, will include in XML)

  // Need to include missing handlers from previous version or it breaks.
  // Re-implementing necessary ones for completeness.

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       // Logic to move cards to resources
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
      // Logic same as before
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      // Simple Click Handlers (Selection for Init, or specific interactions)
      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }

      // Resource Add/Swap Logic
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));
             let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
             if (sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
             else p.consecutiveDrawFailures++;
             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          // Swap logic
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }

      // Attack Declaration Tapping (Click Fallback)
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }

      // Remove Block (Defender Click)
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      // (Simple Start Screen - Abbreviated for XML limits, assuming kept from previous)
      return (
          <div className="flex items-center justify-center h-screen bg-slate-900 text-white">
              <div className="text-center space-y-4">
                  <h1 className="text-6xl font-bold font-title">BATTLE</h1>
                  <div className="flex gap-4">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 px-6 py-3 rounded font-bold">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 px-6 py-3 rounded font-bold">Play Pro</button>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Flying Text Layer */}
      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`
                @keyframes fly {
                    0% { transform: translate(0,0) scale(1); opacity: 1; }
                    80% { opacity: 1; }
                    100% { transform: translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.2); opacity: 0; }
                }
              `}</style>
          </div>
      ))}

      {/* SVG Connection Lines for Blocks */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
              // Draw line from dragging card to cursor
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500">Deck: {gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</div>
         </div>
      </div>

      {/* Field Area */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

          {/* Top Player (Opponent) */}
          <div className="flex-1 flex flex-col items-center justify-center p-4 border-b border-slate-800/30">
               <div className="absolute top-[-40px] flex -space-x-12 scale-75 opacity-70">
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} card={c} showBack size="sm" />)}
               </div>
               <div className="flex gap-16">
                   {/* Black Lane */}
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId} // For play target detection
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
                   {/* Red Lane */}
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Bottom Player (You) */}
          <div className="flex-1 flex flex-col items-center justify-center p-4">
               <div className="flex gap-16">
                   {/* Black Lane */}
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
                   {/* Red Lane */}
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Floating Dragged Card */}
          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      {/* Controls */}
      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30">

          {/* Stats */}
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2">
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 uppercase font-bold tracking-wider">
                  Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
              </div>
          </div>

          {/* Hand */}
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner">
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map(c => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       const isPlayable = isMainPhase && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost;
                       return (
                           <div key={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          {/* Actions & Resources */}
          <div className="w-80 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3">
              <div className="flex justify-between items-baseline px-1">
                  <span className="text-[10px] font-bold text-slate-500 uppercase">Resources</span>
                  <span className="text-xs font-bold text-indigo-400">
                      {bottomPlayer.resources.filter(r => !r.isTapped).length} <span className="text-slate-600">/</span> {bottomPlayer.resources.length}
                  </span>
              </div>
              <div className="h-16 flex items-center gap-1 overflow-x-auto p-2 bg-black/40 rounded-lg shadow-inner">
                  {bottomPlayer.resources.map(r => (
                      <div key={r.instanceId} className="hover:scale-105 transition" onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id)}>
                          <CardDisplay card={r.card} size="sm" isTapped={r.isTapped} />
                      </div>
                  ))}
              </div>

              {/* Dynamic Buttons */}
              <div className="flex-1 grid grid-cols-2 gap-2">
                  {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button 
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1">
                            <ArrowUpCircle size={16} className="mb-1"/> Add
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1">
                            <RotateCcw size={16} className="mb-1"/> Swap
                        </button>
                      </>
                  )}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                      <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20">Select card to Add</div>
                  )}
                  {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2"
                        >
                            <Sword size={16} /> Attack
                        </button>
                        <button 
                            onClick={() => setShowEndTurnModal(true)}
                            className={`bg-slate-700 hover:bg-slate-600 text-white font-bold rounded ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}
                  {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50">
                          Confirm Attackers ({gameState.pendingAttackers.length})
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50">
                          Confirm Blocks
                      </button>
                  )}
              </div>
          </div>
      </div>

      {/* Logs */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40 space-y-1">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in">{log}</div>
          ))}
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);

  // UI State
  const [dragState, setDragState] = useState<DragState | null>(null);
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);

  // Refs for tracking DOM positions for lines and flying text
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, []);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  // Determine if the "End Turn" button should be highlighted
  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      // 1. Can play a card?
      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);

      // 2. Can attack?
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Drag & Drop Logic --

  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      // Prevent dragging if not allowed
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      // Block Phase: Only allow dragging defenders
      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') {
          // Allow
      } 
      // Main Phase: Only allow dragging hand cards (or maybe field cards later for abilities, but sticking to basics)
      else if (gameState.phase === Phase.MAIN && type === 'HAND') {
          // Allow
      }
      else {
          return; // Block drag
      }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      // Use document.elementFromPoint to find what we dropped on
      // We look for elements with 'data-instance-id' or 'id="field-area"'
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return; // Dropped in void

      // -- PLAYING CARDS FROM HAND --
      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');

          if (targetElement.id === 'field-area' || targetInstanceId) {
             // Logic to play card
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }

      // -- DECLARING BLOCKERS --
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      // Cost Check
      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      // Target Check
      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return; // Must drop on a target

          // Execute Targeted Play
          // Find target card
          let targetOwnerId = -1;
          let targetCardIndex = -1;

          gameState.players.forEach(p => {
              const idx = p.field.findIndex(f => f.instanceId === targetInstanceId);
              if (idx !== -1) {
                  targetOwnerId = p.id;
                  targetCardIndex = idx;
              }
          });

          if (targetOwnerId === -1) return;

          // We essentially simulate the 2-step process in one go
          // 1. Pay Cost
          // 2. Execute Effect
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          // Soldier or Jack -> Play normally (no target needed, just field drop)
          playCardImmediate(card);
      }
  };

  const playCardImmediate = (card: Card, targetId?: string, targetOwnerId?: number) => {
       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           const cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           // Pay Cost
           let toTap = card.cost;
           for (const res of p.resources) {
               if (!res.isTapped && toTap > 0) {
                   res.isTapped = true;
                   toTap--;
               }
           }

           // Remove from hand
           p.hand.splice(cardIdx, 1);

           // Effects
           if (card.rank === 'J') {
               p.discard.push(card);
               let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
               for(let i=0; i<2; i++) {
                   if(sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
               }
               return { ...prev, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
           } 
           else if (card.rank === 'Q' || card.rank === 'K') {
               const targetPlayer = prev.players[targetOwnerId!];
               const targetCardIdx = targetPlayer.field.findIndex(f => f.instanceId === targetId);
               if (targetCardIdx === -1) return prev; // Should not happen given checks
               const targetCard = targetPlayer.field[targetCardIdx];

               if (card.rank === 'K') {
                   const kingColor = card.baseColor;
                   const targetColor = getEffectiveColor(targetCard);
                   if (kingColor !== targetColor) {
                        // Refund (Revert state logic is hard here, so we just don't do it? 
                        // Or we allow invalid play to fizzle? Let's block it earlier ideally, but here we just return prev and untap resources? 
                        // For simplicity, we assume player checked. If invalid, we undo cost payment manually here or just fail safe.
                        // Let's just fail safe and revert the hand/tap.
                        p.hand.push(card);
                        // Untap resources (simplistic: untap 'cost' amount of resources)
                        let toUntap = card.cost;
                        for(const res of p.resources) { if(res.isTapped && toUntap > 0) { res.isTapped = false; toUntap--; }}
                        return { ...prev, logs: addLog(prev, "Invalid Target: King can only kill same color.") };
                   }
                   p.discard.push(card);
                   targetPlayer.field.splice(targetCardIdx, 1);
                   targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);
                   return { ...prev, logs: addLog(prev, "King executed a soldier.") };
               }
               else if (card.rank === 'Q') {
                   targetCard.attachedCards.push(card);
                   return { ...prev, logs: addLog(prev, "Queen attached. Spectrum shifted.") };
               }
           }
           else {
               // Soldier
               const newSoldier = createFieldCard(card, p.id);
               p.field.push(newSoldier);
               return { ...prev, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
           }

           return prev;
       });
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          // Validate
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];

          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker) return prev;
          if (blocker.isTapped) return prev; // Cannot block if tapped
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          // Register Block
          // Remove any existing block assignments for this blocker? 
          // One blocker blocks one attacker.
          const newBlocks = { ...prev.pendingBlocks };

          // If this blocker was blocking something else, remove that entry
          // Since pendingBlocks is { blockerId: attackerId }, we just overwrite
          newBlocks[blockerInstanceId] = attackerInstanceId;

          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  // -- Combat Logic & Animation --

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      // Default to center if no element
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      // Target is Life Icon in HUD
      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      // Cleanup
      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            let cardDrawn = false;
            let sourceDeck = newState.mode === 'STREET' ? newState.deck : player.library;

            if (sourceDeck.length > 0) {
                const card = sourceDeck.shift();
                if (card) {
                    player.hand.push(card);
                    player.consecutiveDrawFailures = 0;
                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                    cardDrawn = true;
                }
            } else {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }

            if (newState.phase !== Phase.GAME_OVER) {
                setTimeout(() => advancePhase(Phase.RESOURCE_START), 400);
            }
            break;

        case Phase.RESOURCE_START:
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached. Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 400);
            } else {
                newState.logs = addLog(newState, "Resource Step: Add or Swap?");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          // Auto-Skip Check: Does defender have ANY untapped units?
          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              // Go straight to damage, no blocks possible
              // Need to trigger useEffect, so set phase to DAMAGE
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "Attack declared! No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Attack declared! Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  // Async Combat Sequencer
  const gameStateRef = useRef<GameState | null>(null);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          // 1. Lunge
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          // 2. Logic & Visuals
          setGameState(prev => {
             if (!prev) return null;
             // Correctly find the blocker for this attacker
             // pendingBlocks: { blockerId: attackerId }
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 const defenderKey = defenderPlayer.id === 0 ? 'P0' : 'P1'; // P0 is P1 in UI? No, P0 is ID 0.
                 // Just map ID to Key
                 // Actually, let's just use the player's life for visual logic later or HUD
                 // We will spawn flying text here
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      // 3. Resolve State (Deaths/Damage)
      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      // Simple Click Handlers (Selection for Init, or specific interactions)
      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }

      // Resource Add/Swap Logic
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));
             let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
             if (sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
             else p.consecutiveDrawFailures++;
             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          // Swap logic
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }

      // Attack Declaration Tapping (Click Fallback)
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }

      // Remove Block (Defender Click)
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       // Logic to move cards to resources
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      return (
          <div className="flex items-center justify-center h-screen bg-slate-900 text-white">
              <div className="text-center space-y-4">
                  <h1 className="text-6xl font-bold font-title">BATTLE</h1>
                  <div className="flex gap-4">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 px-6 py-3 rounded font-bold">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 px-6 py-3 rounded font-bold">Play Pro</button>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Flying Text Layer */}
      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`
                @keyframes fly {
                    0% { transform: translate(0,0) scale(1); opacity: 1; }
                    80% { opacity: 1; }
                    100% { transform: translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.2); opacity: 0; }
                }
              `}</style>
          </div>
      ))}

      {/* SVG Connection Lines for Blocks */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
              // Draw line from dragging card to cursor
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500">Deck: {gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</div>
         </div>
      </div>

      {/* Field Area */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

          {/* Top Player (Opponent) */}
          <div className="flex-1 flex flex-col items-center justify-center p-4 border-b border-slate-800/30">
               <div className="absolute top-[-40px] flex -space-x-12 scale-75 opacity-70">
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} card={c} showBack size="sm" />)}
               </div>
               <div className="flex gap-16">
                   {/* Black Lane */}
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId} // For play target detection
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
                   {/* Red Lane */}
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Bottom Player (You) */}
          <div className="flex-1 flex flex-col items-center justify-center p-4">
               <div className="flex gap-16">
                   {/* Black Lane */}
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
                   {/* Red Lane */}
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Floating Dragged Card */}
          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      {/* Controls */}
      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30">

          {/* Stats */}
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2">
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 uppercase font-bold tracking-wider">
                  Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
              </div>
          </div>

          {/* Hand */}
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner">
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c: Card) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       const isPlayable = isMainPhase && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost;
                       return (
                           <div key={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e: React.MouseEvent) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          {/* Actions & Resources */}
          <div className="w-80 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3">
              <div className="flex justify-between items-baseline px-1">
                  <span className="text-[10px] font-bold text-slate-500 uppercase">Resources</span>
                  <span className="text-xs font-bold text-indigo-400">
                      {bottomPlayer.resources.filter(r => !r.isTapped).length} <span className="text-slate-600">/</span> {bottomPlayer.resources.length}
                  </span>
              </div>
              <div className="h-16 flex items-center gap-1 overflow-x-auto p-2 bg-black/40 rounded-lg shadow-inner">
                  {bottomPlayer.resources.map(r => (
                      <div key={r.instanceId} className="hover:scale-105 transition" onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id)}>
                          <CardDisplay card={r.card} size="sm" isTapped={r.isTapped} />
                      </div>
                  ))}
              </div>

              {/* Dynamic Buttons */}
              <div className="flex-1 grid grid-cols-2 gap-2">
                  {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button 
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1">
                            <ArrowUpCircle size={16} className="mb-1"/> Add
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1">
                            <RotateCcw size={16} className="mb-1"/> Swap
                        </button>
                      </>
                  )}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                      <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20">Select card to Add</div>
                  )}
                  {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2"
                        >
                            <Sword size={16} /> Attack
                        </button>
                        <button 
                            onClick={() => setShowEndTurnModal(true)}
                            className={`bg-slate-700 hover:bg-slate-600 text-white font-bold rounded ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}
                  {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50">
                          Confirm Attackers ({gameState.pendingAttackers.length})
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50">
                          Confirm Blocks
                      </button>
                  )}
              </div>
          </div>
      </div>

      {/* Logs */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40 space-y-1">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in">{log}</div>
          ))}
      </div>

    </div>
  );
};

export default App;

export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
  baseColor: Color;
}

export interface FieldCard {
  instanceId: string;
  card: Card;
  ownerId: number;
  isTapped: boolean;
  isSummoningSick: boolean;
  attachedCards: Card[]; // For Queens
  currentHealth: number; // Usually equals attack, but for tracking state
}

export enum Phase {
  INIT = 'INIT',
  INIT_SELECT = 'INIT_SELECT', // New phase for selecting starting resources
  UPKEEP = 'UPKEEP',
  DRAW = 'DRAW',
  RESOURCE_START = 'RESOURCE_START',
  RESOURCE_ADD_SELECT = 'RESOURCE_ADD_SELECT',
  RESOURCE_SWAP_SELECT_HAND = 'RESOURCE_SWAP_SELECT_HAND',
  RESOURCE_SWAP_SELECT_PILE = 'RESOURCE_SWAP_SELECT_PILE',
  MAIN = 'MAIN',
  ATTACK_DECLARE = 'ATTACK_DECLARE',
  BLOCK_DECLARE = 'BLOCK_DECLARE',
  DAMAGE = 'DAMAGE',
  GAME_OVER = 'GAME_OVER',
}

export interface PlayerState {
  id: number;
  name: string;
  life: number;
  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: FieldCard[]; // Changed from Card[] to FieldCard[] to support tapping
  field: FieldCard[];
  discard: Card[];
  consecutiveDrawFailures: number;
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO';

export interface GameState {
  mode: GameMode;
  deck: Card[]; // Shared deck for Street mode
  players: PlayerState[];
  turnPlayer: number; // 0 or 1
  phase: Phase;
  turnCount: number;
  pendingAttackers: string[]; // instanceIds
  pendingBlocks: Record<string, string>; // blockerId -> attackerId
  selectedCardId: string | null; // For hand interaction
  activeCombatCardId: string | null; // The card currently animating in combat
  initSelectedIds: string[]; // For multi-selection during INIT_SELECT
  targetMode: 'NONE' | 'QUEEN' | 'KING';
  sourceCardId: string | null; // The card initiating the target mode
  winner: number | null; // 0, 1, or -1 (Draw)
  recentDamage: Record<string, number>; // Maps instanceId (or 'P0'/'P1') to damage taken this phase
  logs: string[];
}

export interface DragState {
    cardId: string;
    sourceType: 'HAND' | 'FIELD';
    ownerId: number;
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    cardObj?: Card; // Helper to avoid lookups during render
    instanceId?: string; // For field cards
}

export interface FlyingText {
    id: string;
    text: string;
    startX: number;
    startY: number;
    targetX: number;
    targetY: number;
    createdAt: number;
    color: string;
}

export interface FlyingCard {
    id: string;
    card: Card;
    startX: number;
    startY: number;
    targetX: number;
    targetY: number;
    createdAt: number;
}

import { Card, Suit, Rank, Color, FieldCard } from './types';
import { CARD_VALUES } from './constants';

// Unique ID generator
export const generateId = () => Math.random().toString(36).substr(2, 9);

export const createDeck = (): Card[] => {
  const suits = [Suit.Spades, Suit.Clubs, Suit.Hearts, Suit.Diamonds];
  const ranks = Object.values(Rank);
  const deck: Card[] = [];

  for (const suit of suits) {
    for (const rank of ranks) {
      const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
      const numericValue = CARD_VALUES[rank];

      // Cost is equal to numeric value, except Ace=1, J=2, Q=3, K=4
      let cost = numericValue;
      if (rank === Rank.Jack) cost = 2;
      if (rank === Rank.Queen) cost = 3;
      if (rank === Rank.King) cost = 4;
      if (rank === Rank.Ace) cost = 1;

      deck.push({
        id: generateId(),
        suit,
        rank,
        numericValue,
        cost,
        baseColor
      });
    }
  }
  return shuffle(deck);
};

export const shuffle = <T>(array: T[]): T[] => {
  let currentIndex = array.length, randomIndex;
  while (currentIndex !== 0) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;
    [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
  }
  return array;
};

// Determine the EFFECTIVE color of a soldier (considering attached Queens)
export const getEffectiveColor = (fieldCard: FieldCard): Color => {
  // If a Queen is attached, the soldier takes the Queen's spectrum
  const attachedQueen = fieldCard.attachedCards.find(c => c.rank === Rank.Queen);
  if (attachedQueen) {
    return attachedQueen.baseColor;
  }
  return fieldCard.card.baseColor;
};

export const canBlock = (attacker: FieldCard, blocker: FieldCard): boolean => {
    // Must be in same lane (Same Effective Color)
    const attackerColor = getEffectiveColor(attacker);
    const blockerColor = getEffectiveColor(blocker);

    // Physical (Black) vs Physical (Black), Magical (Red) vs Magical (Red)
    return attackerColor === blockerColor;
};

export const createFieldCard = (card: Card, ownerId: number): FieldCard => ({
  instanceId: generateId(),
  card,
  ownerId,
  isTapped: false,
  isSummoningSick: true,
  attachedCards: [],
  currentHealth: card.numericValue
});

export const sortHand = (hand: Card[]): Card[] => {
  return [...hand].sort((a, b) => {
    // 1. Sort by Color: Black First, then Red
    if (a.baseColor !== b.baseColor) {
      return a.baseColor === Color.Black ? -1 : 1;
    }
    // 2. Sort by Value: High to Low
    return b.numericValue - a.numericValue;
  });
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, X, Check } from 'lucide-react';

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [autoSort, setAutoSort] = useState(false);

  // UI Overlays State
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  // Interaction State
  const [dragState, setDragState] = useState<DragState | null>(null);

  // Animation State
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Refs for tracking DOM positions
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);
  const p0DeckRef = useRef<HTMLDivElement>(null);
  const p1DeckRef = useRef<HTMLDivElement>(null);
  const handRef = useRef<HTMLDivElement>(null);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      if (autoSort) {
          hand.splice(0, hand.length, ...sortHand(hand));
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, [autoSort]);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  // Determine if the "End Turn" button should be highlighted
  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Animation Helpers --

  const spawnFlyingCard = (card: Card, startRef: React.RefObject<HTMLDivElement | null>, targetRef: React.RefObject<HTMLDivElement | null>, onComplete: () => void) => {
      if (!startRef.current || !targetRef.current) {
          onComplete();
          return;
      }
      const startRect = startRef.current.getBoundingClientRect();
      const targetRect = targetRef.current.getBoundingClientRect();

      const newFly: FlyingCard = {
          id: generateId(),
          card,
          startX: startRect.left + startRect.width / 2,
          startY: startRect.top + startRect.height / 2,
          targetX: targetRect.left + targetRect.width / 2,
          targetY: targetRect.top, // Fly to top of hand container
          createdAt: Date.now()
      };

      setFlyingCards(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingCards(prev => prev.filter(f => f.id !== newFly.id));
          onComplete();
      }, 800);
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            let cardDrawn = false;
            let sourceDeck = newState.mode === 'STREET' ? newState.deck : player.library;

            if (sourceDeck.length > 0) {
                const card = sourceDeck.shift();
                if (card) {
                    // Start Animation
                    // We need to trigger the state update for the deck removal, 
                    // BUT delay the hand addition for visual effect.
                    // Ideally we use effects, but here we can use the callback chain.
                    // We return the state with card removed from deck, but NOT yet in hand.

                    // However, we need to know WHICH deck ref to use.
                    // If STREET, usually use player's side or central. 
                    // Let's use the active player's "Deck" text position.
                    const isP0 = player.id === 0;
                    // Note: If player 1 is active, we are bottom (p1 is bottom if ID 1? No. Logic is: P0 vs P1. View is fixed?)
                    // View: "Bottom Player" is activeDecisionPlayerId.
                    // But deck refs are static P0 and P1.

                    // We'll perform the animation side-effect here (dirty but works for simple React app without saga/thunk)
                    const deckRef = player.id === 0 ? p0DeckRef : p1DeckRef;

                    spawnFlyingCard(card, deckRef, handRef, () => {
                        setGameState(currentState => {
                            if(!currentState) return null;
                            const p = currentState.players[player.id];
                            p.hand.push(card);
                            if(autoSort) {
                                p.hand = sortHand(p.hand);
                            }
                            return { ...currentState };
                        });
                    });

                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                    cardDrawn = true;
                }
            } else {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }

            if (newState.phase !== Phase.GAME_OVER) {
                setTimeout(() => advancePhase(Phase.RESOURCE_START), 1000); // Increased delay for animation
            }
            break;

        case Phase.RESOURCE_START:
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached. Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 400);
            } else {
                newState.logs = addLog(newState, "Resource Step: Add or Swap?");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          // Auto-Skip Check
          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "Attack declared! No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Attack declared! Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);

    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        const nextState = {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP 
        };

        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return prev; 
    });
  };

  // Async Combat Sequencer
  const gameStateRef = useRef<GameState | null>(null);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          // 1. Lunge
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          // 2. Logic & Visuals
          setGameState(prev => {
             if (!prev) return null;
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      // 3. Resolve State (Deaths/Damage)
      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  // -- Interaction Handlers --

  // (Drag Logic)
  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
      else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
      else { return; }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return;

      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetElement.id === 'field-area' || targetInstanceId) {
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return;
          let targetOwnerId = -1;
          gameState.players.forEach(p => {
              if (p.field.some(f => f.instanceId === targetInstanceId)) targetOwnerId = p.id;
          });
          if (targetOwnerId === -1) return;
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          playCardImmediate(card);
      }
  };

  const playCardImmediate = (card: Card, targetId?: string, targetOwnerId?: number) => {
       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           const cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           let toTap = card.cost;
           for (const res of p.resources) {
               if (!res.isTapped && toTap > 0) {
                   res.isTapped = true;
                   toTap--;
               }
           }
           p.hand.splice(cardIdx, 1);

           if (card.rank === 'J') {
               p.discard.push(card);
               let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
               for(let i=0; i<2; i++) {
                   if(sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
               }
               if(autoSort) p.hand = sortHand(p.hand);
               return { ...prev, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
           } 
           else if (card.rank === 'Q' || card.rank === 'K') {
               const targetPlayer = prev.players[targetOwnerId!];
               const targetCardIdx = targetPlayer.field.findIndex(f => f.instanceId === targetId);
               if (targetCardIdx === -1) return prev;
               const targetCard = targetPlayer.field[targetCardIdx];

               if (card.rank === 'K') {
                   const kingColor = card.baseColor;
                   const targetColor = getEffectiveColor(targetCard);
                   if (kingColor !== targetColor) {
                        p.hand.push(card);
                        if(autoSort) p.hand = sortHand(p.hand);
                        let toUntap = card.cost;
                        for(const res of p.resources) { if(res.isTapped && toUntap > 0) { res.isTapped = false; toUntap--; }}
                        return { ...prev, logs: addLog(prev, "Invalid Target: King can only kill same color.") };
                   }
                   p.discard.push(card);
                   targetPlayer.field.splice(targetCardIdx, 1);
                   targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);
                   return { ...prev, logs: addLog(prev, "King executed a soldier.") };
               }
               else if (card.rank === 'Q') {
                   targetCard.attachedCards.push(card);
                   return { ...prev, logs: addLog(prev, "Queen attached. Spectrum shifted.") };
               }
           }
           else {
               const newSoldier = createFieldCard(card, p.id);
               p.field.push(newSoldier);
               return { ...prev, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
           }
           return prev;
       });
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];
          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker || blocker.isTapped) return prev;
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          const newBlocks = { ...prev.pendingBlocks };
          newBlocks[blockerInstanceId] = attackerInstanceId;
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));
             let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
             if (sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
             else p.consecutiveDrawFailures++;
             if (autoSort) p.hand = sortHand(p.hand);
             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
                  if(autoSort) p.hand = sortHand(p.hand);
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      return (
          <div className="flex flex-col items-center justify-center h-screen bg-slate-900 text-white relative">
              <div className="text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <h1 className="text-8xl font-bold font-title bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</h1>
                  <div className="flex gap-4 justify-center">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 hover:bg-indigo-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-indigo-900/50">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 hover:bg-red-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-red-900/50">Play Pro</button>
                  </div>
                  <div className="flex items-center justify-center gap-2 mt-8">
                      <input 
                        type="checkbox" 
                        id="sort" 
                        checked={autoSort} 
                        onChange={(e) => setAutoSort(e.target.checked)}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="sort" className="text-slate-300 select-none cursor-pointer">Auto-Sort Hand (Spectrum & Value)</label>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Modals & Overlays */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>
                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Animation Layers */}
      {flyingCards.map(fc => (
          <div 
            key={fc.id}
            className="fixed z-[60] transition-all duration-700 ease-in-out"
            style={{ 
                left: fc.startX, 
                top: fc.startY,
                transform: `translate(${fc.targetX - fc.startX}px, ${fc.targetY - fc.startY}px) rotate(360deg) scale(0.5)`,
            }}
          >
              <CardDisplay card={fc.card} showBack size="md" />
          </div>
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {/* SVG Connection Lines */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500 font-bold" ref={topPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                 Deck: <span className="text-slate-200">{gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
             </div>
             <button onClick={() => setShowMenu(true)} className="p-2 hover:bg-slate-800 rounded-full transition">
                 <Settings size={20} className="text-slate-400" />
             </button>
         </div>
      </div>

      {/* Field Area */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

          {/* Top Player (Opponent) */}
          <div className="flex-1 flex flex-col justify-center p-4 border-b border-slate-800/30 relative">

               {/* Opponent Resources (Left) */}
               <div className="absolute left-4 top-1/2 -translate-y-1/2 flex flex-col gap-1 items-center">
                   <div className="text-[10px] text-slate-600 font-bold uppercase -rotate-90 mb-2">Resources</div>
                   <div className="flex flex-col-reverse -space-y-16 scale-75 origin-left">
                       {topPlayer.resources.map(r => (
                           <div key={r.instanceId} className="transition-transform duration-300">
                               <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" showBack />
                           </div>
                       ))}
                   </div>
                   <div className="text-xs font-bold text-slate-500 mt-2">{topPlayer.resources.length}</div>
               </div>

               {/* Opponent Hand (Top) */}
               <div className="absolute top-[-40px] left-1/2 -translate-x-1/2 flex -space-x-12 scale-75 opacity-70">
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} card={c} showBack size="sm" />)}
               </div>

               {/* Lanes */}
               <div className="flex justify-center gap-16 w-full">
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId} 
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Bottom Player (You) */}
          <div className="flex-1 flex flex-col justify-center p-4 relative">

               {/* Player Resources (Left) */}
               <div className="absolute left-4 top-1/2 -translate-y-1/2 flex flex-col gap-1 items-center z-10">
                   <div className="text-[10px] text-indigo-400 font-bold uppercase -rotate-90 mb-2">Resources</div>
                   <div className="flex flex-col -space-y-16 scale-75 origin-left">
                       {bottomPlayer.resources.map(r => (
                           <div 
                                key={r.instanceId} 
                                className="transition-transform duration-300 hover:z-10 hover:-translate-x-4 cursor-pointer"
                                onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id)}
                           >
                               <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" />
                           </div>
                       ))}
                   </div>
                   <div className="text-xs font-bold text-indigo-400 mt-2">
                       {bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}
                   </div>
               </div>

               {/* Lanes */}
               <div className="flex justify-center gap-16 w-full">
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Floating Dragged Card */}
          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      {/* Controls */}
      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30">

          {/* Stats */}
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2">
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 uppercase font-bold tracking-wider" ref={bottomPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                  Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
              </div>
          </div>

          {/* Hand */}
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner" ref={handRef}>
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c: Card) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       const isPlayable = isMainPhase && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost;
                       return (
                           <div key={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e: React.MouseEvent) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          {/* Actions Panel */}
          <div className="w-64 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3">
              <div className="text-center text-xs font-bold text-slate-500 uppercase mb-2">Actions</div>

              <div className="flex-1 grid grid-cols-2 gap-2 content-start">
                  {/* Init Phase */}
                  {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button 
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg h-12"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {/* Resource Phase */}
                  {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <ArrowUpCircle size={20} className="mb-1"/> Add & Draw
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <RotateCcw size={20} className="mb-1"/> Swap Res
                        </button>
                      </>
                  )}
                  {/* Resource Select Info */}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                      <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20 h-12">
                          Select card to Add
                      </div>
                  )}
                  {gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && (
                      <div className="col-span-2 text-center text-xs text-amber-400 animate-pulse font-bold flex items-center justify-center border border-amber-900 rounded bg-amber-900/20 h-12">
                          Select Resource to Swap
                      </div>
                  )}

                  {/* Main Phase */}
                  {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2 h-10 transition-transform active:scale-95"
                        >
                            <Sword size={18} /> Attack Phase
                        </button>
                        <button 
                            onClick={requestEndTurn}
                            className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}

                  {/* Combat Phases */}
                  {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12">
                          Confirm Attackers
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">
                          Confirm Blocks
                      </button>
                  )}
              </div>
          </div>
      </div>

      {/* Logs */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40 space-y-1">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in">{log}</div>
          ))}
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, X, Check } from 'lucide-react';

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [autoSort, setAutoSort] = useState(false);

  // UI Overlays State
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  // Interaction State
  const [dragState, setDragState] = useState<DragState | null>(null);

  // Animation State
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Refs for tracking DOM positions
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);
  const p0DeckRef = useRef<HTMLDivElement>(null);
  const p1DeckRef = useRef<HTMLDivElement>(null);
  const handRef = useRef<HTMLDivElement>(null);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      if (autoSort) {
          hand.splice(0, hand.length, ...sortHand(hand));
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, [autoSort]);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  // Determine if the "End Turn" button should be highlighted
  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Animation Helpers --

  const spawnFlyingCard = (card: Card, startRef: React.RefObject<HTMLDivElement | null>, targetRef: React.RefObject<HTMLDivElement | null>, onComplete: () => void) => {
      if (!startRef.current || !targetRef.current) {
          onComplete();
          return;
      }
      const startRect = startRef.current.getBoundingClientRect();
      const targetRect = targetRef.current.getBoundingClientRect();

      const newFly: FlyingCard = {
          id: generateId(),
          card,
          startX: startRect.left + startRect.width / 2,
          startY: startRect.top + startRect.height / 2,
          targetX: targetRect.left + targetRect.width / 2,
          targetY: targetRect.top, // Fly to top of hand container
          createdAt: Date.now()
      };

      setFlyingCards(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingCards(prev => prev.filter(f => f.id !== newFly.id));
          onComplete();
      }, 800);
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            let cardDrawn = false;
            let sourceDeck = newState.mode === 'STREET' ? newState.deck : player.library;

            if (sourceDeck.length > 0) {
                const card = sourceDeck.shift();
                if (card) {
                    // Start Animation
                    // We need to trigger the state update for the deck removal, 
                    // BUT delay the hand addition for visual effect.
                    // Ideally we use effects, but here we can use the callback chain.
                    // We return the state with card removed from deck, but NOT yet in hand.

                    // However, we need to know WHICH deck ref to use.
                    // If STREET, usually use player's side or central. 
                    // Let's use the active player's "Deck" text position.
                    const isP0 = player.id === 0;
                    // Note: If player 1 is active, we are bottom (p1 is bottom if ID 1? No. Logic is: P0 vs P1. View is fixed?)
                    // View: "Bottom Player" is activeDecisionPlayerId.
                    // But deck refs are static P0 and P1.

                    // We'll perform the animation side-effect here (dirty but works for simple React app without saga/thunk)
                    const deckRef = player.id === 0 ? p0DeckRef : p1DeckRef;

                    spawnFlyingCard(card, deckRef, handRef, () => {
                        setGameState(currentState => {
                            if(!currentState) return null;
                            const p = currentState.players[player.id];
                            p.hand.push(card);
                            if(autoSort) {
                                p.hand = sortHand(p.hand);
                            }
                            return { ...currentState };
                        });
                    });

                    newState.logs = addLog(newState, `${player.name} drew a card.`);
                    cardDrawn = true;
                }
            } else {
                player.consecutiveDrawFailures++;
                newState.logs = addLog(newState, `${player.name} cannot draw (Empty Deck).`);
                checkGameOver(newState);
            }

            if (newState.phase !== Phase.GAME_OVER) {
                setTimeout(() => advancePhase(Phase.RESOURCE_START), 1000); // Increased delay for animation
            }
            break;

        case Phase.RESOURCE_START:
            const isTurn1Player1 = newState.turnCount === 1 && newState.turnPlayer === 0;
            const hasMaxResources = player.resources.length >= MAX_RESOURCES;

            if (isTurn1Player1 || hasMaxResources) {
                newState.logs = addLog(newState, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached. Step skipped.");
                setTimeout(() => advancePhase(Phase.MAIN), 400);
            } else {
                newState.logs = addLog(newState, "Resource Step: Add or Swap?");
            }
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase: Play cards or Declare Attack.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;

        case Phase.DAMAGE:
            break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          // Auto-Skip Check
          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "Attack declared! No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Attack declared! Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);

    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        const nextState = {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP 
        };

        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return prev; 
    });
  };

  // Async Combat Sequencer
  const gameStateRef = useRef<GameState | null>(null);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          // 1. Lunge
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          // 2. Logic & Visuals
          setGameState(prev => {
             if (!prev) return null;
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      // 3. Resolve State (Deaths/Damage)
      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  // -- Interaction Handlers --

  // (Drag Logic)
  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
      else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
      else { return; }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return;

      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetElement.id === 'field-area' || targetInstanceId) {
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return;
          let targetOwnerId = -1;
          gameState.players.forEach(p => {
              if (p.field.some(f => f.instanceId === targetInstanceId)) targetOwnerId = p.id;
          });
          if (targetOwnerId === -1) return;
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          playCardImmediate(card);
      }
  };

  const playCardImmediate = (card: Card, targetId?: string, targetOwnerId?: number) => {
       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           const cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           let toTap = card.cost;
           for (const res of p.resources) {
               if (!res.isTapped && toTap > 0) {
                   res.isTapped = true;
                   toTap--;
               }
           }
           p.hand.splice(cardIdx, 1);

           if (card.rank === 'J') {
               p.discard.push(card);
               let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
               for(let i=0; i<2; i++) {
                   if(sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
               }
               if(autoSort) p.hand = sortHand(p.hand);
               return { ...prev, logs: addLog(prev, "Played Jack: Drew 2 cards.") };
           } 
           else if (card.rank === 'Q' || card.rank === 'K') {
               const targetPlayer = prev.players[targetOwnerId!];
               const targetCardIdx = targetPlayer.field.findIndex(f => f.instanceId === targetId);
               if (targetCardIdx === -1) return prev;
               const targetCard = targetPlayer.field[targetCardIdx];

               if (card.rank === 'K') {
                   const kingColor = card.baseColor;
                   const targetColor = getEffectiveColor(targetCard);
                   if (kingColor !== targetColor) {
                        p.hand.push(card);
                        if(autoSort) p.hand = sortHand(p.hand);
                        let toUntap = card.cost;
                        for(const res of p.resources) { if(res.isTapped && toUntap > 0) { res.isTapped = false; toUntap--; }}
                        return { ...prev, logs: addLog(prev, "Invalid Target: King can only kill same color.") };
                   }
                   p.discard.push(card);
                   targetPlayer.field.splice(targetCardIdx, 1);
                   targetPlayer.discard.push(targetCard.card, ...targetCard.attachedCards);
                   return { ...prev, logs: addLog(prev, "King executed a soldier.") };
               }
               else if (card.rank === 'Q') {
                   targetCard.attachedCards.push(card);
                   return { ...prev, logs: addLog(prev, "Queen attached. Spectrum shifted.") };
               }
           }
           else {
               const newSoldier = createFieldCard(card, p.id);
               p.field.push(newSoldier);
               return { ...prev, logs: addLog(prev, `Conscripted ${card.rank}${card.suit}.`) };
           }
           return prev;
       });
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];
          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker || blocker.isTapped) return prev;
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          const newBlocks = { ...prev.pendingBlocks };
          newBlocks[blockerInstanceId] = attackerInstanceId;
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const handleCardClick = (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));
             let sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;
             if (sourceDeck.length > 0) p.hand.push(sourceDeck.shift()!);
             else p.consecutiveDrawFailures++;
             if (autoSort) p.hand = sortHand(p.hand);
             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Added resource and drew a card.") };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
                  if(autoSort) p.hand = sortHand(p.hand);
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      return (
          <div className="flex flex-col items-center justify-center h-screen bg-slate-900 text-white relative">
              <div className="text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <h1 className="text-8xl font-bold font-title bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</h1>
                  <div className="flex gap-4 justify-center">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 hover:bg-indigo-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-indigo-900/50">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 hover:bg-red-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-red-900/50">Play Pro</button>
                  </div>
                  <div className="flex items-center justify-center gap-2 mt-8">
                      <input 
                        type="checkbox" 
                        id="sort" 
                        checked={autoSort} 
                        onChange={(e) => setAutoSort(e.target.checked)}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="sort" className="text-slate-300 select-none cursor-pointer">Auto-Sort Hand (Spectrum & Value)</label>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Modals & Overlays */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>
                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Animation Layers */}
      {flyingCards.map(fc => (
          <div 
            key={fc.id}
            className="fixed z-[60] transition-all duration-700 ease-in-out"
            style={{ 
                left: fc.startX, 
                top: fc.startY,
                transform: `translate(${fc.targetX - fc.startX}px, ${fc.targetY - fc.startY}px) rotate(360deg) scale(0.5)`,
            }}
          >
              <CardDisplay card={fc.card} showBack size="md" />
          </div>
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {/* SVG Connection Lines */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500 font-bold" ref={topPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                 Deck: <span className="text-slate-200">{gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
             </div>
             <button onClick={() => setShowMenu(true)} className="p-2 hover:bg-slate-800 rounded-full transition">
                 <Settings size={20} className="text-slate-400" />
             </button>
         </div>
      </div>

      {/* Field Area */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

          {/* Top Player (Opponent) */}
          <div className="flex-1 flex flex-col justify-center p-4 border-b border-slate-800/30 relative">

               {/* Opponent Resources (Left) */}
               <div className="absolute left-4 top-1/2 -translate-y-1/2 flex flex-col gap-1 items-center">
                   <div className="text-[10px] text-slate-600 font-bold uppercase -rotate-90 mb-2">Resources</div>
                   <div className="flex flex-col-reverse -space-y-16 scale-75 origin-left">
                       {topPlayer.resources.map(r => (
                           <div key={r.instanceId} className="transition-transform duration-300">
                               <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" showBack />
                           </div>
                       ))}
                   </div>
                   <div className="text-xs font-bold text-slate-500 mt-2">{topPlayer.resources.length}</div>
               </div>

               {/* Opponent Hand (Top) */}
               <div className="absolute top-[-40px] left-1/2 -translate-x-1/2 flex -space-x-12 scale-75 opacity-70">
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} card={c} showBack size="sm" />)}
               </div>

               {/* Lanes */}
               <div className="flex justify-center gap-16 w-full">
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId} 
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
                   <div className="flex gap-2">
                       {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              orientation="top"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Bottom Player (You) */}
          <div className="flex-1 flex flex-col justify-center p-4 relative">

               {/* Player Resources (Left) */}
               <div className="absolute left-4 top-1/2 -translate-y-1/2 flex flex-col gap-1 items-center z-10">
                   <div className="text-[10px] text-indigo-400 font-bold uppercase -rotate-90 mb-2">Resources</div>
                   <div className="flex flex-col -space-y-16 scale-75 origin-left">
                       {bottomPlayer.resources.map(r => (
                           <div 
                                key={r.instanceId} 
                                className="transition-transform duration-300 hover:z-10 hover:-translate-x-4 cursor-pointer"
                                onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id)}
                           >
                               <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" />
                           </div>
                       ))}
                   </div>
                   <div className="text-xs font-bold text-indigo-400 mt-2">
                       {bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}
                   </div>
               </div>

               {/* Lanes */}
               <div className="flex justify-center gap-16 w-full">
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
                   <div className="flex gap-2">
                       {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                           <CardDisplay 
                              key={fc.instanceId} 
                              domId={fc.instanceId}
                              card={fc.card} 
                              data-instance-id={fc.instanceId}
                              isTapped={fc.isTapped}
                              isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                              isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                              isLunging={gameState.activeCombatCardId === fc.instanceId}
                              damageTaken={gameState.recentDamage[fc.instanceId]}
                              onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                              isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                              orientation="bottom"
                           />
                       ))}
                   </div>
               </div>
          </div>

          {/* Floating Dragged Card */}
          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      {/* Controls */}
      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30">

          {/* Stats */}
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2">
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 uppercase font-bold tracking-wider" ref={bottomPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                  Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
              </div>
          </div>

          {/* Hand */}
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner" ref={handRef}>
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c: Card) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       const isPlayable = isMainPhase && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost;
                       return (
                           <div key={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          {/* Actions Panel */}
          <div className="w-64 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3">
              <div className="text-center text-xs font-bold text-slate-500 uppercase mb-2">Actions</div>

              <div className="flex-1 grid grid-cols-2 gap-2 content-start">
                  {/* Init Phase */}
                  {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button 
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg h-12"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {/* Resource Phase */}
                  {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <ArrowUpCircle size={20} className="mb-1"/> Add & Draw
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <RotateCcw size={20} className="mb-1"/> Swap Res
                        </button>
                      </>
                  )}
                  {/* Resource Select Info */}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                      <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20 h-12">
                          Select card to Add
                      </div>
                  )}
                  {gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && (
                      <div className="col-span-2 text-center text-xs text-amber-400 animate-pulse font-bold flex items-center justify-center border border-amber-900 rounded bg-amber-900/20 h-12">
                          Select Resource to Swap
                      </div>
                  )}

                  {/* Main Phase */}
                  {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2 h-10 transition-transform active:scale-95"
                        >
                            <Sword size={18} /> Attack Phase
                        </button>
                        <button 
                            onClick={requestEndTurn}
                            className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}

                  {/* Combat Phases */}
                  {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12">
                          Confirm Attackers
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">
                          Confirm Blocks
                      </button>
                  )}
              </div>
          </div>
      </div>

      {/* Logs */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40 space-y-1">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in">{log}</div>
          ))}
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef, useLayoutEffect } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, X, Check } from 'lucide-react';

// -- Sub-Components --

const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(1) rotate(0deg)',
        transition: 'transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        // Force reflow
        const deltaX = fc.targetX - fc.startX;
        const deltaY = fc.targetY - fc.startY;

        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                transform: `translate(${deltaX}px, ${deltaY}px) scale(0.6) rotate(360deg)`
            }));
        });
    }, [fc]);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={true} size="md" />
        </div>
    );
};

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [autoSort, setAutoSort] = useState(false);

  // UI Overlays State
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  // Interaction State
  const [dragState, setDragState] = useState<DragState | null>(null);

  // Animation State
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Refs for tracking DOM positions
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);
  const p0DeckRef = useRef<HTMLDivElement>(null);
  const p1DeckRef = useRef<HTMLDivElement>(null);
  const handRef = useRef<HTMLDivElement>(null);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      if (autoSort) {
          hand.splice(0, hand.length, ...sortHand(hand));
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, [autoSort]);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Animation Core --

  const triggerFlyer = async (card: Card, startRect: DOMRect, targetRect: DOMRect): Promise<void> => {
      return new Promise(resolve => {
          const id = generateId();
          const newFly: FlyingCard = {
              id,
              card,
              startX: startRect.left,
              startY: startRect.top,
              targetX: targetRect.left + targetRect.width / 2 - 20, // Center roughly
              targetY: targetRect.top + targetRect.height / 2 - 30,
              createdAt: Date.now()
          };
          setFlyingCards(prev => [...prev, newFly]);
          setTimeout(() => {
              setFlyingCards(prev => prev.filter(f => f.id !== id));
              resolve();
          }, 600);
      });
  };

  // -- Complex Actions (Async) --

  const drawCards = async (playerId: number, count: number) => {
      for (let i = 0; i < count; i++) {
          // 1. Peek and Remove from Deck State
          let drawnCard: Card | null = null;

          // We need a ref to the current game state to avoid closures issues, 
          // but since we are inside a function called from an event handler or effect, 
          // we should use the functional update pattern carefully or refs.
          // For simplicity in this structure, we'll do a synchronous check then async anim then update.

          await new Promise<void>(resolve => {
            setGameState(prev => {
                if(!prev) return null;
                const p = prev.players[playerId];
                const sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;

                if (sourceDeck.length === 0) {
                    p.consecutiveDrawFailures++;
                    return { ...prev };
                }

                drawnCard = sourceDeck.shift()!;
                p.consecutiveDrawFailures = 0;
                return { ...prev };
            });
            // State update triggers re-render, but we continue immediately in this task queue usually
            // We use setTimeout 0 to ensure state applied if needed, but here we just need the 'drawnCard' var.
            resolve();
          });

          if (drawnCard) {
              // 2. Animate
              const deckRef = playerId === 0 ? p0DeckRef : p1DeckRef;
              if (deckRef.current && handRef.current) {
                  await triggerFlyer(drawnCard, deckRef.current.getBoundingClientRect(), handRef.current.getBoundingClientRect());
              }

              // 3. Add to Hand State
              setGameState(prev => {
                  if(!prev) return null;
                  const p = prev.players[playerId];
                  p.hand.push(drawnCard!);
                  if (autoSort) p.hand = sortHand(p.hand);
                  return { ...prev, logs: addLog(prev, `${p.name} drew a card.`) };
              });
          } else {
              setGameState(prev => prev ? ({ ...prev, logs: addLog(prev, "Could not draw (Deck Empty).") }) : null);
              // Check game over in state effect or here?
              // Simple check
              setGameState(prev => {
                 if(!prev) return null;
                 if(prev.players[0].consecutiveDrawFailures > 0 && prev.players[1].consecutiveDrawFailures > 0) {
                     checkGameOver(prev);
                 }
                 return prev;
              });
          }
          await new Promise(r => setTimeout(r, 100)); // Small delay between multiple draws
      }
  };

  const handleResourceAdd = async () => {
      // Logic: Move card from Hand -> Resource (Animate), Then Draw
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      // We are in RESOURCE_ADD_SELECT phase, waiting for user to click hand
      // This is called by handleCardClick
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            // Delegate to async draw function? We can't await here easily inside setState.
            // We'll trigger an effect or separate function.
            // Workaround: Call the async function OUTSIDE the setGameState, 
            // but we are inside advancePhase which might be called from event handlers.
            // We will set phase to DRAW, and let a useEffect handle the async draw logic? 
            // Or just fire-and-forget the async function.
            setTimeout(() => {
                drawCards(player.id, 1).then(() => {
                     // After draw is done, move to Resource Start
                     setGameState(current => {
                         if(!current) return null;
                         // Check max resources
                         const p = current.players[current.turnPlayer];
                         const isTurn1Player1 = current.turnCount === 1 && current.turnPlayer === 0;
                         const hasMaxResources = p.resources.length >= MAX_RESOURCES;

                         if (isTurn1Player1 || hasMaxResources) {
                            // Skip Resource
                            setTimeout(() => advancePhase(Phase.MAIN), 400);
                            return { 
                                ...current, 
                                phase: Phase.RESOURCE_START, // Transient
                                logs: addLog(current, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached.") 
                            };
                         } else {
                            return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") };
                         }
                     });
                });
            }, 0);
            break;

        case Phase.RESOURCE_START:
            // Handled in Draw continuation
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);

    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        const nextState = {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP 
        };

        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return prev; 
    });
  };

  // Async Combat Sequencer
  const gameStateRef = useRef<GameState | null>(null);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          setGameState(prev => {
             if (!prev) return null;
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  // -- Interaction Handlers --

  // (Drag Logic)
  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
      else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
      else { return; }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return;

      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetElement.id === 'field-area' || targetInstanceId) {
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return;
          let targetOwnerId = -1;
          gameState.players.forEach(p => {
              if (p.field.some(f => f.instanceId === targetInstanceId)) targetOwnerId = p.id;
          });
          if (targetOwnerId === -1) return;
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          playCardImmediate(card);
      }
  };

  const playCardImmediate = async (card: Card, targetId?: string, targetOwnerId?: number) => {
       // Must break this into async logic to handle Jack animations
       let cardIdx = -1;
       let playedCard: Card | null = null;

       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           // Copy hand to avoid mutation until we are ready
           const newHand = [...p.hand];
           [playedCard] = newHand.splice(cardIdx, 1);

           // Pay Cost
           let toTap = card.cost;
           const newResources = p.resources.map(r => {
               if (!r.isTapped && toTap > 0) {
                   toTap--;
                   return { ...r, isTapped: true };
               }
               return r;
           });

           // Effects
           const nextState = { ...prev, players: [...prev.players] };
           const nextPlayer = { ...p, hand: newHand, resources: newResources };
           nextState.players[prev.turnPlayer] = nextPlayer;

           // Jack
           if (card.rank === 'J') {
               nextPlayer.discard.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Played Jack: Drawing 2...") };
           }
           // King
           else if (card.rank === 'K') {
               const targetP = nextState.players[targetOwnerId!];
               const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
               if (targetFIdx === -1) return prev; // Fail
               const targetF = targetP.field[targetFIdx];

               if (getEffectiveColor(targetF) !== card.baseColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") };
               }

               nextPlayer.discard.push(playedCard!);
               targetP.field.splice(targetFIdx, 1);
               targetP.discard.push(targetF.card, ...targetF.attachedCards);
               return { ...nextState, logs: addLog(nextState, "King executed soldier.") };
           }
           // Queen
           else if (card.rank === 'Q') {
               const targetP = nextState.players[targetOwnerId!];
               const targetF = targetP.field.find(f => f.instanceId === targetId);
               if(targetF) targetF.attachedCards.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Queen attached.") };
           }
           // Soldier
           else {
               const newSoldier = createFieldCard(playedCard!, p.id);
               nextPlayer.field.push(newSoldier);
               return { ...nextState, logs: addLog(nextState, `Conscripted ${card.rank}.`) };
           }
       });

       // Post-Update Asyncs (Jack Draw)
       if (card.rank === 'J' && gameState) {
           await drawCards(gameState.turnPlayer, 2);
       }
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];
          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker || blocker.isTapped) return prev;
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          const newBlocks = { ...prev.pendingBlocks };
          newBlocks[blockerInstanceId] = attackerInstanceId;
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          // Animate Hand -> Resource
          const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
          const cardEl = document.getElementById(card.id); // Assuming we added ID to CardDisplay
          if (cardEl && targetResourceContainer) {
              await triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect());
          }

          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Resource Added.") };
          });

          // Draw
          await drawCards(activePlayerId, 1);
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          // Animation: Hand -> Resource, Resource -> Hand
          if (gameState.selectedCardId) {
              const handCardEl = document.getElementById(gameState.selectedCardId);
              const resCardEl = document.getElementById(instanceId!); // Instance ID is usually reliable for field
              const handContainer = handRef.current;

              const handCard = gameState.players[activePlayerId].hand.find(c => c.id === gameState.selectedCardId);

              if (handCard && handCardEl && resCardEl && handContainer) {
                  // Parallel Animation
                  const p1 = triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                  const p2 = triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                  await Promise.all([p1, p2]);
              }
          }

          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
                  if(autoSort) p.hand = sortHand(p.hand);
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      return (
          <div className="flex flex-col items-center justify-center h-screen bg-slate-900 text-white relative">
              <div className="text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <h1 className="text-8xl font-bold font-title bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</h1>
                  <div className="flex gap-4 justify-center">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 hover:bg-indigo-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-indigo-900/50">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 hover:bg-red-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-red-900/50">Play Pro</button>
                  </div>
                  <div className="flex items-center justify-center gap-2 mt-8">
                      <input 
                        type="checkbox" 
                        id="sort" 
                        checked={autoSort} 
                        onChange={(e) => setAutoSort(e.target.checked)}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="sort" className="text-slate-300 select-none cursor-pointer">Auto-Sort Hand (Spectrum & Value)</label>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Modals & Overlays */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>
                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Animation Layers */}
      {flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {/* SVG Connection Lines */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500 font-bold" ref={topPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                 Deck: <span className="text-slate-200">{gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
             </div>
             <button onClick={() => setShowMenu(true)} className="p-2 hover:bg-slate-800 rounded-full transition">
                 <Settings size={20} className="text-slate-400" />
             </button>
         </div>
      </div>

      {/* Field Area */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

          {/* Top Player (Opponent) */}
          <div className="flex-1 flex flex-col justify-center p-4 border-b border-slate-800/30 relative">

               {/* Opponent Hand (Top) */}
               <div className="absolute top-[-40px] left-1/2 -translate-x-1/2 flex -space-x-12 scale-75 opacity-70">
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} card={c} showBack size="sm" />)}
               </div>

               {/* Container for Field + Resources */}
               <div className="flex justify-center items-center gap-12 w-full h-full">

                   {/* Lanes */}
                   <div className="flex gap-4">
                       <div className="bg-slate-900/40 p-4 rounded-xl border border-slate-700/50 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                            {/* Black Lane */}
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId} 
                                  isTapped={fc.isTapped}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  orientation="top"
                               />
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-4 rounded-xl border border-red-900/30 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                            {/* Red Lane */}
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  orientation="top"
                               />
                           ))}
                       </div>
                   </div>

                   {/* Opponent Resources (Right) */}
                   <div id={`resource-container-${topPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-3 rounded-lg border border-slate-700/30">
                       <div className="text-[10px] text-slate-500 font-bold uppercase mb-2">Resources</div>
                       <div className="flex flex-col-reverse -space-y-16 scale-75 origin-top">
                           {topPlayer.resources.map(r => (
                               <div key={r.instanceId} className="transition-transform duration-300">
                                   <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" showBack />
                               </div>
                           ))}
                       </div>
                       <div className="text-xs font-bold text-slate-500 mt-12">{topPlayer.resources.length}</div>
                   </div>

               </div>
          </div>

          {/* Bottom Player (You) */}
          <div className="flex-1 flex flex-col justify-center p-4 relative">

               {/* Container for Field + Resources */}
               <div className="flex justify-center items-center gap-12 w-full h-full">

                   {/* Lanes */}
                   <div className="flex gap-4">
                       <div className="bg-slate-900/40 p-4 rounded-xl border border-slate-700/50 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                           {/* Black Lane */}
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                  isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-4 rounded-xl border border-red-900/30 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                           {/* Red Lane */}
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                  isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                   </div>

                   {/* Player Resources (Right) */}
                   <div id={`resource-container-${bottomPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-3 rounded-lg border border-slate-700/30">
                       <div className="text-[10px] text-indigo-400 font-bold uppercase mb-2">Resources</div>
                       <div className="flex flex-col -space-y-16 scale-75 origin-top">
                           {bottomPlayer.resources.map(r => (
                               <div 
                                    key={r.instanceId} 
                                    id={r.instanceId} // Necessary for swap animation lookup
                                    className="transition-transform duration-300 hover:z-10 hover:-translate-x-4 cursor-pointer"
                                    onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}
                               >
                                   <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" />
                               </div>
                           ))}
                       </div>
                       <div className="text-xs font-bold text-indigo-400 mt-12">
                           {bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}
                       </div>
                   </div>

               </div>
          </div>

          {/* Floating Dragged Card */}
          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      {/* Controls */}
      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30">

          {/* Stats */}
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2">
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 uppercase font-bold tracking-wider" ref={bottomPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                  Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
              </div>
          </div>

          {/* Hand */}
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner" ref={handRef}>
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c: Card) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       const isPlayable = isMainPhase && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost;
                       return (
                           <div key={c.id} id={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          {/* Actions Panel */}
          <div className="w-64 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3">
              <div className="text-center text-xs font-bold text-slate-500 uppercase mb-2">Actions</div>

              <div className="flex-1 grid grid-cols-2 gap-2 content-start">
                  {/* Init Phase */}
                  {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button 
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg h-12"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {/* Resource Phase */}
                  {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <ArrowUpCircle size={20} className="mb-1"/> Add & Draw
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <RotateCcw size={20} className="mb-1"/> Swap Res
                        </button>
                      </>
                  )}
                  {/* Resource Select Info */}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                      <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20 h-12">
                          Select card to Add
                      </div>
                  )}
                  {gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && (
                      <div className="col-span-2 text-center text-xs text-amber-400 animate-pulse font-bold flex items-center justify-center border border-amber-900 rounded bg-amber-900/20 h-12">
                          Select Resource to Swap
                      </div>
                  )}

                  {/* Main Phase */}
                  {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2 h-10 transition-transform active:scale-95"
                        >
                            <Sword size={18} /> Attack Phase
                        </button>
                        <button 
                            onClick={requestEndTurn}
                            className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}

                  {/* Combat Phases */}
                  {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12">
                          Confirm Attackers
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">
                          Confirm Blocks
                      </button>
                  )}
              </div>
          </div>
      </div>

      {/* Logs */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40 space-y-1">
          {gameState.logs.map((log, i) => (
              <div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in">{log}</div>
          ))}
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef, useLayoutEffect } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, X, Check } from 'lucide-react';

// -- Sub-Components --

const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(1) rotate(0deg)',
        transition: 'transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        // Force reflow
        const deltaX = fc.targetX - fc.startX;
        const deltaY = fc.targetY - fc.startY;

        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                transform: `translate(${deltaX}px, ${deltaY}px) scale(0.6) rotate(360deg)`
            }));
        });
    }, [fc]);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={true} size="md" />
        </div>
    );
};

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [autoSort, setAutoSort] = useState(false);

  // UI Overlays State
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  // Interaction State
  const [dragState, setDragState] = useState<DragState | null>(null);

  // Animation State
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Refs for tracking DOM positions
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);
  const p0DeckRef = useRef<HTMLDivElement>(null);
  const p1DeckRef = useRef<HTMLDivElement>(null);
  const handRef = useRef<HTMLDivElement>(null);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      if (autoSort) {
          hand.splice(0, hand.length, ...sortHand(hand));
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, [autoSort]);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Animation Core --

  const triggerFlyer = async (card: Card, startRect: DOMRect, targetRect: DOMRect): Promise<void> => {
      return new Promise(resolve => {
          const id = generateId();
          const newFly: FlyingCard = {
              id,
              card,
              startX: startRect.left,
              startY: startRect.top,
              targetX: targetRect.left + targetRect.width / 2 - 20, // Center roughly
              targetY: targetRect.top + targetRect.height / 2 - 30,
              createdAt: Date.now()
          };
          setFlyingCards(prev => [...prev, newFly]);
          setTimeout(() => {
              setFlyingCards(prev => prev.filter(f => f.id !== id));
              resolve();
          }, 600);
      });
  };

  // -- Complex Actions (Async) --

  const drawCards = async (playerId: number, count: number) => {
      for (let i = 0; i < count; i++) {
          // 1. Peek and Remove from Deck State
          let drawnCard: Card | null = null;

          // We need a ref to the current game state to avoid closures issues, 
          // but since we are inside a function called from an event handler or effect, 
          // we should use the functional update pattern carefully or refs.
          // For simplicity in this structure, we'll do a synchronous check then async anim then update.

          await new Promise<void>(resolve => {
            setGameState(prev => {
                if(!prev) return null;
                const p = prev.players[playerId];
                const sourceDeck = prev.mode === 'STREET' ? prev.deck : p.library;

                if (sourceDeck.length === 0) {
                    p.consecutiveDrawFailures++;
                    return { ...prev };
                }

                drawnCard = sourceDeck.shift()!;
                p.consecutiveDrawFailures = 0;
                return { ...prev };
            });
            // State update triggers re-render, but we continue immediately in this task queue usually
            // We use setTimeout 0 to ensure state applied if needed, but here we just need the 'drawnCard' var.
            resolve();
          });

          if (drawnCard) {
              // 2. Animate
              const deckRef = playerId === 0 ? p0DeckRef : p1DeckRef;
              if (deckRef.current && handRef.current) {
                  await triggerFlyer(drawnCard, deckRef.current.getBoundingClientRect(), handRef.current.getBoundingClientRect());
              }

              // 3. Add to Hand State
              setGameState(prev => {
                  if(!prev) return null;
                  const p = prev.players[playerId];
                  p.hand.push(drawnCard!);
                  if (autoSort) p.hand = sortHand(p.hand);
                  return { ...prev, logs: addLog(prev, `${p.name} drew a card.`) };
              });
          } else {
              setGameState(prev => prev ? ({ ...prev, logs: addLog(prev, "Could not draw (Deck Empty).") }) : null);
              // Check game over in state effect or here?
              // Simple check
              setGameState(prev => {
                 if(!prev) return null;
                 if(prev.players[0].consecutiveDrawFailures > 0 && prev.players[1].consecutiveDrawFailures > 0) {
                     checkGameOver(prev);
                 }
                 return prev;
              });
          }
          await new Promise(r => setTimeout(r, 100)); // Small delay between multiple draws
      }
  };

  const handleResourceAdd = async () => {
      // Logic: Move card from Hand -> Resource (Animate), Then Draw
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      // We are in RESOURCE_ADD_SELECT phase, waiting for user to click hand
      // This is called by handleCardClick
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            // Delegate to async draw function? We can't await here easily inside setState.
            // We'll trigger an effect or separate function.
            // Workaround: Call the async function OUTSIDE the setGameState, 
            // but we are inside advancePhase which might be called from event handlers.
            // We will set phase to DRAW, and let a useEffect handle the async draw logic? 
            // Or just fire-and-forget the async function.
            setTimeout(() => {
                drawCards(player.id, 1).then(() => {
                     // After draw is done, move to Resource Start
                     setGameState(current => {
                         if(!current) return null;
                         // Check max resources
                         const p = current.players[current.turnPlayer];
                         const isTurn1Player1 = current.turnCount === 1 && current.turnPlayer === 0;
                         const hasMaxResources = p.resources.length >= MAX_RESOURCES;

                         if (isTurn1Player1 || hasMaxResources) {
                            // Skip Resource
                            setTimeout(() => advancePhase(Phase.MAIN), 400);
                            return { 
                                ...current, 
                                phase: Phase.RESOURCE_START, // Transient
                                logs: addLog(current, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached.") 
                            };
                         } else {
                            return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") };
                         }
                     });
                });
            }, 0);
            break;

        case Phase.RESOURCE_START:
            // Handled in Draw continuation
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);

    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        const nextState = {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP 
        };

        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return prev; 
    });
  };

  // Async Combat Sequencer
  const gameStateRef = useRef<GameState | null>(null);
  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          setGameState(prev => {
             if (!prev) return null;
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  // -- Interaction Handlers --

  // (Drag Logic)
  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
      else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
      else { return; }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return;

      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetElement.id === 'field-area' || targetInstanceId) {
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return;
          let targetOwnerId = -1;
          gameState.players.forEach(p => {
              if (p.field.some(f => f.instanceId === targetInstanceId)) targetOwnerId = p.id;
          });
          if (targetOwnerId === -1) return;
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          playCardImmediate(card);
      }
  };

  const playCardImmediate = async (card: Card, targetId?: string, targetOwnerId?: number) => {
       // Must break this into async logic to handle Jack animations
       let cardIdx = -1;
       let playedCard: Card | null = null;

       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           // Copy hand to avoid mutation until we are ready
           const newHand = [...p.hand];
           [playedCard] = newHand.splice(cardIdx, 1);

           // Pay Cost
           let toTap = card.cost;
           const newResources = p.resources.map(r => {
               if (!r.isTapped && toTap > 0) {
                   toTap--;
                   return { ...r, isTapped: true };
               }
               return r;
           });

           // Effects
           const nextState = { ...prev, players: [...prev.players] };
           const nextPlayer = { ...p, hand: newHand, resources: newResources };
           nextState.players[prev.turnPlayer] = nextPlayer;

           // Jack
           if (card.rank === 'J') {
               nextPlayer.discard.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Played Jack: Drawing 2...") };
           }
           // King
           else if (card.rank === 'K') {
               const targetP = nextState.players[targetOwnerId!];
               const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
               if (targetFIdx === -1) return prev; // Fail
               const targetF = targetP.field[targetFIdx];

               if (getEffectiveColor(targetF) !== card.baseColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") };
               }

               nextPlayer.discard.push(playedCard!);
               targetP.field.splice(targetFIdx, 1);
               targetP.discard.push(targetF.card, ...targetF.attachedCards);
               return { ...nextState, logs: addLog(nextState, "King executed soldier.") };
           }
           // Queen
           else if (card.rank === 'Q') {
               const targetP = nextState.players[targetOwnerId!];
               const targetF = targetP.field.find(f => f.instanceId === targetId);
               if(targetF) targetF.attachedCards.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Queen attached.") };
           }
           // Soldier
           else {
               const newSoldier = createFieldCard(playedCard!, p.id);
               nextPlayer.field.push(newSoldier);
               return { ...nextState, logs: addLog(nextState, `Conscripted ${card.rank}.`) };
           }
       });

       // Post-Update Asyncs (Jack Draw)
       if (card.rank === 'J' && gameState) {
           await drawCards(gameState.turnPlayer, 2);
       }
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];
          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker || blocker.isTapped) return prev;
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          const newBlocks = { ...prev.pendingBlocks };
          newBlocks[blockerInstanceId] = attackerInstanceId;
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          // Animate Hand -> Resource
          const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
          const cardEl = document.getElementById(card.id); // Assuming we added ID to CardDisplay
          if (cardEl && targetResourceContainer) {
              await triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect());
          }

          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Resource Added.") };
          });

          // Draw
          await drawCards(activePlayerId, 1);
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          // Animation: Hand -> Resource, Resource -> Hand
          if (gameState.selectedCardId) {
              const handCardEl = document.getElementById(gameState.selectedCardId);
              const resCardEl = document.getElementById(instanceId!); // Instance ID is usually reliable for field
              const handContainer = handRef.current;

              const handCard = gameState.players[activePlayerId].hand.find(c => c.id === gameState.selectedCardId);

              if (handCard && handCardEl && resCardEl && handContainer) {
                  // Parallel Animation
                  const p1 = triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                  const p2 = triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                  await Promise.all([p1, p2]);
              }
          }

          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
                  if(autoSort) p.hand = sortHand(p.hand);
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      return (
          <div className="flex flex-col items-center justify-center h-screen bg-slate-900 text-white relative">
              <div className="text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <h1 className="text-8xl font-bold font-title bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</h1>
                  <div className="flex gap-4 justify-center">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 hover:bg-indigo-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-indigo-900/50">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 hover:bg-red-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-red-900/50">Play Pro</button>
                  </div>
                  <div className="flex items-center justify-center gap-2 mt-8">
                      <input 
                        type="checkbox" 
                        id="sort" 
                        checked={autoSort} 
                        onChange={(e) => setAutoSort(e.target.checked)}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="sort" className="text-slate-300 select-none cursor-pointer">Auto-Sort Hand (Spectrum & Value)</label>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Modals & Overlays */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>
                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Animation Layers */}
      {flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {/* SVG Connection Lines */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500 font-bold" ref={topPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                 Deck: <span className="text-slate-200">{gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
             </div>
             <button onClick={() => setShowMenu(true)} className="p-2 hover:bg-slate-800 rounded-full transition">
                 <Settings size={20} className="text-slate-400" />
             </button>
         </div>
      </div>

      {/* Field Area */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

          {/* Top Player (Opponent) */}
          <div className="flex-1 flex flex-col justify-center p-4 border-b border-slate-800/30 relative">

               {/* Opponent Hand (Top) */}
               <div className="absolute top-[-40px] left-1/2 -translate-x-1/2 flex -space-x-12 scale-75 opacity-70">
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} card={c} showBack size="sm" />)}
               </div>

               {/* Container for Field + Resources */}
               <div className="flex justify-center items-center gap-12 w-full h-full">

                   {/* Lanes */}
                   <div className="flex gap-4">
                       <div className="bg-slate-900/40 p-4 rounded-xl border border-slate-700/50 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                            {/* Black Lane */}
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId} 
                                  isTapped={fc.isTapped}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  orientation="top"
                               />
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-4 rounded-xl border border-red-900/30 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                            {/* Red Lane */}
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  orientation="top"
                               />
                           ))}
                       </div>
                   </div>

                   {/* Opponent Resources (Right) */}
                   <div id={`resource-container-${topPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-3 rounded-lg border border-slate-700/30">
                       <div className="text-[10px] text-slate-500 font-bold uppercase mb-2">Resources</div>
                       <div className="flex flex-col-reverse -space-y-16 scale-75 origin-top">
                           {topPlayer.resources.map(r => (
                               <div key={r.instanceId} className="transition-transform duration-300">
                                   <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" showBack />
                               </div>
                           ))}
                       </div>
                       <div className="text-xs font-bold text-slate-500 mt-12">{topPlayer.resources.length}</div>
                   </div>

               </div>
          </div>

          {/* Bottom Player (You) */}
          <div className="flex-1 flex flex-col justify-center p-4 relative">

               {/* Container for Field + Resources */}
               <div className="flex justify-center items-center gap-12 w-full h-full">

                   {/* Lanes */}
                   <div className="flex gap-4">
                       <div className="bg-slate-900/40 p-4 rounded-xl border border-slate-700/50 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                           {/* Black Lane */}
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                  isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-4 rounded-xl border border-red-900/30 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                           {/* Red Lane */}
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                  isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                   </div>

                   {/* Player Resources (Right) */}
                   <div id={`resource-container-${bottomPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-3 rounded-lg border border-slate-700/30">
                       <div className="text-[10px] text-indigo-400 font-bold uppercase mb-2">Resources</div>
                       <div className="flex flex-col -space-y-16 scale-75 origin-top">
                           {bottomPlayer.resources.map(r => (
                               <div 
                                    key={r.instanceId} 
                                    id={r.instanceId} // Necessary for swap animation lookup
                                    className="transition-transform duration-300 hover:z-10 hover:-translate-x-4 cursor-pointer"
                                    onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}
                               >
                                   <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" />
                               </div>
                           ))}
                       </div>
                       <div className="text-xs font-bold text-indigo-400 mt-12">
                           {bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}
                       </div>
                   </div>

               </div>
          </div>

          {/* Floating Dragged Card */}
          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      {/* Controls */}
      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30">

          {/* Stats */}
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2">
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 uppercase font-bold tracking-wider" ref={bottomPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                  Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
              </div>
          </div>

          {/* Hand */}
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner" ref={handRef}>
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c: Card) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       const isPlayable = isMainPhase && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost;
                       return (
                           <div key={c.id} id={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          {/* Actions Panel */}
          <div className="w-64 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3">
              <div className="text-center text-xs font-bold text-slate-500 uppercase mb-2">Actions</div>

              <div className="flex-1 grid grid-cols-2 gap-2 content-start">
                  {/* Init Phase */}
                  {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button 
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg h-12"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {/* Resource Phase */}
                  {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <ArrowUpCircle size={20} className="mb-1"/> Add & Draw
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <RotateCcw size={20} className="mb-1"/> Swap Res
                        </button>
                      </>
                  )}
                  {/* Resource Select Info */}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                      <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20 h-12">
                          Select card to Add
                      </div>
                  )}
                  {gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && (
                      <div className="col-span-2 text-center text-xs text-amber-400 animate-pulse font-bold flex items-center justify-center border border-amber-900 rounded bg-amber-900/20 h-12">
                          Select Resource to Swap
                      </div>
                  )}

                  {/* Main Phase */}
                  {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2 h-10 transition-transform active:scale-95"
                        >
                            <Sword size={18} /> Attack Phase
                        </button>
                        <button 
                            onClick={requestEndTurn}
                            className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}

                  {/* Combat Phases */}
                  {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12">
                          Confirm Attackers
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">
                          Confirm Blocks
                      </button>
                  )}
              </div>
          </div>
      </div>

      {/* Logs */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40 space-y-1">
          {gameState.logs.map((log: string, i: number) => (
              <div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in">{log}</div>
          ))}
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef, useLayoutEffect } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, X, Check, ArrowRight } from 'lucide-react';

// -- Sub-Components --

const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(1) rotate(0deg)',
        transition: 'transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        // Force reflow
        const deltaX = fc.targetX - fc.startX;
        const deltaY = fc.targetY - fc.startY;

        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                transform: `translate(${deltaX}px, ${deltaY}px) scale(0.6) rotate(360deg)`
            }));
        });
    }, [fc]);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={true} size="md" />
        </div>
    );
};

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [autoSort, setAutoSort] = useState(false);

  // UI Overlays State
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showResignModal, setShowResignModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  // Interaction State
  const [dragState, setDragState] = useState<DragState | null>(null);

  // Animation State
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Refs for tracking DOM positions and State Access
  const gameStateRef = useRef<GameState | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);
  const p0DeckRef = useRef<HTMLDivElement>(null);
  const p1DeckRef = useRef<HTMLDivElement>(null);
  const handRef = useRef<HTMLDivElement>(null);

  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      if (autoSort) {
          hand.splice(0, hand.length, ...sortHand(hand));
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, [autoSort]);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Animation Core --

  const triggerFlyer = async (card: Card, startRect: DOMRect, targetRect: DOMRect): Promise<void> => {
      return new Promise(resolve => {
          const id = generateId();
          const newFly: FlyingCard = {
              id,
              card,
              startX: startRect.left,
              startY: startRect.top,
              targetX: targetRect.left + targetRect.width / 2 - 20, // Center roughly
              targetY: targetRect.top + targetRect.height / 2 - 30,
              createdAt: Date.now()
          };
          setFlyingCards(prev => [...prev, newFly]);
          setTimeout(() => {
              setFlyingCards(prev => prev.filter(f => f.id !== id));
              resolve();
          }, 600);
      });
  };

  // -- Complex Actions (Async) --

  const drawCards = async (playerId: number, count: number) => {
      for (let i = 0; i < count; i++) {
          // Use Ref to get latest state synchronously without waiting for render cycle
          const currentState = gameStateRef.current;
          if (!currentState) return;

          const pIndex = currentState.players.findIndex(p => p.id === playerId);
          const p = currentState.players[pIndex];

          // Determine source deck
          const sourceDeck = currentState.mode === 'STREET' ? currentState.deck : p.library;

          let drawnCard: Card | null = null;

          if (sourceDeck.length > 0) {
              // Peek at the card (it will be at index 0 because we used shift logic previously, but accessing array directly is safer before mutation)
              drawnCard = sourceDeck[0];

              // 1. Update State to Remove Card from Deck
              setGameState(prev => {
                  if (!prev) return null;
                  const nextPlayers = [...prev.players];
                  const nextP = { ...nextPlayers[pIndex] };

                  let nextDeck = prev.deck;
                  if (prev.mode === 'STREET') {
                       nextDeck = [...prev.deck];
                       nextDeck.shift();
                  } else {
                       nextP.library = [...nextP.library];
                       nextP.library.shift();
                  }
                  nextPlayers[pIndex] = nextP;

                  return {
                      ...prev,
                      deck: prev.mode === 'STREET' ? nextDeck : prev.deck,
                      players: nextPlayers,
                      // Reset failure count if successful
                      players: nextPlayers.map(pl => pl.id === playerId ? { ...pl, consecutiveDrawFailures: 0 } : pl) 
                  };
              });

          } else {
              // Handle Empty Deck
              setGameState(prev => {
                   if (!prev) return null;
                   const nextPlayers = prev.players.map(pl => 
                      pl.id === playerId ? { ...pl, consecutiveDrawFailures: pl.consecutiveDrawFailures + 1 } : pl
                   );
                   return { ...prev, players: nextPlayers, logs: addLog(prev, "Deck Empty!") };
              });

              // If both empty (simplified check, real check is in Game Over logic)
              if (currentState.players.every(pl => pl.consecutiveDrawFailures > 0)) {
                  checkGameOver({ ...currentState }); // trigger check
                  return; 
              }
          }

          if (drawnCard) {
              // 2. Animate
               const deckRef = playerId === 0 ? p0DeckRef : p1DeckRef;
               if (deckRef.current && handRef.current) {
                   await triggerFlyer(drawnCard, deckRef.current.getBoundingClientRect(), handRef.current.getBoundingClientRect());
               }

               // 3. Add to Hand
               setGameState(prev => {
                   if (!prev) return null;
                   const nextPlayers = [...prev.players];
                   const nextP = { ...nextPlayers[pIndex] };
                   nextP.hand = [...nextP.hand, drawnCard!];
                   if (autoSort) nextP.hand = sortHand(nextP.hand);
                   nextPlayers[pIndex] = nextP;
                   return { ...prev, players: nextPlayers, logs: addLog(prev, `${nextP.name} drew a card.`) };
               });
          }

          await new Promise(r => setTimeout(r, 200));
      }
  };

  const handleResign = () => {
      if (!gameState) return;
      setGameState(prev => {
          if(!prev) return null;
          // Winner is the opponent of the current turn player (or whoever clicked resign, but we assume active player resigns)
          // Actually, pause menu is global. Let's assume the user (Bottom Player) resigns.
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      setShowResignModal(false);
      setShowMenu(false);
  };

  const toggleAutoSort = () => {
      setAutoSort(prev => !prev);
      // Immediately sort current hand if enabling
      setGameState(prev => {
          if(!prev) return null;
          if (!autoSort) { // If we are turning it ON
             const activePid = getActiveDecisionPlayerId(prev);
             const nextPlayers = [...prev.players];
             nextPlayers[activePid].hand = sortHand(nextPlayers[activePid].hand);
             return { ...prev, players: nextPlayers };
          }
          return prev;
      });
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            setTimeout(() => {
                drawCards(player.id, 1).then(() => {
                     setGameState(current => {
                         if(!current) return null;
                         const p = current.players[current.turnPlayer];
                         const isTurn1Player1 = current.turnCount === 1 && current.turnPlayer === 0;
                         const hasMaxResources = p.resources.length >= MAX_RESOURCES;

                         if (isTurn1Player1 || hasMaxResources) {
                            setTimeout(() => advancePhase(Phase.MAIN), 400);
                            return { 
                                ...current, 
                                phase: Phase.RESOURCE_START, 
                                logs: addLog(current, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached.") 
                            };
                         } else {
                            return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") };
                         }
                     });
                });
            }, 0);
            break;

        case Phase.RESOURCE_START:
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);

    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        const nextState = {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP 
        };

        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return prev; 
    });
  };

  // Async Combat Sequencer
  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          setGameState(prev => {
             if (!prev) return null;
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  // -- Interaction Handlers --

  // (Drag Logic)
  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
      else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
      else { return; }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return;

      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetElement.id === 'field-area' || targetInstanceId) {
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return;
          let targetOwnerId = -1;
          gameState.players.forEach(p => {
              if (p.field.some(f => f.instanceId === targetInstanceId)) targetOwnerId = p.id;
          });
          if (targetOwnerId === -1) return;
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          playCardImmediate(card);
      }
  };

  const playCardImmediate = async (card: Card, targetId?: string, targetOwnerId?: number) => {
       let cardIdx = -1;
       let playedCard: Card | null = null;

       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           // Copy hand
           const newHand = [...p.hand];
           [playedCard] = newHand.splice(cardIdx, 1);

           // Pay Cost
           let toTap = card.cost;
           const newResources = p.resources.map(r => {
               if (!r.isTapped && toTap > 0) {
                   toTap--;
                   return { ...r, isTapped: true };
               }
               return r;
           });

           // Effects
           const nextState = { ...prev, players: [...prev.players] };
           const nextPlayer = { ...p, hand: newHand, resources: newResources };
           nextState.players[prev.turnPlayer] = nextPlayer;

           if (card.rank === 'J') {
               nextPlayer.discard.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Played Jack: Drawing 2...") };
           }
           else if (card.rank === 'K') {
               const targetP = nextState.players[targetOwnerId!];
               const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
               if (targetFIdx === -1) return prev; 
               const targetF = targetP.field[targetFIdx];

               if (getEffectiveColor(targetF) !== card.baseColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") };
               }

               nextPlayer.discard.push(playedCard!);
               targetP.field.splice(targetFIdx, 1);
               targetP.discard.push(targetF.card, ...targetF.attachedCards);
               return { ...nextState, logs: addLog(nextState, "King executed soldier.") };
           }
           else if (card.rank === 'Q') {
               const targetP = nextState.players[targetOwnerId!];
               const targetF = targetP.field.find(f => f.instanceId === targetId);
               if(targetF) targetF.attachedCards.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Queen attached.") };
           }
           else {
               const newSoldier = createFieldCard(playedCard!, p.id);
               nextPlayer.field.push(newSoldier);
               return { ...nextState, logs: addLog(nextState, `Conscripted ${card.rank}.`) };
           }
       });

       // Post-Update Asyncs
       if (card.rank === 'J' && gameState) {
           await drawCards(gameState.turnPlayer, 2);
       }
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];
          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker || blocker.isTapped) return prev;
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          const newBlocks = { ...prev.pendingBlocks };
          newBlocks[blockerInstanceId] = attackerInstanceId;
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          // Animate Hand -> Resource
          const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
          const cardEl = document.getElementById(card.id); 
          if (cardEl && targetResourceContainer) {
              await triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect());
          }

          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Resource Added.") };
          });

          // Draw
          await drawCards(activePlayerId, 1);
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          if (gameState.selectedCardId) {
              const handCardEl = document.getElementById(gameState.selectedCardId);
              const resCardEl = document.getElementById(instanceId!); 
              const handContainer = handRef.current;

              const handCard = gameState.players[activePlayerId].hand.find(c => c.id === gameState.selectedCardId);

              if (handCard && handCardEl && resCardEl && handContainer) {
                  const p1 = triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                  const p2 = triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                  await Promise.all([p1, p2]);
              }
          }

          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
                  if(autoSort) p.hand = sortHand(p.hand);
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      return (
          <div className="flex flex-col items-center justify-center h-screen bg-slate-900 text-white relative">
              <div className="text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <h1 className="text-8xl font-bold font-title bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</h1>
                  <div className="flex gap-4 justify-center">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 hover:bg-indigo-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-indigo-900/50">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 hover:bg-red-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-red-900/50">Play Pro</button>
                  </div>
                  <div className="flex items-center justify-center gap-2 mt-8">
                      <input 
                        type="checkbox" 
                        id="sort" 
                        checked={autoSort} 
                        onChange={(e) => setAutoSort(e.target.checked)}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="sort" className="text-slate-300 select-none cursor-pointer">Auto-Sort Hand (Spectrum & Value)</label>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Modals & Overlays */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showResignModal && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200 border-red-900/50">
                  <h3 className="text-xl font-bold font-title text-red-500 mb-2">Resign Game?</h3>
                  <p className="text-slate-400 mb-6">You will forfeit the match. Are you sure?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowResignModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={handleResign} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Resign</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>

                  <div className="flex items-center justify-center gap-3 bg-slate-800 p-3 rounded-lg">
                      <input 
                        type="checkbox" 
                        id="menuSort" 
                        checked={autoSort} 
                        onChange={toggleAutoSort}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="menuSort" className="text-slate-300 select-none cursor-pointer font-bold text-sm">Auto-Sort Hand</label>
                  </div>

                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>
                  <button onClick={() => setShowResignModal(true)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Resign
                  </button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2">
                      <ArrowRight size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Animation Layers */}
      {flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {/* SVG Connection Lines */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500 font-bold" ref={topPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                 Deck: <span className="text-slate-200">{gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
             </div>
             <button onClick={() => setShowMenu(true)} className="p-2 hover:bg-slate-800 rounded-full transition">
                 <Settings size={20} className="text-slate-400" />
             </button>
         </div>
      </div>

      {/* Field Area */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">

          {/* Top Player (Opponent) */}
          <div className="flex-1 flex flex-col justify-center p-4 border-b border-slate-800/30 relative">

               {/* Opponent Hand (Top) */}
               <div className="absolute top-[-40px] left-1/2 -translate-x-1/2 flex -space-x-4 scale-75 opacity-90 transition-all hover:-space-x-2">
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} card={c} showBack size="sm" />)}
               </div>
               {/* Opponent Card Count Tooltip */}
               <div className="absolute top-4 left-1/2 -translate-x-1/2 text-[10px] font-bold text-slate-500 bg-slate-900/80 px-2 py-1 rounded">
                   Cards: {topPlayer.hand.length}
               </div>

               {/* Container for Field + Resources */}
               <div className="flex justify-center items-center gap-12 w-full h-full">

                   {/* Lanes */}
                   <div className="flex gap-4">
                       <div className="bg-slate-900/40 p-4 rounded-xl border border-slate-700/50 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                            {/* Black Lane */}
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId} 
                                  isTapped={fc.isTapped}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  orientation="top"
                               />
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-4 rounded-xl border border-red-900/30 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                            {/* Red Lane */}
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  orientation="top"
                               />
                           ))}
                       </div>
                   </div>

                   {/* Opponent Resources (Right) */}
                   <div id={`resource-container-${topPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-3 rounded-lg border border-slate-700/30">
                       <div className="text-[10px] text-slate-500 font-bold uppercase mb-2">Resources</div>
                       <div className="flex flex-col-reverse -space-y-8 scale-75 origin-top">
                           {topPlayer.resources.map(r => (
                               <div key={r.instanceId} className="transition-transform duration-300">
                                   <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" showBack={false} />
                               </div>
                           ))}
                       </div>
                       <div className="text-xs font-bold text-slate-500 mt-12">{topPlayer.resources.length}</div>
                   </div>

               </div>
          </div>

          {/* Bottom Player (You) */}
          <div className="flex-1 flex flex-col justify-center p-4 relative">

               {/* Container for Field + Resources */}
               <div className="flex justify-center items-center gap-12 w-full h-full">

                   {/* Lanes */}
                   <div className="flex gap-4">
                       <div className="bg-slate-900/40 p-4 rounded-xl border border-slate-700/50 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                           {/* Black Lane */}
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                  isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-4 rounded-xl border border-red-900/30 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                           {/* Red Lane */}
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  card={fc.card} 
                                  data-instance-id={fc.instanceId}
                                  isTapped={fc.isTapped}
                                  isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                  isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                   </div>

                   {/* Player Resources (Right) */}
                   <div id={`resource-container-${bottomPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-3 rounded-lg border border-slate-700/30">
                       <div className="text-[10px] text-indigo-400 font-bold uppercase mb-2">Resources</div>
                       <div className="flex flex-col -space-y-8 scale-75 origin-top">
                           {bottomPlayer.resources.map(r => (
                               <div 
                                    key={r.instanceId} 
                                    id={r.instanceId} // Necessary for swap animation lookup
                                    className="transition-transform duration-300 hover:z-10 hover:-translate-x-4 cursor-pointer"
                                    onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}
                               >
                                   <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" />
                               </div>
                           ))}
                       </div>
                       <div className="text-xs font-bold text-indigo-400 mt-12">
                           {bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}
                       </div>
                   </div>

               </div>
          </div>

          {/* Floating Dragged Card */}
          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      {/* Controls */}
      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30">

          {/* Stats */}
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2">
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="text-xs text-slate-500 uppercase font-bold tracking-wider" ref={bottomPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                  Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
              </div>
          </div>

          {/* Hand */}
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner" ref={handRef}>
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c: Card) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       const isPlayable = isMainPhase && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost;
                       return (
                           <div key={c.id} id={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          {/* Actions Panel */}
          <div className="w-64 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3">
              <div className="text-center text-xs font-bold text-slate-500 uppercase mb-2">Actions</div>

              <div className="flex-1 grid grid-cols-2 gap-2 content-start">
                  {/* Init Phase */}
                  {gameState.phase === Phase.INIT_SELECT && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button 
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg h-12"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {/* Resource Phase */}
                  {gameState.phase === Phase.RESOURCE_START && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <ArrowUpCircle size={20} className="mb-1"/> Add & Draw
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <RotateCcw size={20} className="mb-1"/> Swap Res
                        </button>
                      </>
                  )}
                  {/* Resource Select Info */}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && (
                      <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20 h-12">
                          Select card to Add
                      </div>
                  )}
                  {gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && (
                      <div className="col-span-2 text-center text-xs text-amber-400 animate-pulse font-bold flex items-center justify-center border border-amber-900 rounded bg-amber-900/20 h-12">
                          Select Resource to Swap
                      </div>
                  )}

                  {/* Main Phase */}
                  {gameState.phase === Phase.MAIN && activeDecisionPlayerId === gameState.turnPlayer && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2 h-10 transition-transform active:scale-95"
                        >
                            <Sword size={18} /> Attack Phase
                        </button>
                        <button 
                            onClick={requestEndTurn}
                            className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}

                  {/* Combat Phases */}
                  {gameState.phase === Phase.ATTACK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12">
                          Confirm Attackers
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId !== gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">
                          Confirm Blocks
                      </button>
                  )}
              </div>
          </div>
      </div>

      {/* Logs */}
      <div className="absolute top-20 left-4 w-72 pointer-events-none z-40 space-y-1">
          {gameState.logs.map((log: string, i: number) => (
              <div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in">{log}</div>
          ))}
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef, useLayoutEffect } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES, STARTING_RESOURCE_COUNT } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, X, Check, ArrowRight } from 'lucide-react';

// -- Sub-Components --

const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(1) rotate(0deg)',
        transition: 'transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        // Force reflow
        const deltaX = fc.targetX - fc.startX;
        const deltaY = fc.targetY - fc.startY;

        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                transform: `translate(${deltaX}px, ${deltaY}px) scale(0.6) rotate(360deg)`
            }));
        });
    }, [fc]);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={true} size="md" />
        </div>
    );
};

const App: React.FC = () => {
  // Game State
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [autoSort, setAutoSort] = useState(false);

  // UI Overlays State
  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showResignModal, setShowResignModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);

  // Interaction State
  const [dragState, setDragState] = useState<DragState | null>(null);

  // Animation State
  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Refs for tracking DOM positions and State Access
  const gameStateRef = useRef<GameState | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null);
  const p0DeckRef = useRef<HTMLDivElement>(null);
  const p1DeckRef = useRef<HTMLDivElement>(null);
  const handRef = useRef<HTMLDivElement>(null);

  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  // -- Initialization --

  const startGame = useCallback((mode: GameMode) => {
    const sharedDeck = mode === 'STREET' ? createDeck() : [];

    const createPlayer = (id: number, name: string): PlayerState => {
      const hand: Card[] = [];
      const resources: FieldCard[] = [];
      const library = mode === 'PRO' ? createDeck() : []; 

      const sourceDeck = mode === 'STREET' ? sharedDeck : library;

      for(let i=0; i<8; i++) {
        const card = sourceDeck.pop();
        if(card) hand.push(card);
      }

      if (autoSort) {
          hand.splice(0, hand.length, ...sortHand(hand));
      }

      return {
        id,
        name,
        life: INITIAL_LIFE,
        hand,
        library,
        resources,
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, "Player 1");
    const p2 = createPlayer(1, "Player 2");

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0,
      phase: Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [`Game Started. Mode: ${mode}. Select 3 starting resources.`]
    };

    setGameState(initialState);
  }, [autoSort]);

  // -- Helpers --

  const addLog = (prev: GameState, message: string): string[] => {
    return [message, ...prev.logs].slice(0, 10);
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.phase === Phase.BLOCK_DECLARE) {
          return state.turnPlayer === 0 ? 1 : 0;
      }
      return state.turnPlayer;
  };

  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;

      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);

      return canPlayCard || canAttack;
  };

  // -- Animation Core --

  const triggerFlyer = async (card: Card, startRect: DOMRect, targetRect: DOMRect): Promise<void> => {
      return new Promise(resolve => {
          const id = generateId();
          const newFly: FlyingCard = {
              id,
              card,
              startX: startRect.left,
              startY: startRect.top,
              targetX: targetRect.left + targetRect.width / 2 - 20, // Center roughly
              targetY: targetRect.top + targetRect.height / 2 - 30,
              createdAt: Date.now()
          };
          setFlyingCards(prev => [...prev, newFly]);
          setTimeout(() => {
              setFlyingCards(prev => prev.filter(f => f.id !== id));
              resolve();
          }, 600);
      });
  };

  // -- Complex Actions (Async) --

  const drawCards = async (playerId: number, count: number) => {
      for (let i = 0; i < count; i++) {
          // Use Ref to get latest state synchronously without waiting for render cycle
          const currentState = gameStateRef.current;
          if (!currentState) return;

          const pIndex = currentState.players.findIndex(p => p.id === playerId);
          const p = currentState.players[pIndex];

          // Determine source deck
          const sourceDeck = currentState.mode === 'STREET' ? currentState.deck : p.library;

          let drawnCard: Card | null = null;

          if (sourceDeck.length > 0) {
              // Peek at the card (it will be at index 0 because we used shift logic previously, but accessing array directly is safer before mutation)
              drawnCard = sourceDeck[0];

              // 1. Update State to Remove Card from Deck
              setGameState(prev => {
                  if (!prev) return null;
                  const nextPlayers = [...prev.players];
                  const nextP = { ...nextPlayers[pIndex] };

                  let nextDeck = prev.deck;
                  if (prev.mode === 'STREET') {
                       nextDeck = [...prev.deck];
                       nextDeck.shift();
                  } else {
                       nextP.library = [...nextP.library];
                       nextP.library.shift();
                  }
                  nextPlayers[pIndex] = nextP;

                  return {
                      ...prev,
                      deck: prev.mode === 'STREET' ? nextDeck : prev.deck,
                      // Reset failure count if successful
                      players: nextPlayers.map(pl => pl.id === playerId ? { ...pl, consecutiveDrawFailures: 0 } : pl) 
                  };
              });

          } else {
              // Handle Empty Deck
              setGameState(prev => {
                   if (!prev) return null;
                   const nextPlayers = prev.players.map(pl => 
                      pl.id === playerId ? { ...pl, consecutiveDrawFailures: pl.consecutiveDrawFailures + 1 } : pl
                   );
                   return { ...prev, players: nextPlayers, logs: addLog(prev, "Deck Empty!") };
              });

              // If both empty (simplified check, real check is in Game Over logic)
              if (currentState.players.every(pl => pl.consecutiveDrawFailures > 0)) {
                  checkGameOver({ ...currentState }); // trigger check
                  return; 
              }
          }

          if (drawnCard) {
              // 2. Animate
               const deckRef = playerId === 0 ? p0DeckRef : p1DeckRef;
               if (deckRef.current && handRef.current) {
                   await triggerFlyer(drawnCard, deckRef.current.getBoundingClientRect(), handRef.current.getBoundingClientRect());
               }

               // 3. Add to Hand
               setGameState(prev => {
                   if (!prev) return null;
                   const nextPlayers = [...prev.players];
                   const nextP = { ...nextPlayers[pIndex] };
                   nextP.hand = [...nextP.hand, drawnCard!];
                   if (autoSort) nextP.hand = sortHand(nextP.hand);
                   nextPlayers[pIndex] = nextP;
                   return { ...prev, players: nextPlayers, logs: addLog(prev, `${nextP.name} drew a card.`) };
               });
          }

          await new Promise(r => setTimeout(r, 200));
      }
  };

  const handleResign = () => {
      if (!gameState) return;
      setGameState(prev => {
          if(!prev) return null;
          // Winner is the opponent of the current turn player (or whoever clicked resign, but we assume active player resigns)
          // Actually, pause menu is global. Let's assume the user (Bottom Player) resigns.
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      setShowResignModal(false);
      setShowMenu(false);
  };

  const toggleAutoSort = () => {
      setAutoSort(prev => !prev);
      // Immediately sort current hand if enabling
      setGameState(prev => {
          if(!prev) return null;
          if (!autoSort) { // If we are turning it ON
             const activePid = getActiveDecisionPlayerId(prev);
             const nextPlayers = [...prev.players];
             nextPlayers[activePid].hand = sortHand(nextPlayers[activePid].hand);
             return { ...prev, players: nextPlayers };
          }
          return prev;
      });
  };

  // -- Phase Management --

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };

      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
            p.field.forEach(c => {
              c.isTapped = false;
              if (p.id === newState.turnPlayer) c.isSummoningSick = false; 
            });
            if (p.id === newState.turnPlayer) {
              p.resources.forEach(r => r.isTapped = false);
            }
          });
          newState.pendingAttackers = [];
          newState.pendingBlocks = {};
          newState.selectedCardId = null;
          newState.recentDamage = {}; 
          newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;

          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;

        case Phase.DRAW:
            setTimeout(() => {
                drawCards(player.id, 1).then(() => {
                     setGameState(current => {
                         if(!current) return null;
                         const p = current.players[current.turnPlayer];
                         const isTurn1Player1 = current.turnCount === 1 && current.turnPlayer === 0;
                         const hasMaxResources = p.resources.length >= MAX_RESOURCES;

                         if (isTurn1Player1 || hasMaxResources) {
                            setTimeout(() => advancePhase(Phase.MAIN), 400);
                            return { 
                                ...current, 
                                phase: Phase.RESOURCE_START, 
                                logs: addLog(current, isTurn1Player1 ? "Turn 1: Resource Step skipped." : "Max Resources reached.") 
                            };
                         } else {
                            return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") };
                         }
                     });
                });
            }, 0);
            break;

        case Phase.RESOURCE_START:
            break;

        case Phase.MAIN:
            newState.logs = addLog(newState, "Main Phase.");
            break;

        case Phase.ATTACK_DECLARE:
            newState.logs = addLog(newState, "Declare Attackers.");
            break;

        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;
      }
      return newState;
    });
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) {
              return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          }

          const p = prev.players[prev.turnPlayer];
          p.field.forEach(f => {
              if (prev.pendingAttackers.includes(f.instanceId)) {
                  f.isTapped = true;
              }
          });
          p.hasAttackedThisTurn = true;

          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const canDefend = defender.field.some(c => !c.isTapped);

          if (!canDefend) {
              return { 
                  ...prev, 
                  phase: Phase.DAMAGE, 
                  logs: addLog(prev, "No defenders available - Direct Hit!") 
              };
          }

          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, "Defender may block.") };
      });
  };

  const confirmBlocks = () => {
      setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null);
  };

  const requestEndTurn = () => {
      setShowEndTurnModal(true);
  };

  const confirmEndTurn = () => {
    setShowEndTurnModal(false);

    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;

        const nextState = {
            ...prev,
            turnPlayer: nextPlayerIdx,
            turnCount: nextTurnCount,
            phase: Phase.UPKEEP 
        };

        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return prev; 
    });
  };

  // Async Combat Sequencer
  useEffect(() => {
      if (gameState?.phase === Phase.DAMAGE) {
          executeCombatSequence();
      }
  }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();

      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));

      for (const atk of attackers) {
          setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
          await new Promise(r => setTimeout(r, 400));

          setGameState(prev => {
             if (!prev) return null;
             const blockerId = Object.keys(prev.pendingBlocks).find(k => prev.pendingBlocks[k] === atk.instanceId);

             const nextRecentDamage = { ...prev.recentDamage };
             let logMsg = "";

             if (blockerId) {
                  const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                      nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                  }
             } else {
                 const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                 spawnFlyingText(`-${dmg}`, 'red', atk.instanceId);
                 logMsg = `${defenderPlayer.name} takes ${dmg} damage!`;
             }

             return { 
                 ...prev, 
                 recentDamage: nextRecentDamage,
                 logs: logMsg ? addLog(prev, logMsg) : prev.logs
             };
          });

          await new Promise(r => setTimeout(r, 800)); // Read time
          setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
          await new Promise(r => setTimeout(r, 100)); // Pause
      }

      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];

          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);

              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue;
                      const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A';
                      const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false;
                      let blkDies = false;

                      if (atkIsAce) blkDies = true;
                      if (blkIsAce) atkDies = true;

                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true;
                          else if (blkVal > atkVal) atkDies = true;
                          else { atkDies = true; blkDies = true; }
                      } else {
                          if(atkIsAce && !blkIsAce) atkDies = true;
                          if(blkIsAce && !atkIsAce) blkDies = true; 
                      }

                      if (atkDies) {
                          atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId);
                          atkP.discard.push(atk.card, ...atk.attachedCards);
                      }
                      if (blkDies) {
                          defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId);
                          defP.discard.push(blk.card, ...blk.attachedCards);
                      }
                  }
              } else {
                  const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
                  defP.life -= dmg;
              }
          });

          nextState.recentDamage = {};
          nextState.pendingAttackers = [];
          nextState.pendingBlocks = {};
          nextState.phase = Phase.MAIN;

          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;

          return nextState;
      });
  };

  const spawnFlyingText = (text: string, color: string, startElId?: string) => {
      const startRect = startElId ? document.getElementById(startElId)?.getBoundingClientRect() : null;
      const startX = startRect ? startRect.left + startRect.width/2 : window.innerWidth / 2;
      const startY = startRect ? startRect.top + startRect.height/2 : window.innerHeight / 2;

      const targetRect = lifeIconRef.current?.getBoundingClientRect();
      const targetX = targetRect ? targetRect.left + targetRect.width/2 : window.innerWidth - 50;
      const targetY = targetRect ? targetRect.top + targetRect.height/2 : 50;

      const newFly: FlyingText = {
          id: generateId(),
          text,
          startX,
          startY,
          targetX,
          targetY,
          color,
          createdAt: Date.now()
      };
      setFlyingTexts(prev => [...prev, newFly]);

      setTimeout(() => {
          setFlyingTexts(prev => prev.filter(f => f.id !== newFly.id));
      }, 1500);
  };

  // -- Interaction Handlers --

  // (Drag Logic)
  useEffect(() => {
      const handleGlobalMouseMove = (e: MouseEvent) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      };

      const handleGlobalMouseUp = (e: MouseEvent) => {
          if (dragState) {
              handleDrop(e, dragState);
              setDragState(null);
          }
      };

      window.addEventListener('mousemove', handleGlobalMouseMove);
      window.addEventListener('mouseup', handleGlobalMouseUp);
      return () => {
          window.removeEventListener('mousemove', handleGlobalMouseMove);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [dragState]);

  const handleDragStart = (e: React.MouseEvent, card: Card, type: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePid = getActiveDecisionPlayerId(gameState);
      if (ownerId !== activePid) return;

      if (gameState.phase === Phase.BLOCK_DECLARE && type === 'FIELD') { /* Allow */ } 
      else if (gameState.phase === Phase.MAIN && type === 'HAND') { /* Allow */ }
      else { return; }

      setDragState({
          cardId: card.id,
          sourceType: type,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
      e.stopPropagation();
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      if (!gameState) return;

      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-instance-id') || el.id === 'field-area');

      if (!targetElement) return;

      if (drag.sourceType === 'HAND' && gameState.phase === Phase.MAIN) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetElement.id === 'field-area' || targetInstanceId) {
             handleCardPlayedViaDrag(drag.cardObj!, targetInstanceId || undefined);
          }
      }
      else if (drag.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE) {
          const targetInstanceId = targetElement.getAttribute('data-instance-id');
          if (targetInstanceId) {
             handleBlockDeclaredViaDrag(drag.instanceId!, targetInstanceId);
          }
      }
  };

  const handleCardPlayedViaDrag = (card: Card, targetInstanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = gameState.turnPlayer;
      const player = gameState.players[activePlayerId];

      const untappedRes = player.resources.filter(r => !r.isTapped).length;
      if (untappedRes < card.cost) {
          setGameState(prev => ({ ...prev!, logs: addLog(prev!, "Not enough resources!") }));
          return;
      }

      if (card.rank === 'Q' || card.rank === 'K') {
          if (!targetInstanceId) return;
          let targetOwnerId = -1;
          gameState.players.forEach(p => {
              if (p.field.some(f => f.instanceId === targetInstanceId)) targetOwnerId = p.id;
          });
          if (targetOwnerId === -1) return;
          playCardImmediate(card, targetInstanceId, targetOwnerId);
      } else {
          playCardImmediate(card);
      }
  };

  const playCardImmediate = async (card: Card, targetId?: string, targetOwnerId?: number) => {
       let cardIdx = -1;
       let playedCard: Card | null = null;

       setGameState(prev => {
           if (!prev) return null;
           const p = prev.players[prev.turnPlayer];
           cardIdx = p.hand.findIndex(c => c.id === card.id);
           if (cardIdx === -1) return prev;

           // Copy hand
           const newHand = [...p.hand];
           [playedCard] = newHand.splice(cardIdx, 1);

           // Pay Cost
           let toTap = card.cost;
           const newResources = p.resources.map(r => {
               if (!r.isTapped && toTap > 0) {
                   toTap--;
                   return { ...r, isTapped: true };
               }
               return r;
           });

           // Effects
           const nextState = { ...prev, players: [...prev.players] };
           const nextPlayer = { ...p, hand: newHand, resources: newResources };
           nextState.players[prev.turnPlayer] = nextPlayer;

           if (card.rank === 'J') {
               nextPlayer.discard.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Played Jack: Drawing 2...") };
           }
           else if (card.rank === 'K') {
               const targetP = nextState.players[targetOwnerId!];
               const targetFIdx = targetP.field.findIndex(f => f.instanceId === targetId);
               if (targetFIdx === -1) return prev; 
               const targetF = targetP.field[targetFIdx];

               if (getEffectiveColor(targetF) !== card.baseColor) {
                   return { ...prev, logs: addLog(prev, "Invalid Target: Color mismatch.") };
               }

               nextPlayer.discard.push(playedCard!);
               targetP.field.splice(targetFIdx, 1);
               targetP.discard.push(targetF.card, ...targetF.attachedCards);
               return { ...nextState, logs: addLog(nextState, "King executed soldier.") };
           }
           else if (card.rank === 'Q') {
               const targetP = nextState.players[targetOwnerId!];
               const targetF = targetP.field.find(f => f.instanceId === targetId);
               if(targetF) targetF.attachedCards.push(playedCard!);
               return { ...nextState, logs: addLog(nextState, "Queen attached.") };
           }
           else {
               const newSoldier = createFieldCard(playedCard!, p.id);
               nextPlayer.field.push(newSoldier);
               return { ...nextState, logs: addLog(nextState, `Conscripted ${card.rank}.`) };
           }
       });

       // Post-Update Asyncs
       if (card.rank === 'J' && gameState) {
           await drawCards(gameState.turnPlayer, 2);
       }
  };

  const handleBlockDeclaredViaDrag = (blockerInstanceId: string, attackerInstanceId: string) => {
      setGameState(prev => {
          if (!prev) return null;
          if (!prev.pendingAttackers.includes(attackerInstanceId)) return prev;

          const defP = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const atkP = prev.players[prev.turnPlayer];
          const blocker = defP.field.find(f => f.instanceId === blockerInstanceId);
          const attacker = atkP.field.find(f => f.instanceId === attackerInstanceId);

          if (!blocker || !attacker || blocker.isTapped) return prev;
          if (!canBlock(attacker, blocker)) {
              return { ...prev, logs: addLog(prev, "Invalid Block: Wrong Spectrum!") };
          }

          const newBlocks = { ...prev.pendingBlocks };
          newBlocks[blockerInstanceId] = attackerInstanceId;
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const removeBlock = (blockerInstanceId: string) => {
      setGameState(prev => {
          if(!prev) return null;
          const newBlocks = { ...prev.pendingBlocks };
          delete newBlocks[blockerInstanceId];
          return { ...prev, pendingBlocks: newBlocks };
      });
  };

  const handleCardClick = async (card: Card, location: 'HAND' | 'RESOURCE' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!gameState) return;
      const activePlayerId = getActiveDecisionPlayerId(gameState);

      if (gameState.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === gameState.turnPlayer) {
          setGameState(prev => {
              if(!prev) return null;
              const isSelected = prev.initSelectedIds.includes(card.id);
              let newIds = isSelected ? prev.initSelectedIds.filter(id => id !== card.id) : [...prev.initSelectedIds, card.id];
              if (newIds.length > 3) newIds.pop();
              return { ...prev, initSelectedIds: newIds };
          });
      }
      else if (gameState.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePlayerId) {
          // Animate Hand -> Resource
          const targetResourceContainer = document.getElementById(`resource-container-${ownerId}`);
          const cardEl = document.getElementById(card.id); 
          if (cardEl && targetResourceContainer) {
              await triggerFlyer(card, cardEl.getBoundingClientRect(), targetResourceContainer.getBoundingClientRect());
          }

          setGameState(prev => {
             if(!prev) return null;
             const p = prev.players[activePlayerId];
             const cardIdx = p.hand.findIndex(c => c.id === card.id);
             const [resCard] = p.hand.splice(cardIdx, 1);
             p.resources.push(createFieldCard(resCard, p.id));

             return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Resource Added.") };
          });

          // Draw
          await drawCards(activePlayerId, 1);
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND && location === 'HAND') {
           setGameState(prev => ({ ...prev!, selectedCardId: card.id, phase: Phase.RESOURCE_SWAP_SELECT_PILE, logs: addLog(prev!, "Select a resource to swap with.") }));
      }
      else if (gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && location === 'RESOURCE') {
          if (gameState.selectedCardId) {
              const handCardEl = document.getElementById(gameState.selectedCardId);
              const resCardEl = document.getElementById(instanceId!); 
              const handContainer = handRef.current;

              const handCard = gameState.players[activePlayerId].hand.find(c => c.id === gameState.selectedCardId);

              if (handCard && handCardEl && resCardEl && handContainer) {
                  const p1 = triggerFlyer(handCard, handCardEl.getBoundingClientRect(), resCardEl.getBoundingClientRect());
                  const p2 = triggerFlyer(card, resCardEl.getBoundingClientRect(), handContainer.getBoundingClientRect());
                  await Promise.all([p1, p2]);
              }
          }

          setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const handIdx = p.hand.findIndex(c => c.id === prev.selectedCardId);
              const resIdx = p.resources.findIndex(c => c.card.id === card.id);
              if(handIdx > -1 && resIdx > -1) {
                  const handCard = p.hand[handIdx];
                  const resFieldCard = p.resources[resIdx];
                  p.hand[handIdx] = resFieldCard.card;
                  p.resources[resIdx] = createFieldCard(handCard, p.id); 
                  if(autoSort) p.hand = sortHand(p.hand);
              }
              return { ...prev, selectedCardId: null, phase: Phase.MAIN, logs: addLog(prev, "Swapped resource.") };
          });
      }
      else if (gameState.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
           setGameState(prev => {
              if(!prev) return null;
              const p = prev.players[activePlayerId];
              const fieldCard = p.field.find(fc => fc.instanceId === instanceId);
              if (!fieldCard || fieldCard.isTapped || fieldCard.isSummoningSick) return prev;
              const isAttacking = prev.pendingAttackers.includes(instanceId!);
              const newPending = isAttacking ? prev.pendingAttackers.filter(id => id !== instanceId) : [...prev.pendingAttackers, instanceId!];
              return { ...prev, pendingAttackers: newPending as string[] };
          });
      }
      else if (gameState.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePlayerId) {
          if (instanceId && gameState.pendingBlocks[instanceId]) {
              removeBlock(instanceId);
          }
      }
  };

  const handleResourceOption = (option: 'ADD' | 'SWAP') => {
      if (!gameState) return;
      if (option === 'ADD') advancePhase(Phase.RESOURCE_ADD_SELECT);
      else advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
  };

  const handleConfirmInitSelection = () => {
       setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[prev.turnPlayer];
          const selectedCards = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const remainingHand = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));
          p.hand = remainingHand;
          selectedCards.forEach(c => { p.resources.push(createFieldCard(c, p.id)); });

          if (prev.turnPlayer === 0) {
              return { ...prev, turnPlayer: 1, initSelectedIds: [], logs: addLog(prev, "Player 1 Ready. Player 2, select resources.") };
          } else {
              const startState = { ...prev, turnPlayer: 0, initSelectedIds: [], phase: Phase.UPKEEP, logs: addLog(prev, "Game On! Player 1 Start.") };
              setTimeout(() => advancePhase(Phase.UPKEEP, startState), 500);
              return startState;
          }
       });
  };

  const checkGameOver = (state: GameState) => {
       if (state.players[0].life <= 0) state.winner = 1;
       else if (state.players[1].life <= 0) state.winner = 0;
       if (state.winner !== null) state.phase = Phase.GAME_OVER;
  };

  const getPhaseName = () => {
    switch(gameState?.phase) {
        case Phase.INIT_SELECT: return "Setup";
        case Phase.RESOURCE_START: return "Resource Step";
        case Phase.MAIN: return "Main Phase";
        case Phase.ATTACK_DECLARE: return "Attack Declare";
        case Phase.BLOCK_DECLARE: return "Block Declare";
        case Phase.DAMAGE: return "Combat";
        default: return gameState?.phase || "";
    }
  };

  // -- Render --

  if (!gameState) {
      return (
          <div className="flex flex-col items-center justify-center h-screen bg-slate-900 text-white relative">
              <div className="text-center space-y-8 animate-in fade-in zoom-in duration-500">
                  <h1 className="text-8xl font-bold font-title bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-red-400">BATTLE</h1>
                  <div className="flex gap-4 justify-center">
                    <button onClick={() => startGame('STREET')} className="bg-indigo-600 hover:bg-indigo-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-indigo-900/50">Play Street</button>
                    <button onClick={() => startGame('PRO')} className="bg-red-600 hover:bg-red-500 px-8 py-4 rounded-xl font-bold text-xl transition transform hover:-translate-y-1 shadow-lg shadow-red-900/50">Play Pro</button>
                  </div>
                  <div className="flex items-center justify-center gap-2 mt-8">
                      <input 
                        type="checkbox" 
                        id="sort" 
                        checked={autoSort} 
                        onChange={(e) => setAutoSort(e.target.checked)}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="sort" className="text-slate-300 select-none cursor-pointer">Auto-Sort Hand (Spectrum & Value)</label>
                  </div>
              </div>
          </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const bottomPlayer = gameState.players[activeDecisionPlayerId];
  const topPlayer = gameState.players[activeDecisionPlayerId === 0 ? 1 : 0];
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) ? '' : 'ring-2 ring-indigo-400 animate-pulse';

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef}>

      {/* Modals & Overlays */}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showResignModal && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200 border-red-900/50">
                  <h3 className="text-xl font-bold font-title text-red-500 mb-2">Resign Game?</h3>
                  <p className="text-slate-400 mb-6">You will forfeit the match. Are you sure?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowResignModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={handleResign} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Resign</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>

                  <div className="flex items-center justify-center gap-3 bg-slate-800 p-3 rounded-lg">
                      <input 
                        type="checkbox" 
                        id="menuSort" 
                        checked={autoSort} 
                        onChange={toggleAutoSort}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="menuSort" className="text-slate-300 select-none cursor-pointer font-bold text-sm">Auto-Sort Hand</label>
                  </div>

                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>
                  <button onClick={() => setShowResignModal(true)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Resign
                  </button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2">
                      <ArrowRight size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Animation Layers */}
      {flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {/* SVG Connection Lines */}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="red"
                        strokeWidth="3"
                        strokeDasharray="10 5"
                        className="animate-pulse"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="yellow" strokeWidth="2" strokeDasharray="5"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {/* Top Bar */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 shadow-lg z-20">
         <div className="flex items-center gap-4">
            <span className="font-title font-bold text-xl">BATTLE</span>
            <div className="text-xs bg-slate-800 px-2 py-1 rounded border border-slate-700">{getPhaseName()}</div>
         </div>
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 text-red-400 font-bold" ref={lifeIconRef}>
                 <Heart size={18} fill="currentColor" /> {topPlayer.life}
             </div>
             <div className="text-xs text-slate-500 font-bold" ref={topPlayer.id === 0 ? p0DeckRef : p1DeckRef}>
                 Deck: <span className="text-slate-200">{gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
             </div>
             <button onClick={() => setShowMenu(true)} className="p-2 hover:bg-slate-800 rounded-full transition">
                 <Settings size={20} className="text-slate-400" />
             </button>
         </div>
      </div>

      {/* Field Area */}
