                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === gameState.turnPlayer && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded animate-pulse shadow-lg shadow-indigo-900/50 h-12">
