import { Card, Suit, Rank, Color, FieldCard, GameState, PlayerState } from './types';
import { CARD_VALUES } from './constants';

// Unique ID generator
export const generateId = () => Math.random().toString(36).substr(2, 9);

export const createDeck = (): Card[] => {
  const suits = [Suit.Spades, Suit.Clubs, Suit.Hearts, Suit.Diamonds];
  const ranks = Object.values(Rank);
  const deck: Card[] = [];

  for (const suit of suits) {
    for (const rank of ranks) {
      const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
      const numericValue = CARD_VALUES[rank];

      // Cost is equal to numeric value, except Ace=1, J=2, Q=3, K=4
      let cost = numericValue;
      if (rank === Rank.Jack) cost = 2;
      if (rank === Rank.Queen) cost = 3;
      if (rank === Rank.King) cost = 4;
      if (rank === Rank.Ace) cost = 1;

      deck.push({
        id: generateId(),
        suit,
        rank,
        numericValue,
        cost,
        baseColor
      });
    }
  }
  return shuffle(deck);
};

export const shuffle = <T>(array: T[]): T[] => {
  let currentIndex = array.length, randomIndex;
  while (currentIndex !== 0) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;
    [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
  }
  return array;
};

// Determine the EFFECTIVE color of a soldier (considering attached Queens)
export const getEffectiveColor = (fieldCard: FieldCard): Color => {
  // If a Queen is attached, the soldier takes the Queen's spectrum
  const attachedQueen = fieldCard.attachedCards.find(c => c.rank === Rank.Queen);
  if (attachedQueen) {
    return attachedQueen.baseColor;
  }
  return fieldCard.card.baseColor;
};

export const canBlock = (attacker: FieldCard, blocker: FieldCard): boolean => {
    // Must be in same lane (Same Effective Color)
    const attackerColor = getEffectiveColor(attacker);
    const blockerColor = getEffectiveColor(blocker);

    // Physical (Black) vs Physical (Black), Magical (Red) vs Magical (Red)
    return attackerColor === blockerColor;
};

export const createFieldCard = (card: Card, ownerId: number): FieldCard => ({
  instanceId: generateId(),
  card,
  ownerId,
  isTapped: false,
  isSummoningSick: true,
  attachedCards: [],
  currentHealth: card.numericValue
});

export const sortHand = (hand: Card[]): Card[] => {
  return [...hand].sort((a, b) => {
    // 1. Sort by Color: Black First, then Red
    if (a.baseColor !== b.baseColor) {
      return a.baseColor === Color.Black ? -1 : 1;
    }
    // 2. Sort by Value: High to Low
    return b.numericValue - a.numericValue;
  });
};

// --- CPU AI LOGIC ---

// Heuristic Weights
const W_CPU_LIFE = 10;
const W_PLAYER_LIFE = -10;
const W_CPU_BOARD_VAL = 15;
const W_PLAYER_BOARD_VAL = -20;
const W_CPU_HAND = 12;
const W_ACE_ON_BOARD = 50;

/**
 * Calculates a 'Board Score' for the CPU based on the provided weights.
 */
const calculateScore = (cpu: PlayerState, player: PlayerState): number => {
    let score = 0;

    // Life
    score += cpu.life * W_CPU_LIFE;
    score += player.life * W_PLAYER_LIFE;

    // Board Presence
    const cpuVal = cpu.field.reduce((acc, f) => acc + f.card.numericValue, 0);
    const playerVal = player.field.reduce((acc, f) => acc + f.card.numericValue, 0);
    score += cpuVal * W_CPU_BOARD_VAL;
    score += playerVal * W_PLAYER_BOARD_VAL;

    // The Ace Factor
    if (cpu.field.some(f => f.card.rank === Rank.Ace)) score += W_ACE_ON_BOARD;

    // Hand Advantage
    score += cpu.hand.length * W_CPU_HAND;

    return score;
};

// Helper for Init Phase
export const getCpuInitSelection = (hand: Card[]): string[] => {
    // Pick 3 cards to resource.
    // Strategy: Resource HIGH COST cards because we can't play them early.
    // Keep LOW COST cards to play immediately.

    const sorted = [...hand].sort((a, b) => b.cost - a.cost); // Descending Cost
    return sorted.slice(0, 3).map(c => c.id);
};

// Helper for Resource Step
export const getCpuResourceDecision = (cpu: PlayerState, turnCount: number): { action: 'ADD' | 'SWAP' | 'SKIP', cardIdToSwap?: string, resourceIdToSwap?: string, cardIdToAdd?: string } => {
    if (cpu.resources.length >= 10) return { action: 'SKIP' };

    // Determine "Stage" of game
    // Early Game (Turns 1-4): Need mana. Resource High Cost stuff if we can't play it, or Low Cost junk if we have enough High Cost?
    // Actually, simple heuristic: 
    // Early: Resource High Cost (can't play yet).
    // Late: Resource Low Cost (useless on board).

    const isEarlyGame = turnCount <= 4;

    const handSorted = [...cpu.hand].sort((a, b) => {
        if (isEarlyGame) {
             return b.cost - a.cost; // Descending Cost (High cost at top)
        } else {
             return a.numericValue - b.numericValue; // Ascending Value (Weakest at top)
        }
    });

    const candidateToAdd = handSorted[0];

    // Swap Logic
    // If we have a very low value card in hand and resources are full-ish, maybe swap?
    // But we are limited to binary choice: ADD or SWAP.
    // Default to ADD unless max resources or specific swap heuristic (omitted for stability for now).

    return { action: 'ADD', cardIdToAdd: candidateToAdd.id };
};

// Helper for Main Phase
export interface CpuAction {
    type: 'PLAY_UNIT' | 'PLAY_TACTIC' | 'END_TURN';
    cardId?: string;
    targetId?: string;
    score: number;
}

export const getBestMainPhaseAction = (gameState: GameState): CpuAction => {
    const cpu = gameState.players[1];
    const player = gameState.players[0];
    const availableRes = cpu.resources.filter(r => !r.isTapped).length;

    // Potential actions
    const possibleActions: CpuAction[] = [];

    // 1. Evaluate playing each card in hand
    cpu.hand.forEach(card => {
        if (card.cost <= availableRes) {
            // -- Play Soldier --
            if (!['J', 'Q', 'K'].includes(card.rank)) {
                // Simulate Score Change:
                // Hand -1 (-12), Board +Value (+15*Val), Ace (+50 if Ace)
                // Note: Resources tap, but we treat them as available for the turn curve
                let scoreDelta = -W_CPU_HAND + (card.numericValue * W_CPU_BOARD_VAL);
                if (card.rank === Rank.Ace) scoreDelta += W_ACE_ON_BOARD;

                possibleActions.push({
                    type: 'PLAY_UNIT',
                    cardId: card.id,
                    score: scoreDelta
                });
            }

            // -- Play King (Removal) --
            else if (card.rank === Rank.King) {
                // Find targets (Player soldiers of same color)
                const targets = player.field.filter(f => getEffectiveColor(f) === card.baseColor);
                targets.forEach(t => {
                    // Score: Hand -1 (-12), Opponent Board -Value (-(-20*Val) = +20*Val)
                    // Priority: Removal of High Value (>7)
                    let scoreDelta = -W_CPU_HAND + (t.card.numericValue * Math.abs(W_PLAYER_BOARD_VAL));

                    if (t.card.numericValue >= 7) scoreDelta += 100; // Artificial priority boost

                    possibleActions.push({
                        type: 'PLAY_TACTIC',
                        cardId: card.id,
                        targetId: t.instanceId,
                        score: scoreDelta
                    });
                });
            }

            // -- Play Queen (Shift) --
            else if (card.rank === Rank.Queen) {
                // Changing color might enable a King kill later or bypass block?
                // Hard to heuristic without deep search.
                // Simple logic: If we have a King in hand that has no targets, and Queen can make a target?
                // For MVP: Randomly low score unless needed.
                const targets = player.field;
                targets.forEach(t => {
                    if (getEffectiveColor(t) !== card.baseColor) {
                         possibleActions.push({
                            type: 'PLAY_TACTIC',
                            cardId: card.id,
                            targetId: t.instanceId,
                            score: 5 // Low priority
                        });
                    }
                });
            }

            // -- Play Jack (Draw 2) --
            else if (card.rank === Rank.Jack) {
                // Hand -1 (+2) = +1 Net card (+12 pts)
                const scoreDelta = -W_CPU_HAND + (2 * W_CPU_HAND);
                possibleActions.push({
                    type: 'PLAY_TACTIC',
                    cardId: card.id,
                    score: scoreDelta
                });
            }
        }
    });

    // Sort by Score desc
    possibleActions.sort((a, b) => b.score - a.score);

    if (possibleActions.length > 0 && possibleActions[0].score > 0) {
        return possibleActions[0];
    }

    return { type: 'END_TURN', score: 0 };
};

// Helper for Attack Phase
export const getCpuAttackers = (gameState: GameState): string[] => {
    const cpu = gameState.players[1];
    const player = gameState.players[0];
    const readyUnits = cpu.field.filter(f => !f.isTapped && !f.isSummoningSick);
    const potentialBlockers = player.field.filter(f => !f.isTapped); // Only untapped can block

    // Lethal Check
    let totalUnblockedDmg = 0;
    // Rough estimate: Assume everything connects
    totalUnblockedDmg = readyUnits.reduce((acc, u) => acc + (u.card.rank === 'A' ? 1 : u.card.numericValue), 0);

    // If strict lethal (even if they block everything possible, we win), just GO
    // This is hard to calc perfectly without knowing blocks.
    // Simplification: If unblocked damage >= life, send all.
    if (totalUnblockedDmg >= player.life && potentialBlockers.length === 0) {
        return readyUnits.map(u => u.instanceId);
    }

    const attackers: string[] = [];

    readyUnits.forEach(attacker => {
        const atkVal = attacker.card.numericValue;
        const atkColor = getEffectiveColor(attacker);

        // Find blockers in lane
        const laneBlockers = potentialBlockers.filter(b => getEffectiveColor(b) === atkColor);

        if (laneBlockers.length === 0) {
            // Free hit
            attackers.push(attacker.instanceId);
        } else {
            // Check if any blocker can kill us for free
            const scaryBlocker = laneBlockers.find(b => b.card.numericValue > atkVal || b.card.rank === Rank.Ace);
            if (!scaryBlocker) {
                // We are safe or trade
                attackers.push(attacker.instanceId);
            } else if (attacker.card.rank === Rank.Ace) {
                // Ace always attacks (Death touch)
                attackers.push(attacker.instanceId);
            }
        }
    });

    return attackers;
};

// Helper for Block Phase
export const getCpuBlocks = (gameState: GameState): Record<string, string> => {
    const cpu = gameState.players[1];
    const player = gameState.players[0];
    const attackers = player.field.filter(f => gameState.pendingAttackers.includes(f.instanceId));
    const blockers = cpu.field.filter(f => !f.isTapped);

    const blocks: Record<string, string> = {}; // blockerId -> attackerId
    const usedBlockers = new Set<string>();

    // Sort attackers by value (threat)
    const sortedAttackers = [...attackers].sort((a, b) => b.card.numericValue - a.card.numericValue);

    sortedAttackers.forEach(atk => {
        const atkVal = atk.card.numericValue;
        const atkColor = getEffectiveColor(atk);

        // Find eligible blockers
        const eligible = blockers.filter(b => 
            !usedBlockers.has(b.instanceId) && getEffectiveColor(b) === atkColor
        );

        if (eligible.length > 0) {
            // 1. Can we kill it for free? (Our Val > Atk Val)
            const freeKiller = eligible.find(b => b.card.numericValue > atkVal && atk.card.rank !== 'A');

            // 2. Can we trade up? (Our Val < Atk Val, but we kill it? No, game rules say higher wins. Equal trades.)
            // Trade: Equal value.
            const trader = eligible.find(b => b.card.numericValue === atkVal);

            // 3. Chump block (We die, they live) - avoid unless life is low?
            // For now, prioritize killing.

            let bestBlocker = freeKiller || trader;

            // Ace Logic: Ace kills anything. Use Ace to kill high value.
            const ace = eligible.find(b => b.card.rank === Rank.Ace);
            if (ace && atkVal >= 7) bestBlocker = ace;

            if (bestBlocker) {
                blocks[bestBlocker.instanceId] = atk.instanceId;
                usedBlockers.add(bestBlocker.instanceId);
            } else if (cpu.life <= 5) {
                // Desperation block
                const chump = eligible.sort((a, b) => a.card.numericValue - b.card.numericValue)[0]; // Lowest value
                if (chump) {
                    blocks[chump.instanceId] = atk.instanceId;
                    usedBlockers.add(chump.instanceId);
                }
            }
        }
    });

    return blocks;
};

