// App.tsx
import React, { useState, useReducer, useEffect } from 'react';

// Define the shape of your game state
interface GameState {
  logs: string[];
  // Other game state properties...
}

// Initial game state (example)
const initialGameState: GameState = {
  logs: [],
  // Initialize other properties...
};

// Action types for the reducer
type GameAction =
  | { type: 'ADD_LOG'; payload: string }
  // | { type: 'OTHER_ACTION'; payload: any } // other actions

// Reducer function to manage state updates
const gameReducer = (state: GameState, action: GameAction): GameState => {
  switch (action.type) {
    case 'ADD_LOG':
      return {
        ...state,
        logs: [...state.logs, action.payload],
      };
    // case 'OTHER_ACTION':
    //   return { ...state, ...action.payload };
    default:
      return state;
  }
};

const LogRenderer: React.FC<{ text: string }> = ({ text }) => {
  const parts = text.split(" ");
  return (
    <div>
      {parts.map((part, index) => (
        <span key={index}>{part} </span>
      ))}
    </div>
  );
};

const App: React.FC = () => {
  const [gameState, dispatch] = useReducer(gameReducer, initialGameState);

  const addLog = (log: string) => {
    dispatch({ type: 'ADD_LOG', payload: log });
  };

  useEffect(() => {
    // Example: add a log when the component mounts
    addLog("Application started.");
  }, []);

  return (
    <div>
      <h1>My Awesome App</h1>
      <div>
        {/* Render logs */}
        {gameState.logs.map((log, index) => (
          <div key={index}>
            <LogRenderer text={String(log)} />
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;
