        if (state !== 'FLY' && state !== 'POP') return;

        const timeout = setTimeout(() => {
            setStyle(prev => ({
                ...prev,
                opacity: 0,
                transform: 'translate(-50%, -50%) scale(0)'
            }));
        }, 400);

        return () => clearTimeout(timeout);
    }, [state]);

    return (
