export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
