export default App;

import { Card, Suit, Rank, Color, FieldCard, PlayerState, GameState, Phase } from './types';
import { CARD_VALUES, MAX_RESOURCES } from './constants';

// Unique ID generator
export const generateId = () => Math.random().toString(36).substr(2, 9);

export const createDeck = (): Card[] => {
  const suits = [Suit.Spades, Suit.Clubs, Suit.Hearts, Suit.Diamonds];
  const ranks = Object.values(Rank);
  const deck: Card[] = [];

  for (const suit of suits) {
    for (const rank of ranks) {
      const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
      const numericValue = CARD_VALUES[rank];

      // Cost is equal to numeric value, except Ace=1, J=2, Q=3, K=4
      let cost = numericValue;
      if (rank === Rank.Jack) cost = 2;
      if (rank === Rank.Queen) cost = 3;
      if (rank === Rank.King) cost = 4;
      if (rank === Rank.Ace) cost = 1;

      deck.push({
        id: generateId(),
        suit,
        rank,
        numericValue,
        cost,
        baseColor
      });
    }
  }
  return shuffle(deck);
};

export const shuffle = <T>(array: T[]): T[] => {
  let currentIndex = array.length, randomIndex;
  while (currentIndex !== 0) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;
    [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
  }
  return array;
};

// Determine the EFFECTIVE color of a soldier (considering attached Queens)
export const getEffectiveColor = (fieldCard: FieldCard): Color => {
  // If a Queen is attached, the soldier takes the Queen's spectrum
  const attachedQueen = fieldCard.attachedCards.find(c => c.rank === Rank.Queen);
  if (attachedQueen) {
    return attachedQueen.baseColor;
  }
  return fieldCard.card.baseColor;
};

export const canBlock = (attacker: FieldCard, blocker: FieldCard): boolean => {
    // Must be in same lane (Same Effective Color)
    const attackerColor = getEffectiveColor(attacker);
    const blockerColor = getEffectiveColor(blocker);

    // Physical (Black) vs Physical (Black), Magical (Red) vs Magical (Red)
    return attackerColor === blockerColor;
};

export const createFieldCard = (card: Card, ownerId: number): FieldCard => ({
  instanceId: generateId(),
  card,
  ownerId,
  isTapped: false,
  isSummoningSick: true,
  attachedCards: [],
  currentHealth: card.numericValue
});

export const sortHand = (hand: Card[]): Card[] => {
  return [...hand].sort((a, b) => {
    // 1. Sort by Color: Black First, then Red
    if (a.baseColor !== b.baseColor) {
      return a.baseColor === Color.Black ? -1 : 1;
    }
    // 2. Sort by Value: High to Low
    return b.numericValue - a.numericValue;
  });
};

// --- CPU Logic ---

export const getCpuInitSelection = (hand: Card[]): string[] => {
  // Sort by value (low to high), pick 3 lowest
  const sorted = [...hand].sort((a, b) => a.numericValue - b.numericValue);
  return sorted.slice(0, 3).map(c => c.id);
};

export const getCpuResourceDecision = (cpu: PlayerState, turnCount: number): { action: 'ADD' | 'SWAP' | 'SKIP', cardIdToAdd?: string } => {
    if (cpu.resources.length >= MAX_RESOURCES) return { action: 'SKIP' };

    const untappedResources = cpu.resources.length;
    const playableCards = cpu.hand.filter(c => c.cost <= untappedResources);

    // Add resource if we can't play much, or early game
    const shouldAdd = (cpu.resources.length < 5 && cpu.hand.length > 2) || playableCards.length < cpu.hand.length / 2;

    if (shouldAdd && cpu.hand.length > 0) {
        const sortedHand = [...cpu.hand].sort((a, b) => a.numericValue - b.numericValue);
        return { action: 'ADD', cardIdToAdd: sortedHand[0].id };
    }
    return { action: 'SKIP' };
};

export const getBestMainPhaseAction = (gameState: GameState): { type: 'PLAY_UNIT' | 'PLAY_TACTIC' | 'END_TURN', cardId?: string, targetId?: string } => {
    const cpu = gameState.players[1];
    const opponent = gameState.players[0];
    const availableResources = cpu.resources.filter(r => !r.isTapped).length;
    const playable = cpu.hand.filter(c => c.cost <= availableResources);

    if (playable.length === 0) return { type: 'END_TURN' };

    // Sort: High Value First
    playable.sort((a, b) => b.numericValue - a.numericValue);

    // 1. TACTICS
    const kings = playable.filter(c => c.rank === Rank.King);
    for (const king of kings) {
        const target = opponent.field.find(f => getEffectiveColor(f) === king.baseColor);
        if (target) return { type: 'PLAY_TACTIC', cardId: king.id, targetId: target.instanceId };
    }

    const queens = playable.filter(c => c.rank === Rank.Queen);
    for (const queen of queens) {
        if (cpu.field.length > 0) {
             // Buff highest value unit
             const target = cpu.field.sort((a, b) => b.card.numericValue - a.card.numericValue)[0];
             return { type: 'PLAY_TACTIC', cardId: queen.id, targetId: target.instanceId };
        }
    }

    const jacks = playable.filter(c => c.rank === Rank.Jack);
    if (jacks.length > 0) return { type: 'PLAY_TACTIC', cardId: jacks[0].id };

    // 2. UNITS
    const units = playable.filter(c => !['J', 'Q', 'K'].includes(c.rank));
    if (units.length > 0) return { type: 'PLAY_UNIT', cardId: units[0].id };

    return { type: 'END_TURN' };
};

export const getCpuAttackers = (gameState: GameState): string[] => {
    const cpu = gameState.players[1];
    const opponent = gameState.players[0];
    const potential = cpu.field.filter(f => !f.isTapped && !f.isSummoningSick);
    const attackers: string[] = [];
    const blockers = opponent.field.filter(f => !f.isTapped);

    for (const atk of potential) {
        const atkColor = getEffectiveColor(atk);
        const canBeBlocked = blockers.some(b => getEffectiveColor(b) === atkColor);

        if (!canBeBlocked) {
            attackers.push(atk.instanceId);
            continue;
        }

        // Attack if Value >= 6 or Ace
        if (atk.card.numericValue >= 6 || atk.card.rank === Rank.Ace) {
            attackers.push(atk.instanceId);
        }
    }
    return attackers;
};

export const getCpuBlocks = (gameState: GameState): Record<string, string> => {
    const blocks: Record<string, string> = {};
    const cpu = gameState.players[1];
    const opponent = gameState.players[0];
    const attackerIds = gameState.pendingAttackers;

    const attackers = opponent.field.filter(f => attackerIds.includes(f.instanceId));
    const myBlockers = cpu.field.filter(f => !f.isTapped);
    const usedBlockers = new Set<string>();

    // Sort attackers high to low
    attackers.sort((a, b) => b.card.numericValue - a.card.numericValue);

    for (const atk of attackers) {
        const validBlockers = myBlockers.filter(b => !usedBlockers.has(b.instanceId) && canBlock(atk, b));

        if (validBlockers.length > 0) {
            // Try to win first
            let chosen = validBlockers.find(b => b.card.numericValue > atk.card.numericValue);

            // Or trade
            if (!chosen) chosen = validBlockers.find(b => b.card.numericValue === atk.card.numericValue);

            // Or sacrifice cheap unit for Ace
            if (!chosen && atk.card.rank === Rank.Ace) {
                 validBlockers.sort((a,b) => a.card.numericValue - b.card.numericValue);
                 chosen = validBlockers[0];
            }

            if (chosen) {
                blocks[chosen.instanceId] = atk.instanceId;
                usedBlockers.add(chosen.instanceId);
            }
        }
    }
    return blocks;
};

import React, { useState, useEffect, useCallback, useRef, useLayoutEffect } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard, Rank } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand, getCpuInitSelection, getCpuResourceDecision, getBestMainPhaseAction, getCpuAttackers, getCpuBlocks } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, ArrowRight, Skull, User, Cpu, Users, Coins } from 'lucide-react';

// -- Sub-Components --

const CoinFlipOverlay: React.FC<{ onComplete: (winner: number) => void, p1Name: string, p2Name: string }> = ({ onComplete, p1Name, p2Name }) => {
    const [rotation, setRotation] = useState(0);
    const [resultText, setResultText] = useState("Flipping...");

    useEffect(() => {
        const winner = Math.random() > 0.5 ? 0 : 1;
        // Spin 5 times (1800deg) + winner offset (0 for P1, 180 for P2)
        // Note: P1 is Front (0deg), P2 is Back (180deg)
        const target = 1800 + (winner === 1 ? 180 : 0);

        requestAnimationFrame(() => {
            setRotation(target);
        });

        const spinDuration = 2000;
        const resultDuration = 1500;

        setTimeout(() => {
            setResultText(winner === 0 ? `${p1Name} Goes First!` : `${p2Name} Goes First!`);
            setTimeout(() => {
                onComplete(winner);
            }, resultDuration);
        }, spinDuration);
    }, []);

    return (
        <div className="fixed inset-0 z-[150] bg-slate-900/90 flex flex-col items-center justify-center">
            <div 
                className="relative w-48 h-48 transition-all duration-[2000ms] ease-out"
                style={{ transform: `rotateY(${rotation}deg)`, transformStyle: 'preserve-3d' }}
            >
                 {/* Heads / P1 */}
                 <div className="absolute inset-0 bg-gradient-to-br from-amber-300 to-amber-600 rounded-full border-4 border-amber-700 flex flex-col items-center justify-center backface-hidden shadow-[0_0_50px_rgba(245,158,11,0.5)]" style={{ backfaceVisibility: 'hidden' }}>
                    <User size={48} className="text-amber-900 mb-2" />
                    <span className="font-black text-amber-900 text-3xl drop-shadow-sm">{p1Name}</span>
                 </div>

                 {/* Tails / P2 */}
                 <div className="absolute inset-0 bg-gradient-to-br from-slate-300 to-slate-500 rounded-full border-4 border-slate-700 flex flex-col items-center justify-center backface-hidden shadow-[0_0_50px_rgba(100,116,139,0.5)]" style={{ transform: 'rotateY(180deg)', backfaceVisibility: 'hidden' }}>
                    {p2Name === 'CPU' ? <Cpu size={48} className="text-slate-900 mb-2" /> : <Users size={48} className="text-slate-900 mb-2" />}
                    <span className="font-black text-slate-900 text-3xl drop-shadow-sm">{p2Name}</span>
                 </div>
            </div>

            <div className="mt-16 text-3xl font-bold text-white animate-bounce">
                {resultText}
            </div>
        </div>
    );
};

const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(1) rotate(0deg)',
        transition: 'transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        const deltaX = fc.targetX - fc.startX;
        const deltaY = fc.targetY - fc.startY;

        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                transform: `translate(${deltaX}px, ${deltaY}px) scale(0.6) rotate(360deg)`
            }));
        });
    }, [fc]);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={true} size="md" />
        </div>
    );
};

