const DamageOverlay: React.FC<{ dmg: number, state: 'POP' | 'FLY', targetRef: React.RefObject<HTMLDivElement> }> = ({ dmg, state, targetRef }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
