};

const CoinFlipOverlay: React.FC<{ onComplete: (winner: number) => void, p1Name: string, p2Name: string }> = ({ onComplete, p1Name, p2Name }) => {
    const [rotation, setRotation] = useState(0);
    const [resultText, setResultText] = useState("Flipping...");

    useEffect(() => {
        const winner = Math.random() > 0.5 ? 0 : 1;
        // Spin 5 times (1800deg) + winner offset (0 for P1, 180 for P2)
        // Note: P1 is Front (0deg), P2 is Back (180deg)
        const target = 1800 + (winner === 1 ? 180 : 0);

        requestAnimationFrame(() => {
            setRotation(target);
        });

        const spinDuration = 2000;
        const resultDuration = 1500;

        setTimeout(() => {
            setResultText(winner === 0 ? `${p1Name} Goes First!` : `${p2Name} Goes First!`);
            setTimeout(() => {
                onComplete(winner);
            }, resultDuration);
        }, spinDuration);
    }, []);

    return (
        <div className="fixed inset-0 z-[150] bg-slate-900/90 flex flex-col items-center justify-center">
            <div 
                className="relative w-48 h-48 transition-all duration-[2000ms] ease-out"
                style={{ transform: `rotateY(${rotation}deg)`, transformStyle: 'preserve-3d' }}
            >
                 {/* Heads / P1 */}
                 <div className="absolute inset-0 bg-gradient-to-br from-amber-300 to-amber-600 rounded-full border-4 border-amber-700 flex flex-col items-center justify-center backface-hidden shadow-[0_0_50px_rgba(245,158,11,0.5)]" style={{ backfaceVisibility: 'hidden' }}>
                    <User size={48} className="text-amber-900 mb-2" />
                    <span className="font-black text-amber-900 text-3xl drop-shadow-sm">{p1Name}</span>
                 </div>

                 {/* Tails / P2 */}
                 <div className="absolute inset-0 bg-gradient-to-br from-slate-300 to-slate-500 rounded-full border-4 border-slate-700 flex flex-col items-center justify-center backface-hidden shadow-[0_0_50px_rgba(100,116,139,0.5)]" style={{ transform: 'rotateY(180deg)', backfaceVisibility: 'hidden' }}>
                    {p2Name === 'CPU' ? <Cpu size={48} className="text-slate-900 mb-2" /> : <Users size={48} className="text-slate-900 mb-2" />}
                    <span className="font-black text-slate-900 text-3xl drop-shadow-sm">{p2Name}</span>
                 </div>
            </div>

            <div className="mt-16 text-3xl font-bold text-white animate-bounce">
                {resultText}
            </div>
        </div>
    );
};

const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(1) rotate(0deg)',
        transition: 'transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        const deltaX = fc.targetX - fc.startX;
        const deltaY = fc.targetY - fc.startY;

        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                transform: `translate(${deltaX}px, ${deltaY}px) scale(0.6) rotate(360deg)`
            }));
        });
    }, [fc]);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={true} size="md" />
        </div>
    );
};

