              </div>
              <button className="mt-8 px-6 py-2 bg-slate-800 rounded-full text-sm font-bold border border-slate-700">Close</button>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[160] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-4">PAUSED</h2>
                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2"><Play size={18} /> Resume</button>
                  <button onClick={() => setShowResignModal(true)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900"><LogOut size={18} /> Resign</button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2">Quit</button>
              </div>
          </div>
      )}

      {showEndTurnModal && (
          <div className="absolute inset-0 z-[170] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full mx-4">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <div className="flex gap-3 justify-end mt-6">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showResignModal && (
          <div className="absolute inset-0 z-[180] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full mx-4">
                  <h3 className="text-xl font-bold font-title text-red-500 mb-2">Resign?</h3>
                  <div className="flex gap-3 justify-end mt-6">
                      <button onClick={() => setShowResignModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={handleResign} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Resign</button>
                  </div>
              </div>
          </div>
      )}

      {kingAnim && <KingSlamAnimation card={kingAnim.card} targetRect={kingAnim.targetRect} onComplete={() => setKingAnim(null)} />}
      {flyingCards.map(fc => <Flyer key={fc.id} fc={fc} />)}
      {explosions.map(e => <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => setExplosions(prev => prev.filter(x => x.id !== e.id))} />)}
      {damageAnim && <DamageOverlay dmg={damageAnim.val} state={damageAnim.state} targetRef={damageAnim.playerId === topPlayer.id ? lifeIconRef : bottomLifeRef} />}

      {/* Targeting Line Visual Feedback for Blocking */}
      {dragState && dragState.sourceType === 'FIELD' && gameState.phase === Phase.BLOCK_DECLARE && (
          <svg className="fixed inset-0 pointer-events-none z-[190] w-full h-full">
              <defs>
                  <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="10" refY="3.5" orientation="auto">
                      <polygon points="0 0, 10 3.5, 0 7" fill="rgba(59, 130, 246, 0.8)" />
                  </marker>
              </defs>
              <line 
                  x1={dragState.startX} 
                  y1={dragState.startY} 
                  x2={dragState.currentX} 
                  y2={dragState.currentY} 
                  stroke="rgba(59, 130, 246, 0.6)" 
                  strokeWidth="4" 
                  strokeDasharray="8,4"
                  markerEnd="url(#arrowhead)"
              />
          </svg>
      )}

      {/* Game Layout */}
      {/* Header */}
      <div className="flex justify-between items-center px-4 py-2 bg-slate-900 border-b border-slate-800 z-50 flex-none h-12">
         <div className="flex items-center gap-2">
            <span className="font-title font-bold text-base sm:text-xl hidden xs:block">BATTLE</span>
            <div className="text-[10px] sm:text-xs bg-slate-800 px-2 py-0.5 rounded border border-slate-700">{getPhaseName()}</div>
         </div>

         {/* Mobile Opponent HUD Integration */}
         {isMobile && (
             <div className="flex items-center gap-1.5 bg-black/30 px-2 py-1 rounded-full border border-slate-700/50">
                 <span className="text-[10px] font-black text-indigo-400">T{gameState.turnCount}</span>
                 <div className="w-[1px] h-3 bg-slate-700"></div>
                 <div className="flex items-center gap-1 text-red-400 font-bold" ref={lifeIconRef}>
                     <Heart size={12} fill="currentColor" />
                     <span className="text-xs">{topPlayer.life}</span>
                 </div>
                 <div className="w-[1px] h-3 bg-slate-700"></div>
                 <div className="flex items-center gap-1 text-slate-400 font-bold" ref={topDeckRef}>
                     <Layers size={10} />
                     <span className="text-[10px]">{gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
                 </div>
             </div>
         )}

         <div className="flex items-center gap-1 sm:gap-6">
             <button onClick={() => setShowLogOverlay(true)} className="p-2 hover:bg-slate-800 rounded-full md:hidden"><MessageSquare size={16} /></button>
             <button onClick={() => setShowMenu(true)} className="p-2 hover:bg-slate-800 rounded-full transition"><Settings size={18} className="text-slate-400" /></button>
         </div>
      </div>

      {/* Battlefield */}
      <div id="field-area" className="flex-1 flex flex-col relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] p-1 overflow-hidden">

          {/* Top Player Field Area */}
          <div className="flex-1 flex flex-col justify-center relative border-b border-slate-800/30">
               {/* Top Hand Placeholder */}
               <div className="absolute top-[-20px] sm:top-[-40px] left-1/2 -translate-x-1/2 flex -space-x-4 scale-50 sm:scale-75 opacity-70 cursor-pointer active:opacity-100" ref={cpuHandRef} onClick={() => isMobile && setShowOpponentHand(true)}>
                   {topPlayer.hand.map(c => <CardDisplay key={c.id} domId={c.id} card={c} showBack size="sm" />)}
                   {isMobile && <div className="absolute inset-0 flex items-center justify-center"><Eye size={16} className="text-white opacity-40" /></div>}
               </div>

               <div className="flex flex-col items-center justify-center gap-2 sm:gap-8 w-full h-full px-2">
                   <div className="flex gap-2 sm:gap-4 w-full justify-center">
                       {/* Top Lanes - Fixed Wrapping */}
                       <div className="bg-slate-900/40 p-2 rounded-xl border border-slate-700/50 grid grid-cols-3 gap-1 min-w-[80px] min-h-[100px] justify-items-center shadow-inner overflow-y-auto max-w-[48%]">
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay key={fc.instanceId} domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} size={isMobile ? 'sm' : 'md'} isLunging={gameState.activeCombatCardId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} orientation="top"/>
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-2 rounded-xl border border-red-900/30 grid grid-cols-3 gap-1 min-w-[80px] min-h-[100px] justify-items-center shadow-inner overflow-y-auto max-w-[48%]">
                            {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay key={fc.instanceId} domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} size={isMobile ? 'sm' : 'md'} isLunging={gameState.activeCombatCardId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} orientation="top"/>
                           ))}
                       </div>
                       {/* Top Resources Compact */}
                       <div id={`resource-container-${topPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-1 rounded-lg border border-slate-700/30 shrink-0 self-center">
                           <div className={`grid grid-flow-col grid-rows-2 -space-x-10 sm:-space-x-20 origin-center ${isMobile ? 'scale-[0.35]' : 'scale-[0.5]'}`}>
                                 {topPlayer.resources.map((r, i) => <CardDisplay key={r.instanceId} card={r.card} isTapped={r.isTapped} size="md" />)}
                           </div>
                           <div className="text-[8px] font-bold text-slate-500 mt-[-5px] sm:mt-0">{topPlayer.resources.length}</div>
                        </div>
                   </div>
               </div>
          </div>

          {/* Bottom Player Field Area */}
          <div className="flex-1 flex flex-col justify-center relative">
               <div className="flex flex-col items-center justify-center gap-2 sm:gap-8 w-full h-full px-2">
                   <div className="flex gap-2 sm:gap-4 w-full justify-center">
                       {/* Bottom Lanes - Fixed Wrapping */}
                       <div className="bg-slate-900/40 p-2 rounded-xl border border-slate-700/50 grid grid-cols-3 gap-1 min-w-[80px] min-h-[100px] justify-items-center shadow-inner overflow-y-auto max-w-[48%]">
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                               <CardDisplay key={fc.instanceId} domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} size={isMobile ? 'sm' : 'md'} isAttacking={gameState.pendingAttackers.includes(fc.instanceId)} isBlocking={!!gameState.pendingBlocks[fc.instanceId]} isLunging={gameState.activeCombatCardId === fc.instanceId} isDragging={dragState?.instanceId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} onTouchStart={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick} orientation="bottom"/>
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-2 rounded-xl border border-red-900/30 grid grid-cols-3 gap-1 min-w-[80px] min-h-[100px] justify-items-center shadow-inner overflow-y-auto max-w-[48%]">
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay key={fc.instanceId} domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} size={isMobile ? 'sm' : 'md'} isAttacking={gameState.pendingAttackers.includes(fc.instanceId)} isBlocking={!!gameState.pendingBlocks[fc.instanceId]} isLunging={gameState.activeCombatCardId === fc.instanceId} isDragging={dragState?.instanceId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} onTouchStart={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick} orientation="bottom"/>
                           ))}
                       </div>
                       {/* Bottom Resources grid */}
                       <div id={`resource-container-${bottomPlayer.id}`} className="flex flex-col gap-1 items-center bg-black/20 p-1 rounded-lg border border-slate-700/30 shrink-0 self-center">
                           <div className={`grid grid-flow-col grid-rows-2 -space-x-10 sm:-space-x-20 origin-center ${isMobile ? 'scale-[0.35]' : 'scale-[0.5]'}`}>
                                 {bottomPlayer.resources.map((r, i) => <div key={r.instanceId} id={r.instanceId} onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}><CardDisplay card={r.card} isTapped={r.isTapped} size="md" /></div>)}
                           </div>
                           <div className="text-[8px] font-bold text-indigo-400 mt-[-5px] sm:mt-0">{bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}</div>
                       </div>
                   </div>
               </div>
          </div>
      </div>

      {/* HUD Bottom */}
      <div className={`flex flex-col sm:flex-row ${isMobile ? 'h-36' : 'h-56'} bg-slate-900 border-t border-slate-800 z-[100]`}>

          {/* Status Panel (Desktop left, Mobile bottom bar) */}
